INSERT INTO `board_of_directors` (`id`, `title`, `full_name`, `designation`, `short_description`, `full_biography`, `experience`, `achievements`, `image`, `sort_order`, `is_active`, `is_chairman`, `created_at`, `updated_at`) VALUES
(1, 'Mr.', 'Abdul Majid Khan', 'Minister Finance & Cooperatives / Chairman BAJK', 'Khan Abdul Majid Khan is currently Minister for Finance & Cooperatives of the State of AJ&K and is also Chairman Board of Directors of Bank of Azad Jammu and Kashmir.', 'Khan Abdul Majid Khan is currently Minister for Finance & Cooperatives of the State of AJ&K and is also Chairman Board of Directors of Bank of Azad Jammu and Kashmir. Mr. Khan belongs to a respectable and reputable family having deep political links to Pakistan/Kashmir politics since time tracing back to independence days. Having diverse political career and experience with more than 16 years of struggle in the political arena of Azad Jammu & Kashmir he successfuly elected for four successive times by winning four consecutive AJK General Elections since 2006. Khan Abdul Majid Khan holds a Bachelors degree of Political Science, History and also LLB from University of Punjab. Previously, the Honorable Minister also successfully handled the portfolio of Rehabilitation, AKMIDC, Population Welfare, Information (Media), Agriculture, Livestock & Minerals in Govt. of AJK. He also remained Advisor to Prime Minister AJK on TEVTA and Information Technology. Mr. Khan has represented Kashmir issue at various international forums such as European Parliament, House of Lords, UK and Human Rights Commission. He also was part of dialogue on Kashmir issue in USA, Turkey and France. Mr. Khan being a young and energetic political figure also remained member of major Standing Committees of AJ&K Assembly pertaining to Finance, Planning & Development, LG&RD, S&GAD, C&W, Law, Food Department and also Public Accounts Committee (PAC), GoAJ&K. He also chaired Higher Education Commission, GoAJ&K.', '[\"Minister Finance & Cooperatives, State of AJ&K\",\"Chairman Board of Directors, Bank of Azad Jammu & Kashmir\",\"Four consecutive AJK General Elections winner since 2006\",\"Previously handled portfolios: Rehabilitation, AKMIDC, Population Welfare, Information, Agriculture, Livestock & Minerals\",\"Advisor to Prime Minister AJK on TEVTA and Information Technology\",\"Chairman Higher Education Commission, GoAJ&K\"]', '[\"Represented Kashmir issue at European Parliament, House of Lords, UK\",\"Part of dialogue on Kashmir issue in USA, Turkey and France\",\"Member of major Standing Committees of AJ&K Assembly\",\"Member of Public Accounts Committee (PAC), GoAJ&K\",\"Bachelors degree in Political Science, History and LLB from University of Punjab\"]', 'bod/chairman.jpg', 1, 0, 1, '2025-07-17 08:08:32', '2025-12-01 11:20:19'),
(2, 'Mr.', 'Shahid Shahzad Mir', 'President/CEO', 'Mr. Shahid Shahzad Mir is a seasoned banking professional with an illustrious career spanning several key leadership roles within the financial sector.', 'Mr. Shahid Shahzad Mir is a seasoned banking professional with an illustrious career spanning several key leadership roles within the financial sector. Currently serving as the Executive Vice President and Chief Financial Officer (CFO) of The Bank of Azad Jammu & Kashmir, he brings a wealth of expertise in financial management, strategic leadership, and executive decision-making. Mr. Shahid Shahzad Mir commenced his journey with the Bank of Azad Jammu & Kashmir in 2006, initially joining as an OG-II. Through his unwavering commitment and diligent efforts, he progressively earned promotions within the organization. In 2014, in recognition of his hard work and dedication, Mr. Mir achieved the esteemed position of Divisional Head of the Financial Control Division and Treasury. Prior to joining Bank of AJK, he remained associated with Sehgal Group of Industries, Pakistan\'s one of the most reputed Business Group as Manager Finance. He has been looking after the Financial Control and Treasury Management of the Bank, playing a pivotal role in shaping and executing the bank\'s financial strategies. In addition to his core financial responsibilities, he holds significant leadership roles within the Bank. As Head of Finance & Treasury at the Head Office, he demonstrated exceptional financial acumen. His role extended to treasury functions, where he effectively managed day-to-day operations, investments in various financial instruments, and ensured robust and fund management. His meticulous approach to financial governance is evident from the Profitability of the Bank, which has been sky rocketed through viable investments. Mr. Shahid Shahzad Mir beings with him ample knowledge and experience of Commercial and Retail Banking, and in his previous role in the field of Business, he provided inspirational leadership ensuring the successful delivery of business plans. His academic journey reflects a commitment to continuous learning and professional development. Holding a Master\'s degree in Economics, and MBA in Finance, he has also earned diplomas and certifications in Islamic Banking and Finance and certified Islamic Fund Manager, further enhancing his expertise in this specialized domain. Recently assuming the charge of Acting President/CEO, Mr. Shahid Shahzad Mir  brings a visionary approach to his leadership. Known for his strategic thinking and commitment to excellence, he is poised to steer The Bank of Azad Jammu & Kashmir towards new heights. His extensive experience, coupled with a comprehensive understanding of financial dynamics, positions him as a dynamic and capable leader ready to navigate the bank through evolving challenges and opportunities. Mr. Shahid Shahzad Mir\'s leadership philosophy revolves around fostering a culture of innovation, collaboration, and customer-centricity. As Acting President/CEO, he is dedicated to upholding the bank\'s legacy of trust, transparency, and service excellence, ensuring the continued success and growth of The Bank of Azad Jammu & Kashmir.', '[\"Executive Vice President and CFO at Bank of Azad Jammu & Kashmir\",\"Divisional Head of Financial Control Division and Treasury (2014)\",\"Manager Finance at Sehgal Group of Industries\",\"Progressive career growth from OG-II since 2006\"]', '[\"Recently appointed as Acting President\\/CEO\",\"Significantly increased bank profitability through strategic investments\",\"Successfully managed treasury operations and fund management\",\"Master\'s degree in Economics and MBA in Finance\",\"Certified Islamic Fund Manager and Islamic Banking specialist\"]', 'bod/president.png', 2, 0, 0, '2025-07-17 08:08:32', '2026-09-02 09:50:36'),
(3, 'Mr.', 'Islam Zaib', 'Secretary Finance Government of AJK, Director', 'Mr. Islam Zaib, currently posted as Secretary Finance Government of AJK, is a Federal Civil Servant from Pakistan Administrative Service (PAS).', 'Mr. Islam Zaib, currently posted as Secretary Finance Government of AJK, is a Federal Civil Servant from Pakistan Administrative Service (PAS). He has over twenty-two years of work experience at different key positions in the Federal Government, the Provincial Government of Khyber Pakhtunkhwa (KP) and erstwhile FATA (Federally Administered Tribal Areas). His professional career includes both field and secretariat level positions in different public sector organizations. He has worked in areas of Immigration & Passport, Economic Affairs, Planning & Development, Public Financial Management (PFM), Law Enforcement, Governance including Local Governance, Public Policy and Service Delivery at National, Provincial and District levels. Having experience of working with different tiers of the Government, Mr. Zaib is well versed with the procedures at all levels of the Government and the Parliamentary Affairs. Mr. Islam Zaib is a fellow of Hubert H. Humphrey in Public Policy Analysis and Public Administration from University of Syracuse, New York State. He also holds a certificate of Advanced Studies in Public Administration from Maxwell School of Citizenship, University of Syracuse, New York State and MBA (Public Service) – International Department for Development (IDD) from University of Birmingham, United Kingdom.', '[\"Secretary Finance Government of AJK\",\"Federal Civil Servant from Pakistan Administrative Service (PAS)\",\"Over 22 years experience in Federal and Provincial Government\",\"Worked in Immigration & Passport, Economic Affairs, Planning & Development\",\"Experience in Public Financial Management and Law Enforcement\"]', '[\"Fellow of Hubert H. Humphrey in Public Policy Analysis - University of Syracuse\",\"Certificate of Advanced Studies in Public Administration - Maxwell School\",\"MBA (Public Service) from University of Birmingham, UK\",\"Extensive experience in governance at National, Provincial and District levels\"]', 'bod/mr islam zaib.png', 3, 0, 0, '2025-07-17 08:08:32', '2026-01-28 07:58:37'),
(4, 'Mr.', 'Muhammad Sajjad', 'Secretary Law Justice, Parliamentary Affairs & Human Rights Department', 'Mr. Muhammad Sajjad started his Career as Civil Judge in 2006 with a passion for fair and efficient dispute resolution.', 'Mr. Muhammad Sajjad started his Career as Civil Judge in 2006 with a passion for fair and efficient dispute resolution, proficient for applying the law to uphold justice. In 2021, promoted to the esteemed position of District & Sessions Judge, unveil his experience and expertise in the Legal Domain. Mr. Muhammad Sajjad served in three Division of Azad Kashmir District Haveli, Kotli and Muzaffarabad. Due to his diverse legal capabilities he had honor to serve as Judge Ehtesab Court Mirpur in 2023, having powers of Banking Court. From March 2024 his services has been hired by the Government of AJ&K as Secretary Law, Justice, Parliamentary Affairs and Human Rights.', '[\"Secretary Law, Justice, Parliamentary Affairs & Human Rights (March 2024)\",\"Judge Ehtesab Court Mirpur (2023) with Banking Court powers\",\"District & Sessions Judge (2021)\",\"Civil Judge (2006)\",\"Served in Districts: Haveli, Kotli, and Muzaffarabad\"]', '[\"Promoted to District & Sessions Judge in 2021\",\"Appointed as Judge Ehtesab Court with Banking Court powers\",\"Diverse legal experience across three divisions of AJK\",\"Expertise in fair and efficient dispute resolution\"]', 'board-of-directors/BGcvwLBxmTuCxb6RpAXPiPHR31GPoAsbH5EJ9nKl.png', 4, 0, 0, '2025-07-17 08:08:32', '2025-12-26 07:43:13'),
(5, 'Mr.', 'Khalid Mehmood Mirza', 'Secretary Industries, Commerce, Labour Welfare', 'Mr. Khalid Mehmood Mirza, currently posted as Secretary Industries Government of AJK, is an officer from Secretariat Service Group AJK.', 'Mr. Khalid Mehmood Mirza, currently posted as Secretary Industries Government of AJK, is an officer from Secretariat Service Group AJK, started his career as Section Officer in 1999. He has a vast working experience. He has worked in different departments such as Service & General Administration, Works and Communication, Energy & Water Resources and Mangla Dam Raising Project.  Thereafter, has served as Special Secretary S&GAD, Health Department, Elementary and Secondary Education Department and Finance Department. Besides, he has also served as Director General Civil Defense. In 2022, he was elevated as Secretary to Government and has served in Higher Education Department, Planning and Development Department and Information Technology Department.', '[\"Secretary Industries, Commerce, Labour Welfare (Current)\",\"Secretary in Higher Education, Planning & Development, IT Department (2022)\",\"Director General Civil Defense\",\"Special Secretary in various departments (2016)\",\"Section Officer (1999)\"]', '[\"Promoted to BPS-20 in 2016\",\"Elevated as Secretary to Government in 2022\",\"Vast experience across multiple government departments\",\"Worked on Mangla Dam Raising Project\"]', 'board-of-directors/LcsjawXFE9oeyalifxIqKDUrVOP6tAu8NJnttq2o.png', 5, 0, 0, '2025-07-17 08:08:32', '2025-08-25 14:34:36'),
(6, 'Mr.', 'Mubashar Nabi', 'Social Worker, Director', 'Mubashar Nabi is Founder President and Ex-CEO of ACT with 30 years of experience in poverty alleviation through community mobilization.', 'Mubashar Nabi is Founder President and Ex-CEO of ACT. With a vast and diversified background of 30 years of experience and contributed to policy work and designed & piloted number of national programs & development initiatives across Pakistan & AJ&K. He has almost 30 years\' experience on his credit with exclusive thirteen years practical understanding of working with international and national organizations aiming at poverty alleviation through community mobilization. He specializes in the field of community mobilization with special perspective of forming institutions, linking them up with donor organizations and facilitating the BODs of these institutions to envision from the perspective of institutional development in their local perspective. Being an associate of MDF Holland, Mr. Nabi had contributed widely to strengthening national & regional level institutions through capacity building initiatives linked with microfinance and infrastructure development including TRDP, MRDP, SAFCOW, JWS, IRC, BRSP, KWO, WWOP, HRDN, etc. He had initiated, implemented and managed large projects funded by UNDP, WB, WFP, UNICEF, DIFD, USAID and Save the Children (US & UK). He was also part of the formation of Human Resource Development Network which sets a milestone in the history of capacity building endeavors in the country. His special interest revolves around Institutional Development & Organizational Strengthening, Leadership Management, Social mobilization, Capacity Building, Program Management and Innovate divergent programs in the field of poverty alleviation, microfinance, disaster preparedness, livelihood, social sector, reconstruction and social mobilization.', '[\"Founder President and Ex-CEO of ACT\",\"30 years experience in poverty alleviation programs\",\"13 years with international organizations\",\"Associate of MDF Holland\",\"Project management for UNDP, WB, WFP, UNICEF, USAID\"]', '[\"Founder of Human Resource Development Network (HRDN)\",\"Led policy work and piloted national development programs across Pakistan & AJK\",\"Strengthened institutions: TRDP, MRDP, SAFCOW, BRSP, KWO, WWOP\",\"Specialist in community mobilization and poverty alleviation\"]', 'bod/mubshar nabi.jpg', 6, 1, 0, '2025-07-17 08:08:32', '2025-07-22 05:46:53'),
(7, 'Mr.', 'Zulfiqar Abbasi', 'Laraib Group of Companies Director', 'Mr. Zulfiqar Abbasi is a private Director on the Board of Bank of Azad Jammu & Kashmir and former President of various Chambers of Commerce.', 'Mr. Zulfiqar Abbasi, is a private Director on the Board of Bank of Azad Jammu & Kashmir. He holds Masters Degree in English Literature and also Alumni of the National Defense University (NDU), Islamabad (NS4W). Mr. Zulfiqar Abbasi is the former President of Jammu & Kashmir Joint Chamber of Commerce & Industry (a joint Chamber of Pakistani and Indian administrated Kashmir) and also Presided AJ&K, Chamber of Commerce and Industry, Mirpur. Mr. Abbasi also remained President of Center for Peace, Development and Reforms (CPRD), an AJ&K based think tank working on AJK Constitutional amendments and generated various publications on Youth affairs, Tourism in Kashmir, Environmental issues, Local Bodies elections, Electoral Reforms, Cross LOC Trade, Women status and host of other issues. Mr. Abbasi also served as Chief Executive of various companies set up and owned at Mirpur, A.K such as: Kohsar Hydro Power Pvt. Ltd (Pakistan\'s first private sector Hydro Power Project), Mangla Metals Pvt. Ltd (A steel Industry based on self generated hydropower), Kashmir Foods Pvt. Ltd (A food distribution and manufacturing industry). Mr. Zulfiqar Abbasi, also worked as Director at the Board of Directors of various State owned Institutions and Corporations including AJ&K Hydro Electric Board, AJ&K Technical and Vocational Training Authority (TEVTA), AJ&K Mineral and Industrial Development Corporation (AKMIDC), AJ&K Information Technology Board and AJ&K Small Industries Corporation.', '[\"Former President of J&K Joint Chamber of Commerce & Industry\",\"President AJ&K Chamber of Commerce and Industry, Mirpur\",\"President of Center for Peace, Development and Reforms (CPRD)\",\"Chief Executive of Kohsar Hydro Power, Mangla Metals, Kashmir Foods\",\"Director on various State institutions: TEVTA, AKMIDC, IT Board\"]', '[\"Masters in English Literature, Alumni of NDU Islamabad\",\"Pakistan\'s first private sector Hydro Power Project\",\"Publications on Youth affairs, Tourism, Environmental issues\",\"Cross LOC Trade expertise and Constitutional amendments work\"]', 'bod/zulfiqar_abbasi.jpg', 7, 0, 0, '2025-07-17 08:08:32', '2025-07-17 08:08:32'),
(8, 'Ms.', 'Bushra Naz Malik', 'Director', 'Ms. Bushra Naz Malik is a fellow member of the Institute of Chartered Accountants of Pakistan and CA/CPA from Ontario, Canada.', 'Ms. Bushra Naz Malik is a fellow member of the Institute of Chartered Accountants of Pakistan and CA/CPA from Chartered Professional Accountants, Ontario, Canada. Ms. Malik is an MBA graduate of Kellogg Business School in the United States and the Schulich Business School, Canada. She also has an LLB degree from the Punjab College and Advanced Management Program certification from the Harvard Business School, Boston, USA. Currently, she is Chairperson of the Independent Audit Oversight Committee UNHCR, Geneva, Switzerland. She is also a Director of MHM Consulting, a management service provider firm. She is also a Member of Competition Commission of Pakistan which is a quasi-judicial institution for promoting competitiveness and fair trade in Pakistan. Between 2010 and 2013, she was a Director and Chairperson of the Audit Committee at the Lahore Stock Exchange Ltd in Pakistan. She also served as Group Finance Director and member of the Board of Directors of Kohinoor Maple Leaf Group, Lahore, a consortium of publicly listed firms headquartered in Pakistan, from 2007 to 2010. Ms. Malik was a member of the CGIAR System Management Board (SMB) in 2017-2018, chairing its Audit and Risk Committee, and a member of the Board of Directors of the Pakistan Industrial Development Corporation, also chairing its Audit Committee. She is committed to the cause of women and provides consultancy services to a local NGO dubbed \'All Mothers Educated Now\' based in Pakistan. In 2012 she served as a member of the Commonwealth Business Women, Pakistan Steering Group.', '[\"Chairperson, Independent Audit Oversight Committee UNHCR, Geneva\",\"Director of MHM Consulting\",\"Member of Competition Commission of Pakistan\",\"Group Finance Director, Kohinoor Maple Leaf Group (2007-2010)\",\"Director and Audit Committee Chair, Lahore Stock Exchange (2010-2013)\"]', '[\"Fellow ICAP and CA\\/CPA from Ontario, Canada\",\"MBA from Kellogg Business School and Schulich Business School\",\"LLB and Harvard Business School Advanced Management Program\",\"CGIAR System Management Board member (2017-2018)\",\"Commonwealth Business Women Pakistan Steering Group (2012)\"]', 'bod/bushra naz.png', 8, 1, 0, '2025-07-17 08:08:32', '2025-07-22 07:54:01'),
(9, NULL, 'Dr. Adnan U. Khan', 'Company Secretary', 'Dr. Adnan U. Khan is Company Secretary of the Bank with experience at SBP and a PhD in Finance, specializing in corporate governance and financial markets.', 'Dr. Adnan U. Khan has joined the Bank as Company Secretary, bringing with him experience from the State Bank of Pakistan, where he managed corporate and secretarial affairs of its subsidiary, Pakistan Security Printing Corporation. Dr. Adnan U. Khan, who holds a PhD in Finance with numerous publications in leading finance and corporate governance journals, is also an Associate Member of the Institute of Corporate Secretaries of Pakistan. In addition to his academic achievements, Dr. Khan has completed several certifications from prestigious institutions, such as a certification in Financial Markets from Yale University, USA, and a certification in Investment Banking from the University of Illinois Urbana-Champaign, USA.', '[\"Company Secretary, Bank of Azad Jammu & Kashmir\",\"Manager Corporate & Secretarial Affairs, Pakistan Security Printing Corporation (a subsidiary of State Bank of Pakistan)\",\"Associate Member, Institute of Corporate Secretaries of Pakistan\",\"Academic and research background in finance and corporate governance\",\"Completed certifications in Financial Markets and Investment Banking from top U.S. universities\"]', '[\"Awarded a PhD in Finance, with research published in internationally acclaimed journals on finance and corporate governance\",\"Completed prestigious executive certifications in Financial Markets (Yale University, USA) and Investment Banking (University of Illinois Urbana-Champaign, USA), demonstrating global proficiency in financial and investment disciplines\",\"Appointed as Company Secretary of the Bank of Azad Jammu & Kashmir, reflecting institutional confidence in his leadership and governance expertise\",\"Played a key role in strengthening governance and compliance frameworks at the Pakistan Security Printing Corporation, a subsidiary of the State Bank of Pakistan\"]', 'board-of-directors/cAwCjtpLyCR7qNibntpsBc1QI2aaT71eQDzoFSwB.png', 9, 0, 0, '2025-07-22 07:01:30', '2025-12-05 06:24:54'),
(10, NULL, 'Ch. Abdul Rehman', 'Secretary Industries, Commerce, Labour Welfare', 'Ch. Abdul Rehman, Secretary Industries & Commerce (GoAJK), combines strong academic credentials with decades of administrative experience to advance governance and institutional growth.', 'Ch. Abdul Rehman brings with him extensive experience across diverse sectors of public service. He is currently serving as Secretary Industries & Commerce, Government of Azad Jammu & Kashmir. Previously, he has held key positions as Secretary Tourism & Archaeology, GoAJK and Director General Civil Defense Department, GoAJK. With strong academic credentials, including an M.A. in Economics, M.A. in History and an LL.B., Ch. Abdul Rehman combines his multidisciplinary knowledge with decades of administrative expertise. His leadership and vision continue to contribute significantly to institutional growth and governance.', '[\"Secretary Industries & Commerce, GoAJK (Current)\",\"Previously served as Secretary Tourism & Archaeology, Government of Azad Jammu & Kashmir.\",\"Served as Director General, Civil Defense Department, Government of Azad Jammu & Kashmir.\"]', '[\"Strengthened institutional frameworks through effective leadership and governance.  Contributed to the promotion and development of industries, commerce, and tourism in AJK.\",\"Enhanced organizational efficiency and public service delivery across multiple departments.\",\"Applied multidisciplinary academic background (Economics, History, Law) to policymaking and administration.\"]', 'board-of-directors/1ymdIIjCIqavO7eOzsCHemauIwcvdPXO2mnLCyPa.jpg', 5, 0, 0, '2025-08-25 14:51:48', '2026-01-28 07:59:24'),
(11, NULL, 'Ch. Qasim Majeed', 'Minister Finance & Inland Revenue', 'Chairman of AJK Bank and Finance Minister, leading the digital modernization of AJK’s banking system for efficiency and global alignment.', 'Ch. Qasim Majid is the current Chairman of the Bank of Azad Jammu & Kashmir and serves as the Minister for Finance and Inland Revenue as well as Member of the Legislative Assembly from LA-2 Mirpur. His priority is to modernize and digitalize AJK’s banking system — making it fully compatible with Pakistan’s current financial standards and aligned with global banking practices. He is committed to introducing innovative mechanisms that ensure ease of business, improved access to financial services, and a more efficient and consumer-friendly banking experience across the region.', '[]', '[]', 'board-of-directors/xVr9zm7kdemmgoY2j8Lte5sH3SaYIjtTdruWB52M.jpg', 1, 0, 1, '2025-12-01 11:23:40', '2026-09-02 09:43:09'),
(12, 'Mr.', 'Irshad Ahmed Qureshi', 'Secretary, Law, Justice & Parliamentary Affairs  AJK, Director', 'Mr. Irshad Ahmed Qureshi is a seasoned civil servant with over 27 years of experience, currently serving as Secretary Law, Justice, Parliamentary Affairs & Human Rights, Azad Jammu & Kashmir, with a strong background in legal governance, policy leadership, and public administration across multiple key departments.', 'Mr. Irshad Ahmed Qureshi currently posted as Secretary Law, Justice, Parliamentary Affairs & Human Rights Deptt. Azad Jammu & Kashmir; he holds a Master of Laws (LLM) degree in International Law with International Relations from the University of Kent, the United Kingdom. He had joined public service as Section Officer in 1995 and has more than 27 years of experience. He also served as Secretary to the Prime Minister of AJK. During his career, he had performed different assignments with dedication as Secretary to Govt. of AJK and Head of multiple Departments like Elementary & Secondary Education, Local Government & Rural Development Agriculture, Zakat & Usher and Social Welfare Department.', '[\"Currently serving as Secretary, Law, Justice, Parliamentary Affairs & Human Rights Department, Azad Jammu & Kashmir.\",\"Joined public service in 1995 as a Section Officer, with over 27 years of continuous government service.\",\"Served as Secretary to the Prime Minister of Azad Jammu & Kashmir, handling high-level administrative coordination and policy matters.\",\"Held multiple assignments as Secretary to the Government of AJK, leading key government departments.\",\"Headed the Elementary & Secondary Education Department, overseeing education policy, administration, and institutional management\",\"Served as Secretary of Local Government & Rural Development Department, contributing to grassroots governance and rural development initiatives.\",\"Led the Agriculture Department, supporting agricultural planning and sectoral development.\",\"Served as Secretary for Zakat & Usher Department, ensuring effective management and distribution of welfare funds.\",\"Headed the Social Welfare Department, focusing on social protection and community development programs.\"]', '[\"Demonstrated strong leadership and administrative expertise across diverse government departments.\",\"Made significant contributions to education, local governance, agriculture, and social welfare sectors in Azad Jammu & Kashmir.\",\"Applied international legal knowledge gained through LLM in International Law & International Relations (University of Kent, UK) to public sector governance.\",\"Contributed to the effective functioning of the Prime Minister\\u2019s Office through strategic coordination and advisory support.\",\"Successfully managed legal, legislative, and parliamentary affairs, ensuring compliance with laws and governance frameworks.\",\"Played a key role in policy formulation, implementation, and institutional strengthening within the Government of AJK.\"]', 'board-of-directors/ElLDg5OKSat0R8UAeudO1bfd42FDjLtywVo9f5qq.jpg', 4, 0, 0, '2025-12-26 07:45:46', '2026-01-28 07:59:06'),
(13, 'Mr.', 'Khurram Haris', 'Director', 'Mr. Khurram Haris, CEO & Founder of KH Group, has 20+ years of experience in banking, investment, and strategic advisory across Pakistan, UAE, and UK.', 'Mr. Khurram Haris is a seasoned banking and investment professional with over two decades of diverse experience across Pakistan, UAE and United Kingdom. He is the Chief Executive Officer and Founder of KH Group / KIMC Management Consulting, providing strategic advisory services in investment, infrastructure and public–private partnerships. Mr. Haris has held several senior leadership and advisory roles, including Executive Director at the Bin Zayed Group (UAE), Executive Director and Advisor for South Asia and the Middle East at Tumas Pakistan and Honorary Investment Advisor to UAE, the Board of Investment, Pakistan. He currently serves as a Member of the Public–Private Partnership Policy and Monitoring Board, Government of Punjab, and has previously contributed as a Corporate and Banking Transaction Expert with NAB Lahore. His distinguished career also includes senior positions with leading global financial institutions such as Barclays Bank, Citibank and the Royal Bank of Scotland, as well as advisory roles with national and international public sector organizations. Mr. Haris holds an MBA from the University of Liverpool (UK) and a Postgraduate Diploma in Information Technology from DeVry University, Canada.', '[\"Over 20 years of professional experience in banking, investment and financial advisory\",\"International exposure across Pakistan, UAE and the United Kingdom\",\"International exposure across Pakistan, UAE and the United Kingdom\",\"Executive Director, Bin Zayed Group (UAE)\",\"Senior leadership roles with global banks including Barclays Bank, Citibank and Royal Bank of Scotland\"]', '[\"Advised government bodies on investment facilitation and economic development as Honorary Investment Advisor to the Board of Investment, Pakistan\",\"Established and successfully grew KH Group \\/ KIMC Management Consulting as a strategic advisory firm\",\"Played a key role in cross-border investments between Pakistan, UAE and the UK\"]', 'board-of-directors/7SjhLUJSDzQJRaPqIRUJYLFZWrD7fQnJ3gGQOeQK.jpg', 10, 1, 0, '2026-01-26 05:02:02', '2026-01-26 05:09:37'),
(14, 'Mr.', 'Hasan Masud', 'Secretary Finance', 'Hasan Masud is a highly experienced public sector professional with over 24 years of expertise in Public Financial Management and digital transformation. He is currently serving as Secretary Finance, AJK, leading reforms to modernize and strengthen government financial systems.', 'For the past 24 years Hasan Masud has worked in the areas of Public Financial Management\n(PFM) reform and digital transformation. Presently as Secretary Finance, Azad Jammu and\nKashmir, he is working on digital transformation and mainstreaming of PFM reforms in the\nregion. He had earlier worked on digital transformation issues at the office of the Auditor\nGeneral of Pakistan. This involved working as the Project Manager of Audit Management\nInformation System (AMIS) in the 28 field offices across the country. He was also responsible\nfor implementing an intensive professional training and education program in the field of\nAccounting, Information Technology and Auditing. This entailed mainstreaming a new\ncompetency framework, change management and development of an innovation hub in the\ndepartment of the Auditor General. He has worked on change management and internal\ngovernance reforms as Director General MIS/FABS, the agency responsible for digitalization in\nGovernment Accounting organizations.\nMr Hasan Masud has been trained extensively in the field of Project Management, PFM, Internal\nAudit, government Auditing both locally and abroad.\nSome of his key assignments are\n1.    Secretary Finance, Government of AJK, Muzaffarabad (Present Posting)\n2.   Accountant General, AJK, Muzaffarabad\n3.    Director General Information Technology/ Project Manager, Auditor General Office,\nIslamabad\n4.    Director General Audit Defence Services, Rawalpindi\n5.    Director General MIS/Financial Accounting and Budgeting Systems, Controller General\nof Accounts, Islamabad\n6.    Director General Quality Assurance, Inspection &amp; Monitoring, Auditor General Office,\nIslamabad\n7.     Additional Accountant General, AGPR, Islamabad\n8.    Controller Military Accounts (ISOs), MAG, Rawalpindi\n9.    Controller Local Audit (DP), MAG, Rawalpindi\n10.   Vice Consul (Accounts), Consulate General of Pakistan, Jeddah, KSA', '[\"Over 24 years of experience in Public Financial Management (PFM) and digital transformation.\",\"Currently serving as Secretary Finance, Government of AJK, leading modernization and PFM reforms.\",\"Project Manager of the Audit Management Information System (AMIS) across 28 field offices.\",\"Implemented digitalization initiatives in government accounting and auditing systems.\"]', '[\"Successfully led digital transformation initiatives in government accounting and auditing systems, including the implementation of the Audit Management Information System (AMIS) across 28 field offices.\",\"Modernized and strengthened Public Financial Management (PFM) reforms in Azad Jammu & Kashmir as Secretary Finance.\",\"Contributed to the digitalization of MIS and Financial Accounting & Budgeting Systems at a national level.\"]', 'board-of-directors/WuaxWFY3LJ0PWLUZsx33oLW0ZEZcpbAEJR128COU.jpg', 3, 1, 0, '2026-01-28 07:36:13', '2026-01-29 11:33:47'),
(15, 'Dr.', 'Muhammad Idrees Abbasi', 'Secretary Law', 'Dr. Muhammad Idrees Abbasi is a distinguished legal scholar and veteran civil servant currently serving as Secretary of Law for the Government of AJK, with extensive expertise in human rights, governance, and academic research.', 'Dr. Muhammad Idrees Abbasi is Secretary Law, Justice, Parliamentary Affairs & Human Rights Department, Govt. of AJK and Director of the Board of Bank of AJK. He is a Ph.D in Law (Human Rights) from International Islamic University, Islamabad and has a vast experience of law, planning, teaching and management at his credit which includes various top hierarchy level positions. He headed various Departments as Secretary to the Govt. of Azad Jammu & Kashmir. Dr. Abbasi is a highly professional/competent person. He attended a large number of training programs nationally and internationally. Dr. Abbasi has a diversified personality which lead him to write numerous Research Papers and Publications on all the aspects such as Human Rights, Islamic as well as Inland Laws, Kashmir Issue, Electronic Media and Women Testimony under Qanoon-e-Shahadat. Dr. Mohammad Idrees Abbasi, Secretary Law Justice, Parliamentary Affairs & Human Rights Department, Govt. of AJK and Director of the Board of Bank of AJK. He is a Ph.D in Law (Human Rights) from International Islamic University, Islamabad and has a vast experience of law, planning, teaching and management at his credit which includes various top hierarchy level positions. He headed various Departments as Secretary to the Govt. of Azad Jammu & Kashmir.\nDr. Abbasi is a highly professional/competent Personal and attended a large number of training programs nationally and internationally. Dr. Abbasi has a diversified personality which leaded him to write numerous Research Papers and Publications on all the aspects such as Human Rights, Islamic as well as Inland Laws, Kashmir Issue, Electronic Media and Women Testimony under Qanoon-e-Shahadat.', '[\"Secretary Law, Justice, Parliamentary Affairs & Human Rights: Currently serving as the administrative head of this department for the Government of Azad Jammu & Kashmir (AJK).\",\"Director of the Board: Serving as a Director for the Bank of Azad Jammu & Kashmir, overseeing corporate governance and financial oversight.\",\"Departmental Head (Multiple Portfolios): Previously headed various government departments as Secretary to the Government of AJK.\"]', '[\"Academic Excellence: Successfully earned a Ph.D. in Law (Human Rights) from the International Islamic University, Islamabad.\",\"Scholarly Contribution: Published numerous research papers on complex legal issues, including Human Rights and the Kashmir issue.\"]', 'board-of-directors/3he2EaSO86D2RpC6eAbqLCxFslW4OSfpFl4BD7pS.jpg', 4, 1, 0, '2026-01-28 07:43:20', '2026-01-29 11:51:12'),
(16, 'Mr.', 'Adnan Khurshid', 'Secretary industries', NULL, NULL, NULL, NULL, 'board-of-directors/rVHjltT3Ifj5n7RkPXbu80j82sBPoL0b1iDxw9TI.jpg', 5, 1, 0, '2026-01-28 07:45:18', '2026-01-28 07:45:18'),
(17, NULL, 'Mr. Khushal Khan', 'Chief Secretary Govt. of AJK', 'Mr. Khushal Khan, S.I., T.St. is a distinguished public servant, former Pakistan Air Force officer, and senior Pakistan Administrative Service (PAS) officer with extensive experience in governance and public administration. He assumed charge as Chief Secretary, Government of Azad Jammu & Kashmir, in December 2024 and serves as Chairman of the Board of Directors, Bank of Azad Jammu & Kashmir. His leadership reflects strong administrative expertise, strategic vision, and a commitment to institutional excellence and regional development.', 'Mr. Khushal Khan, S.I., T.St., is a senior public administrator and former Pakistan Air Force officer with extensive experience in governance, public administration, and institutional management. A BS-21 officer of the Pakistan Administrative Service, he has held several important positions in the Government of Pakistan, including Additional Secretary, Power Division.\r\n\r\nHe assumed charge as Chief Secretary, Government of Azad Jammu & Kashmir, in December 2024. In his capacity as Chairman of the Board of Directors of the Bank of Azad Jammu & Kashmir, he provides strategic leadership and governance oversight, supporting the Bank\'s continued institutional growth and contribution to the economic development of the region.', NULL, NULL, 'board-of-directors/MLp4NyEoNMBrceJ5cLaEYS3RqUGj3hj0Za6UBOUy.jpg', 1, 1, 1, '2026-09-02 09:47:41', '2026-09-02 09:49:43'),
(18, NULL, 'Mr. Malik Muhammad Babar Ayyaz', 'President/CEO', 'Mr. Malik Muhammad Babar Ayyaz is the President & CEO of BAJK, with over 27 years of banking experience in corporate, commercial, Islamic, and SME banking. He brings extensive expertise in strategic planning, business transformation, and institutional leadership.', 'Mr. Malik Muhammad Babar Ayyaz is the President & Chief Executive Officer (CEO) of the Bank of Azad Jammu & Kashmir (BAJK). A seasoned banking professional with over 27 years of diverse experience in Pakistan\'s financial sector, Mr. Ayyaz brings extensive expertise in corporate banking, commercial banking, Islamic banking, SME finance, strategic planning, business transformation, and institutional leadership. Prior to joining BAJK, Mr. Ayyaz served for nearly 17 years at The Bank of Punjab (BOP), where he held several key leadership positions after serving at other private banks. During his tenure at BOP, he played a pivotal role in restructuring the Bank\'s Corporate & Investment Banking and was instrumental in establishing and strengthening its SME & Commercial Banking businesses, contributing significantly to the Bank\'s growth and strategic transformation. Mr. Ayyaz holds an Executive MBA from the Lahore University of Management Sciences (LUMS), graduating with distinction and earning a place on the Dean\'s Honour Roll. His academic background, combined with extensive leadership experience, reflects a strong commitment to excellence and continuous professional development', NULL, NULL, 'board-of-directors/8OTLNrZRbKqr29rS8adkrMtdHyUiDgRDk90X1BbS.jpg', 2, 1, 0, '2026-09-02 09:52:42', '2026-09-02 09:52:42');
