INSERT INTO `careers` (`id`, `title`, `description`, `requirements`, `location`, `document`, `closing_date`, `is_active`, `is_featured`, `views_count`, `benefits`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES
(1, 'Date Extension', 'We are looking for an experienced Senior Software Engineer to join our technology team. You will be responsible for developing and maintaining our core banking applications using modern technologies.', '', '', 'careers/career1.jpeg', '2025-06-15', 1, 1, 0, '', NULL, NULL, '2025-07-17 08:08:32', '2025-07-17 08:08:32'),
(2, 'CAREER OPPORTUNITIES', ' We are looking for dedicated resources having relevant experience and are willing to work in Project\n                             Management Office, Information Technology Division of the bank for execution and implementation of Core Banking Solution and Digital\n                             Channels project with proven track record and capacity act as a catalyst for transformation in a dynamic and challenging environment in\n                             the area of Information Technology. The Individuals who are team players, energetic, dynamic and result oriented and willing to work in\n                             a challenging environment with a lot of growth opportunities, fulfilling the below-mentioned basic eligibility criteria may apply for the positions.', 'Kindly consult the detailed advertisement for complete eligibility requirements.', 'All over AJK', 'careers/career2.pdf', '2025-04-16', 1, 1, 0, '', NULL, NULL, '2025-07-17 08:08:32', '2025-07-17 08:08:32'),
(3, 'Corrigendum', 'This corrigendum notice contains updates or modifications to the original advertisement. Please refer to the attached document for detailed information.', 'Refer to the corrigendum document for revised criteria or changes.', 'Muzaffarabad, AJ&K', 'careers/career3.pdf', '2025-06-15', 1, 1, 0, '', NULL, NULL, '2025-07-17 08:08:32', '2025-07-17 08:08:32'),
(4, 'Corrigendum – Date Extension', 'The Bank of Azad Jammu and Kashmir has issued a corrigendum regarding the previously advertised Internship Opportunities 2024 (Ref: AJK 123-D/02/2024) published on February 15, 2024 in Daily Dawn and Daily Jang. The deadline for submission of online applications has been extended up to March 10, 2024. All other terms and conditions remain unchanged.', 'All eligibility criteria and requirements remain the same as stated in the original advertisement. Please refer to the original notice for details.', 'Bank of Azad Jammu and Kashmir, Head Office, Sardar Nazir Plaza, Muzaffarabad', 'careers/career4.pdf', '2025-06-15', 1, 1, 0, '', NULL, NULL, '2025-07-17 08:08:32', '2025-07-17 08:08:32'),
(5, 'Internship Opportunities 2024 ', 'The Bank of Azad Jammu and Kashmir (BAJK) is offering a one-year paid internship program for graduate and postgraduate students. The internship provides hands-on work experience in various functional areas across different branches.', 'Kindly consult the detailed advertisement for complete eligibility requirements.', 'All over AJK', 'careers/career5.pdf', '2024-03-10', 1, 1, 0, 'Competitive stipend, and professional development opportunities.', NULL, NULL, '2025-07-17 08:08:32', '2025-07-17 08:08:32'),
(6, 'CAREER OPPORTUNITIES', 'The Bank of Azad Jammu and Kashmir (BAJK) is an emerging and rapidly growing Financial Institution wholly owned by the Azad Government of the State of Azad Jammu and Kashmir. The BAJK focuses on strengthening its institutionalcapacity through continugus upgradation in terms of Human Resource at the Bank. Currently, BAJK is going to hire a batch of General Banking Officers (GBOs) in Grade-IV to meet the shortfall of staff at branches at Mirpur, Kotli & Rawalakot Regions through competitive test to be conducted by third party testing firm. For the purpose, BAJK is looking for services of young individuals who are team players, energetic, result oriented and willing to work in a challenging environment with a lot of growth opportunities. ', 'Kindly consult the detailed advertisement for complete eligibility requirements.', 'Mirpur, Rawalakot,Kotli Regions', 'careers/career6.pdf', '2024-03-02', 1, 1, 0, 'Competitive salary, health insurance, provident fund, annual bonus, and professional development opportunities.', NULL, NULL, '2025-07-17 08:08:32', '2025-07-17 08:08:32'),
(7, 'Corrigendum  ', 'Corrigendum notice from Bank of Azad Jammu and Kashmir updating the number of positions for Assistant/Cash Sorter roles across branches, with regional quotas and disability reservations.', 'Kindly consult the detailed advertisement for complete eligibility requirements.', 'All over AJK', 'careers/career7.jpeg', '2024-02-15', 1, 1, 0, '', NULL, NULL, '2025-07-17 08:08:32', '2025-07-17 08:08:32'),
(8, 'Assistant / Cash Sorter Positions', 'Contract-based opportunities at Bank of Azad Jammu and Kashmir for young, energetic individuals seeking career growth in banking operations.', 'Intermediate minimum (graduation preferred), age 18-42, computer literacy, communication skills. AJK State Subjects preferred.', 'Various branches across Muzaffarabad, Rawalakot, Mirpur, and Kotli regions', 'careers/career8.pdf', '0204-02-03', 1, 1, 0, '2-year contract with potential absorption into regular cadre, competitive compensation package per bank policy', NULL, NULL, '2025-07-17 08:08:32', '2025-07-17 08:08:32'),
(9, 'Enployement Form ', 'Standard employment application form for all career opportunities at Bank of Azad Jammu & Kashmir. This universal document collects essential candidate information required for consideration across various positions, roles, and departments within the banking institution.', '', '', 'careers/career9.pdf', '2025-06-15', 1, 1, 0, '', NULL, NULL, '2025-07-17 08:08:32', '2025-07-17 08:08:32'),
(10, 'DATE EXTENSION (Advertisement No. AJK-102D/03/2025)', 'This notice refers to a job advertisement published on March 15, 2025, in Daily Dawn and Daily Jang Islamabad, with the deadline for submitting online applications further extended up to July 15, 2025, while all other terms and conditions remain the same.', '', '', 'careers/career10.jpeg', '2025-07-15', 1, 1, 0, '', NULL, NULL, '2025-07-17 08:08:32', '2025-07-17 08:08:32'),
(11, 'DATE EXTENSION (Advertisement No. AJK-136-D/05/2025)', 'This notice, regarding a job advertisement published on March 15, 2025, in Daily Dawn and Daily Jang Islamabad, states that the deadline for submitting online applications has been further extended to July 15, 2025, with all other terms and conditions remaining the same.', '', '', 'careers/career11.jpeg', '2025-07-15', 1, 1, 0, '', NULL, NULL, '2025-07-17 08:08:32', '2025-07-17 08:08:32'),
(12, 'DATE EXTENSION (Advertisement No. AJK-102D/03/2025) .', 'This notice refers to a job advertisement published on March 15, 2025, in Daily Dawn and Daily Jang Islamabad, with the deadline for submitting online applications further extended up to Aug 31, 2025, while all other terms and conditions remain the same.', 'N/A', 'N/A', 'careers/7QG5nLAD2AEVgDghSWsrkd7qLZNsCVF591mxFhAX.pdf', '2025-08-31', 1, 0, 8, 'N/A', 1, 1, '2025-08-21 11:34:56', '2025-08-25 04:15:44');
INSERT INTO `carousels` (`id`, `title`, `description`, `image`, `button_text`, `button_url`, `order`, `status`, `created_by`, `updated_by`, `created_at`, `updated_at`) VALUES
(1, 'Customer Support 24/7', 'We\'re here to help you with all your banking needs anytime, anywhere with dedicated support.', 'carousel-images/smtf.png', 'Contact Us', '/contact', 1, 'inactive', 1, 1, '2025-07-17 08:08:32', '2026-10-12 17:47:13'),
(2, 'Car Finance', 'Enjoy the drive of your dreams with our simple and accessible car financing solutions across Azad Jammu & Kashmir.', 'carousel-images/cardrive.png', 'Explore', '/products/consumer-finances', 2, 'active', 1, NULL, '2025-07-17 08:08:32', '2025-07-17 08:08:32'),
(3, 'Gold Loan ', 'Experience seamless banking with our innovative digital platform designed for modern financial needs.', 'carousel-images/gold_loan.jpg', 'Learn More', '/gold-loan', 3, 'active', 1, NULL, '2025-07-17 08:08:32', '2025-07-17 08:08:32');
