INSERT INTO `news_announcements` (`id`, `title`, `content`, `excerpt`, `image`, `published_date`, `is_featured`, `category`, `slug`, `is_published`, `created_at`, `updated_at`) VALUES
(1, 'BAJK Signs Historic Agreement with Silverlake to Implement Core Banking System, Ushering in a New Era of Digital Banking', 'Muzaffarabad<br>  The Bank of Azad Jammu and Kashmir (BAJK) has taken a monumental leap toward digital transformation by signing a landmark agreement with Malaysia-based global technology consortium Silverlake to implement a state-of-the-art <strong>Core Banking System (CBS)</strong>. The contract signing ceremony, held at the prestigious Islamabad Serena Hotel, was graced by esteemed dignitaries, marking a pivotal moment in the financial modernization of the region.<br><br>\n\n<strong>Distinguished Guests and Key Attendees</strong><br>\nThe event was attended by senior officials from BAJK, consortium partners, government representatives, and key stakeholders from the financial and technology sectors. The <strong>Honorable Prime Minister of AJK, Chaudhry Anwarul Haq</strong>, presided as the <strong>Chief Guest</strong>.<br>\nOther notable attendees included:<br>\n- <strong>Mr. Shahid Shahzad Mir</strong>, President & CEO of BAJK<br>\n- <strong>Khan Abdul Majid Khan</strong>, Chairman of BAJK’s Board of Directors<br>\n- <strong>Chaudhry Latif Akbar</strong>, Speaker of the AJK Legislative Assembly<br>\n- <strong>Mr. Khushal Khan</strong>, Chief Secretary of AJK<br>\n- Former Chief Secretaries <strong>Mr. Usman Chacharr</strong> and <strong>Mr. Dawood Bareech</strong><br>\n- BAJK Directors, Divisional Heads, and members of the business community<br><br>\n\n<strong>A Transformational Step for BAJK</strong><br>\nThe new <strong>Core Banking System (CBS)</strong> will replace BAJK’s legacy infrastructure with a <strong>modern, centralized, and real-time banking platform</strong>, integrating all operations to enhance efficiency, improve customer experience, and enable innovative digital services.<br><br>\n\n<strong>Key Statements from the Ceremony</strong><br>\n<strong>1. Mr. Shahid Shahzad Mir – President & CEO, BAJK</strong><br>\n<em>\"Today marks a historic step forward for BAJK, particularly under the dynamic leadership of Chairman Khan Abdul Majid Khan and the Board IT Committee. This CBS will strengthen our operational backbone and allow us to serve customers with speed, security, and innovation. It is a crucial part of our vision to become a fully digital, customer-centric bank across Azad Jammu & Kashmir.\"</em><br><br>\n\n<strong>2. Mr. David Lim – Co-CEO, Silverlake</strong><br>\n<em>\"This partnership signifies a major digital transformation. Silverlake is committed to delivering a <strong>robust, scalable, and secure</strong> banking solution tailored to BAJK’s needs, ensuring compliance with global standards while empowering customers with real-time, 24/7 banking services.\"</em><br><br>\n\n<strong>3. Khan Abdul Majid Khan – Chairman, BAJK</strong><br>\n<em>\"Forewarning and digital readiness are the backbone of modern banking. This initiative lays the foundation for BAJK’s <strong>scheduled bank status</strong>, economic empowerment, and AJK’s digital development. The dedication of BAJK’s management has been instrumental in reaching this milestone.\"</em><br><br>\n\n<strong>4. Chaudhry Latif Akbar – Speaker, AJK Legislative Assembly</strong><br>\n<em>\"With this transformation, BAJK is on its way to becoming a <strong>scheduled bank</strong>—a milestone that will elevate financial services in the region. I commend Chairman Majid Khan and the entire BAJK team for their relentless efforts.\"</em><br><br>\n\n<strong>Prime Minister Chaudhry Anwarul Haq’s Keynote Address</strong><br>\n<em>\"Today is a momentous occasion for Azad Jammu & Kashmir as we witness a strategic leap in our financial infrastructure. The agreement between BAJK and Silverlake is not merely a technological upgrade—it is a <strong>game-changer</strong> for our economy and a testament to our government’s commitment to digital progress.<br>\nI commend BAJK’s Board of Directors and management for their foresight in embracing this transformation. The implementation of the Core Banking System will revolutionize service delivery, bringing AJK in line with global banking standards. This aligns perfectly with our vision to make BAJK a <strong>scheduled bank</strong>, a priority for my government.<br>\nTo the people of AJK, I assure you: this government stands firmly behind BAJK’s growth. We have high expectations from this partnership and are confident it will unlock new opportunities for economic empowerment, especially for our youth and entrepreneurs. I congratulate all stakeholders, particularly the Finance Secretary, for turning this vision into reality.\"</em><br><br>\n\n<strong>Implementation Timeline</strong><br>\nThe CBS will be rolled out in phases and is expected to be <strong>fully operational across all BAJK branches within 24 months</strong>, revolutionizing banking services in AJK.<br><br>\n\n<strong>About BAJK</strong><br>\nThe <strong>Bank of Azad Jammu & Kashmir (BAJK)</strong> is a state-owned financial institution committed to inclusive banking and socio-economic development in the region. With an expanding branch network and a vision for digital excellence, BAJK continues to play a vital role in AJK’s financial growth.<br><br>\n\n<div dir=\"rtl\" style=\"text-align: right;\">\n<strong>بینک آف آزاد جموں و کشمیر (BAJK) نے سلورلیک کے ساتھ تاریخی معاہدہ پر دستخط کرتے ہوئے جدید ترین کور بینکنگ سسٹم متعارف کرانے کا اعلان کیا</strong><br>\n<strong>مظفرآباد،</strong><br>\nبینک آف آزاد جموں و کشمیر (BAJK) نے جمعہ کے روز ملائیشیا کی عالمی ٹیکنالوجی کنسورشیم سلورلیک کے ساتھ ایک تاریخی معاہدے پر دستخط کر کے خطے میں ڈیجیٹل بینکنگ کے نئے دور کا آغاز کر دیا ہے۔ اس معاہدے کے تحت BAJK میں جدید ترین <strong>کور بینکنگ سسٹم (CBS)</strong> متعارف کرایا جائے گا۔ اسلام آباد کے شاندار ہوٹل سیرینا میں منعقدہ دستخطی تقریب میں معزز شخصیات نے شرکت کی، جو خطے میں مالیاتی جدید کاری کا ایک اہم سنگ میل ثابت ہو گی۔<br><br>\n\n<strong>تقریب میں شریک معزز شخصیات</strong><br>\nتقریب میں BAJK کے اعلیٰ عہدیداران، کنسورشیم کے شراکت داروں، حکومتی نمائندوں اور مالیاتی و ٹیکنالوجی شعبوں کے اہم اسٹیک ہولڈرز نے شرکت کی۔ <strong>آزاد جموں و کشمیر کے وزیراعظم محترم چوہدری انور الحق</strong> اس موقع پر <strong>مہمان خصوصی</strong> کی حیثیت سے موجود تھے۔<br>\nدیگر ممتاز شخصیات میں شامل تھے:<br>\n- <strong>شاہد شہزاد میر</strong>، صدر و سی ای او BAJK<br>\n- <strong>خان عبدالماجد خان</strong>، چیئرمین بورڈ آف ڈائریکٹرز BAJK<br>\n- <strong>چوہدری لطیف اکبر</strong>، اسپیکر قانون ساز اسمبلی آزاد جموں و کشمیر<br>\n- <strong>جناب خوشحال خان</strong>، چیف سیکرٹری آزاد جموں و کشمیر<br>\n- سابق چیف سیکرٹریز <strong>جناب عثمان چھچھر</strong> اور <strong>جناب داؤد بریچ</strong><br>\n- BAJK کے ڈائریکٹرز، ڈویژنل ہیڈز اور کاروباری برادری کے اراکین<br><br>\n\n<strong>BAJK کے لیے ایک انقلابی قدم</strong><br>\nنیا <strong>کور بینکنگ سسٹم (CBS)</strong> BAJK کے پرانے نظام کی جگہ لے گا اور ایک <strong>جدید، مرکزی اور رئیل ٹائم بینکنگ پلیٹ فارم</strong> فراہم کرے گا، جو تمام بینکنگ آپریشنز کو یکجا کرے گا، کارکردگی کو بہتر بنائے گا، صارفین کے تجربے کو بڑھائے گا اور جدید ڈیجیٹل خدمات کی راہ ہموار کرے گا۔<br><br>\n\n<strong>تقریب سے کلیدی اقتباسات</strong><br>\n<strong>1. شاہد شہزاد میر – صدر و سی ای او، BAJK</strong><br>\n<em>\"آج BAJK کے لیے ایک تاریخی لمحہ ہے، خاص طور پر چیئرمین خان عبدالماجد خان اور بورڈ آئی ٹی کمیٹی کی متحرک قیادت میں۔ یہ سسٹم ہمارے آپریشنل ڈھانچے کو مستحکم کرے گا اور ہمیں تیز، محفوظ اور جدید بینکنگ خدمات فراہم کرنے کے قابل بنائے گا۔\"</em><br><br>\n\n<strong>2. ڈیوڈ لِم – کو-سی ای او، سلورلیک</strong><br>\n<em>\"یہ شراکت داری ڈیجیٹل بینکنگ کی ایک بڑی تبدیلی کی نمائندہ ہے۔ سلورلیک BAJK کو <strong>مضبوط، محفوظ اور توسیع پذیر</strong> حل فراہم کرنے کے لیے پرعزم ہے جو عالمی معیار کے مطابق ہوگا۔\"</em><br><br>\n\n<strong>3. خان عبدالماجد خان – چیئرمین، BAJK</strong><br>\n<em>\"پیشگی تیاری اور ڈیجیٹل اپنانا جدید بینکنگ کی بنیاد ہیں۔ یہ اقدام نہ صرف BAJK کے <strong>شیڈولڈ بینک</strong> بننے کی راہ ہموار کرے گا بلکہ خطے کی ڈیجیٹل ترقی اور معاشی خودمختاری میں مددگار ہو گا۔\"</em><br><br>\n\n<strong>4. چوہدری لطیف اکبر – اسپیکر، قانون ساز اسمبلی</strong><br>\n<em>\"یہ اقدام BAJK کو <strong>شیڈولڈ بینک</strong> بننے کی طرف گامزن کرتا ہے، جو علاقے کی مالیاتی ترقی کے لیے ایک اہم پیش رفت ہے۔ میں چیئرمین اور ان کی ٹیم کو خراج تحسین پیش کرتا ہوں۔\"</em><br><br>\n\n<strong>وزیراعظم چوہدری انور الحق کا کلیدی خطاب</strong><br>\n<em>\"آج کا دن آزاد جموں و کشمیر کے لیے ایک سنگ میل ہے۔ یہ معاہدہ صرف ٹیکنالوجی کی اپ گریڈ نہیں بلکہ ایک <strong>انقلابی قدم</strong> ہے جو ہماری معیشت اور ڈیجیٹل وژن کی عکاسی کرتا ہے۔<br>\nBAJK کی انتظامیہ اور بورڈ کی دوراندیشی لائق تحسین ہے۔ یہ نظام خدمات کی فراہمی میں انقلاب لائے گا اور عالمی معیارات سے ہم آہنگ کرے گا۔<br>\nمیری حکومت کا وژن ہے کہ BAJK کو <strong>شیڈولڈ بینک</strong> بنایا جائے اور ہم اس ترقی کے پیچھے پوری طرح کھڑے ہیں۔ یہ شراکت نئے معاشی مواقع پیدا کرے گی، خصوصاً نوجوانوں اور کاروباری افراد کے لیے۔ میں تمام اسٹیک ہولڈرز، خاص طور پر فنانس سیکرٹری کو مبارکباد پیش کرتا ہوں۔\"</em><br><br>\n\n<strong>نفاذ کا وقت کار</strong><br>\nیہ سسٹم مرحلہ وار نافذ کیا جائے گا اور <strong>اگلے 24 ماہ کے اندر تمام برانچز میں مکمل طور پر فعال</strong> ہو جائے گا، جس سے بینکنگ سروسز میں انقلابی تبدیلی آئے گی۔<br><br>\n\n<strong>BAJK کے بارے میں</strong><br>\n<strong>بینک آف آزاد جموں و کشمیر (BAJK)</strong> ایک سرکاری مالیاتی ادارہ ہے جو جامع بینکاری اور معاشی ترقی کے لیے وقف ہے۔ اپنی وسیع ہوتی برانچ نیٹ ورک اور ڈیجیٹل وژن کے تحت، BAJK خطے کی مالی ترقی میں اہم کردار ادا کر رہا ہے۔\n</div>', 'Muzaffarabad  The Bank of Azad Jammu and Kashmir (BAJK) has taken a monumental leap toward digital transformation by signing a landmark agreement with Malaysia-based global technology consortium Silve...', 'news-images/ceremony.jpg', '2025-07-11', 0, 'announcements', 'bajk-silverlake-core-banking-agreement-digital-banking-era', 1, '2025-07-17 08:08:32', '2026-02-02 05:16:44'),
(2, 'Inauguration of the 88th Branch of the Bank of Azad Jammu and Kashmir in Raheemkot', 'Muzaffarabad<br>\nThe Bank of Azad Jammu and Kashmir has inaugurated its <strong>88th branch</strong> in Raheemkot, an area of Chikar. The inauguration ceremony took place on Wednesday, with the <strong>Speaker of the AJK Legislative Assembly, Chaudhry Latif Akbar</strong>, and the <strong>Minister for Finance & Cooperative and Chairman of the Bank, Khan Abdul Majid Khan</strong>, as the chief guests. Both dignitaries formally inaugurated the branch by cutting the ribbon and unveiling the plaque. Chaudhry Latif Akbar also opened his personal account at the new branch.<br><br>\n\nPresent at the occasion were <strong>President/CEO Mr. Shahid Shehzad Mir</strong>, <strong>Divisional Head CRBD Raja Ghulam Mustafa</strong>, <strong>Divisional Head Operations Ehtesham Malik</strong>, <strong>Divisional Head CMD Muhammad Imtiaz Shaheen</strong>, <strong>Divisional Head SAMD Masood Ilyas Khan</strong>, <strong>Regional Head Muzaffarabad Jamal Anwar Khan</strong>, senior bank officials, and a large number of local residents.<br><br>\n\n<strong>A Significant Step for the Region</strong><br>\nWith the opening of the new branch, a large population in Raheemkot and surrounding areas has gained access to banking facilities. The branch will serve people from areas such as <em>Namet Phutoat, Nakar, Perot, Sarakarr, Siri, Panjili, Upper Phutoat, Kiyati, Prem Kot, Katikar, Kundiali, Haveli, Lower Kot, Mashtamba, Jhagda Gali, Riyat, Mera Saru, Basti Qureshiyan, Basuj Chachiyan, Mera Kalan, Makhiyala Gali, Manja Ker, and Taap</em>.<br><br>\n\n<strong>An Area Rich in Educational and Health Facilities</strong><br>\nRahim Kot hosts a <em>girls’ college, a boys’ college, a rural health center, a veterinary hospital, an agriculture office, a police check post, a community hall</em>, and various other government offices. The new bank branch is expected to <strong>promote commercial activity</strong> and provide <strong>easier access to banking services</strong> for students, farmers, traders, and the general public.<br><br>\n\n<strong>Public Sentiment</strong><br>\nLocal residents expressed gratitude to the bank and government, calling this a vital step toward the region’s development. They noted that they would no longer need to travel far for banking services, and all financial transactions could now be handled with ease.<br><br>\n\n<strong>Bank President Mr. Shahid Shehzad Mir</strong> stated that the bank’s mission is to deliver <strong>quality financial services</strong> to remote and underdeveloped areas. He pledged that the bank will continue to open branches in other parts of Azad Kashmir to provide <strong>modern banking facilities</strong> to the public. A special prayer was offered for the <strong>success and development</strong> of the bank, the state, and the country.<br><br>\n\n<div dir=\"rtl\" style=\"text-align: right;\">\n<strong>مظفر آباد</strong><br>\nبینک آف آزاد جموں وکشمیر نے اپنی <strong>88 ویں برانچ</strong> کا چکار کے علاقے رحیم کوٹ میں افتتاح کر دیا ہے۔ بدھ کے روز رحیم کوٹ برانچ کی افتتاحی تقریب کے مہمان خصوصی آزاد جموں و کشمیر قانون ساز اسمبلی کے اسپیکر <strong>چوہدری لطیف اکبر</strong> اور وزیر خزانہ و کواپریٹو اور چیئرمین بینک <strong>خان عبدالماجد خان</strong> تھے۔ دونوں مہمانوں نے بینک کا افتتاح ربن کاٹ کر کیا، تختی کی نقاب کشائی کی گئی اور چوہدری لطیف اکبر نے اپنا ذاتی اکاؤنٹ بھی نئی برانچ میں کھول دیا۔<br><br>\n\nاس موقع پر بینک آف آزاد جموں وکشمیر کے صدر/سی ای او <strong>شاہد شہزاد میر</strong>، ڈی ایچ سی آر بی ڈی <strong>راجہ غلام مصطفی</strong>، ڈی ایچ آپریشنز <strong>احتشام ملک</strong>، ڈی ایچ سی ایم ڈی <strong>محمد امتیاز شاہین</strong>، ڈی ایچ ایس اے ایم ڈی <strong>مسعود الیاس خان</strong>، ریجنل ہیڈ مظفرآباد <strong>جمال انور خان</strong>، بینک کے اعلیٰ عہدیداران اور مقامی لوگوں کی بڑی تعداد موجود تھی۔<br><br>\n\n<strong>علاقے کے لیے ایک اہم قدم</strong><br>\nنئی برانچ کے افتتاح سے <strong>رحیم کوٹ</strong> اور گردونواح کی ایک بڑی آبادی کو بینکنگ سہولیات میسر آئی ہیں۔ اس برانچ کے تحت <em>نامٹ فٹوٹ، نکر، پیروٹ، سراکڑ، سیری، پنجیلی، اپر فٹوٹ، کیاٹی، پریم کوٹ، کٹیکر، کنڈیالی، حویلی، لوئر کوٹ، مشٹمبا، جھگڑاگلی، ریاٹ، میرا سرو، بستی قریشیاں، بسوج چچیاں، میرا کلاں، مکھیالہ گلی، منجا کیر، ٹاپ</em> جیسے علاقوں کے لوگ مستفید ہوں گے۔<br><br>\n\n<strong>تعلیمی و صحت کی سہولیات سے مالامال علاقہ</strong><br>\nرحیم کوٹ میں <em>لڑکیوں کا کالج، لڑکوں کا کالج، رورل ہیلتھ سینٹر، ویٹرنری ہسپتال، زراعت کا دفتر، پولیس چوکی، کمیونٹی ہال</em> اور دیگر سرکاری دفاتر موجود ہیں۔ نئے بینک برانچ کے افتتاح سے نہ صرف <strong>تجارتی سرگرمیوں کو فروغ</strong> ملے گا بلکہ <strong>طلباء، کسانوں، تاجروں اور عام شہریوں کو بینکنگ خدمات تک آسان رسائی</strong> میسر آئے گی۔<br><br>\n\n<strong>عوام کے جذبات</strong><br>\nمقامی لوگوں نے بینک اور حکومت کا شکریہ ادا کرتے ہوئے اس اقدام کو <strong>علاقے کی ترقی کے لیے ایک اہم قدم</strong> قرار دیا۔ ان کا کہنا تھا کہ اب انہیں بینکنگ کے لیے دور دراز کا سفر نہیں کرنا پڑے گا اور تمام مالی لین دین آسانی سے ہو سکے گا۔<br><br>\n\nبینک کے صدر <strong>شاہد شہزاد میر</strong> نے کہا کہ بینک کا مقصد <strong>دور دراز اور پسماندہ علاقوں میں معیاری مالیاتی خدمات</strong> پہنچانا ہے۔ انہوں نے عہد کیا کہ بینک آنے والے دنوں میں بھی آزاد کشمیر کے دیگر علاقوں میں اپنی شاخیں کھول کر <strong>عوام کو جدید بینکنگ سہولیات</strong> فراہم کرتا رہے گا۔<br><br>\n\nاس موقع پر <strong>بینک، ریاست اور ملک کی ترقی، کامیابی</strong> کے لیے دعا کی گئی۔\n</div>', 'Muzaffarabad\nThe Bank of Azad Jammu and Kashmir has inaugurated its 88th branch in Raheemkot, an area of Chikar. The inauguration ceremony took place on Wednesday, with the Speaker of the AJK Legislat...', 'news-images/88branch.jpg', '2025-07-02', 0, 'banking', 'inauguration-88th-bajk-branch-rahim-kot', 1, '2025-07-17 08:08:32', '2026-02-02 05:18:41'),
(3, 'BAJK Celebrates Record-Breaking Rs. 46 Billion Deposit Milestone', 'Muzaffarabad, July 01, 2025 – The Bank of Azad Jammu & Kashmir (BAJK) has made history by crossing <strong>Rs. 46 billion in deposits</strong>, setting a new benchmark in its financial journey.<br><br>\n\nA ceremony was held at <strong>BAJK\'s Main Branch Muzaffarabad</strong> to commemorate this achievement. The event was presided over by <strong>Mr. Khan Abdul Majid Khan</strong>, Minister for Finance & Cooperative AJK and <strong>Chairman of BAJK</strong>, who lauded the efforts of <strong>President/CEO Mr. Shahid Shahzad Mir</strong>, the dedicated BAJK team, and all stakeholders.<br><br>\n\nDivisional heads, executives, and officials were also present on this momentous occasion.<br><br>\n\nIn his address, Chairman Mr. Khan Abdul Majid Khan outlined the bank\'s ambitious roadmap, highlighting its imminent transition to a <strong>scheduled bank</strong>. He called upon employees to <strong>embrace upcoming challenges and opportunities</strong> with renewed vigor. Reiterating BAJK\'s customer-centric approach, he emphasized treating clients with the utmost <strong>respect, dignity, and care</strong>. The Chairman also reaffirmed the bank\'s commitment to <strong>employee growth and development</strong>, ensuring that staff progression keeps pace with institutional expansion.<br><br>\n\nEarlier, <strong>President/CEO Mr. Shahid Shahzad Mir</strong> revealed that BAJK had not only achieved unprecedented deposit growth but had also surpassed its <strong>December 2025 profit targets six months ahead of schedule in June 2025</strong>. He attributed this success to the <strong>collective hard work of the BAJK team, DH CRBD, all Regional Heads, managers, and the entire field team</strong>, unwavering stakeholder support, and the visionary leadership of the AJK Prime Minister, Chairman BAJK, and the Board of Directors.<br><br>\n\nThe celebrations culminated in a <strong>traditional cake-cutting ceremony</strong>, marking this significant achievement and symbolizing BAJK\'s promising future.<br><br>\n\n<div dir=\"rtl\" style=\"text-align: right;\">\n<strong>مظفرآباد، 01 جولائی 2025</strong> – بینک آف آزاد جموں و کشمیر (BAJK) نے تاریخ رقم کرتے ہوئے <strong>46 ارب روپے کے ڈیپازٹس</strong> کا سنگِ میل عبور کر لیا، جو کہ اس کے مالی سفر میں ایک نئی کامیابی کی علامت ہے۔<br><br>\n\nاس اہم کامیابی کی یاد میں BAJK کی مرکزی شاخ مظفرآباد میں ایک پروقار تقریب منعقد ہوئی۔ اس موقع کی صدارت وزیر خزانہ و تعاون حکومت آزاد جموں و کشمیر اور چیئرمین BAJK، <strong>جناب خان عبدالمجید خان</strong> نے کی، جنہوں نے <strong>صدر/سی ای او جناب شاہد شہزاد میر</strong>، BAJK کی محنتی ٹیم اور تمام اسٹیک ہولڈرز کی کاوشوں کو سراہا۔<br><br>\n\nتقریب میں ڈویژنل سربراہان، اعلیٰ افسران، اور دیگر عملہ بھی شریک تھا۔<br><br>\n\nاپنے خطاب میں چیئرمین جناب خان عبدالمجید خان نے بینک کے مستقبل کے جامع منصوبے کا خاکہ پیش کیا، جس میں جلد <strong>شیڈیول بینک</strong> میں منتقلی کو نمایاں حیثیت دی گئی۔ انہوں نے ملازمین پر زور دیا کہ وہ آئندہ چیلنجز اور مواقع کو نئی توانائی اور جذبے کے ساتھ قبول کریں۔<br><br>\n\nانہوں نے BAJK کی <strong>کسٹمر سینٹرک اپروچ</strong> کو اجاگر کرتے ہوئے کہا کہ صارفین سے عزت، وقار اور خلوص کے ساتھ پیش آنا ہماری اولین ترجیح ہے۔ چیئرمین نے یہ بھی یقین دلایا کہ ادارے کی ترقی کے ساتھ ساتھ <strong>ملازمین کی پیشہ ورانہ ترقی</strong> بھی یقینی بنائی جائے گی۔<br><br>\n\nقبل ازیں، <strong>صدر/سی ای او جناب شاہد شہزاد میر</strong> نے انکشاف کیا کہ نہ صرف بینک نے ریکارڈ ڈیپازٹ گروتھ حاصل کی ہے بلکہ <strong>دسمبر 2025 کے منافع کے اہداف</strong> کو بھی چھ ماہ قبل <strong>جون 2025</strong> میں عبور کر لیا ہے۔<br><br>\n\nانہوں نے اس کامیابی کو <strong>BAJK ٹیم، DH CRBD، تمام ریجنل ہیڈز، منیجرز، فیلڈ ٹیم، اسٹیک ہولڈرز کے تعاون</strong> اور وزیر اعظم آزاد کشمیر، چیئرمین BAJK اور بورڈ آف ڈائریکٹرز کی وژنری قیادت کا نتیجہ قرار دیا۔<br><br>\n\nتقریب کا اختتام ایک <strong>روایتی کیک کاٹنے کی تقریب</strong> پر ہوا، جو اس اہم کامیابی کی خوشی اور BAJK کے روشن مستقبل کی علامت تھی۔\n</div>', 'Muzaffarabad, July 01, 2025 – The Bank of Azad Jammu & Kashmir (BAJK) has made history by crossing Rs. 46 billion in deposits, setting a new benchmark in its financial journey.\n\nA ceremony was held ...', 'news-images/46 million.jpg', '2025-07-01', 0, 'announcements', 'bajk-celebrates-record-breaking-rs-46-billion-deposit-milestone', 1, '2025-07-17 08:08:32', '2026-02-02 05:19:54'),
(4, '90th Meeting of the Board of Directors of Bank of Azad Jammu & Kashmir (BAJK) Held Successfully', '<div dir=\"ltr\">\nThe 90th meeting of the Board of Directors of Bank of Azad Jammu & Kashmir (BAJK) was held at the Bank\'s Head Office in Muzaffarabad on Tuesday. The meeting was chaired by Mr. Khan Abdul Majid Khan, Honorable Minister for Finance & Cooperatives, Government of Azad Jammu & Kashmir, and Chairman of BAJK.<br>\nAll members attended the meeting in person, except Ms. Bushra Naz Malik, who joined via Zoom. Mr. Mubashar Nabi also participated following the notification of his further extension as a Board member.<br><br>\n\n<strong>Key Attendees:</strong><br>\nPresident & CEO Mr. Shahid Shahzad Mir,<br>\nSecretary Finance, AJK Mr. Islam Zaib,<br>\nSecretary Industries & Commerce Mr. Khalid Mahmood Mirza,<br>\nSecretary Law & Justice Mr. Muhammad Sajjad,<br>\nMs. Bushra Naz Malik (via Zoom),<br>\nMr. Mubashar Nabi,<br>\nCompany Secretary Dr. Adnanullah Khan.<br><br>\n\n<strong>Key Discussions & Decisions:</strong><br>\n1. Core Banking System Upgrade:<br>\nProgress on the MoU with Silverlake for modernizing BAJK\'s Core Banking System was reviewed, ensuring enhanced digital banking services, operational efficiency, and speedy implementation.<br><br>\n\n2. Other Strategic Matters:<br>\nThe Board discussed ongoing and future initiatives to strengthen financial performance, customer service, and technological advancement.<br><br>\n\n<strong>Chairman\'s Appreciation:</strong><br>\nChairman Mr. Khan Abdul Majid Khan praised the efforts of BAJK\'s management, Board members, and stakeholders in driving the Bank\'s success. He emphasized the commitment to innovation, growth, and excellence, reinforcing BAJK\'s vision to become a leading financial institution in the region.<br><br>\n\n<strong>Way Forward:</strong><br>\nThe Board reiterated its focus on sustainable growth, service expansion, and the adoption of advanced banking technologies to better serve customers and stakeholders.\n</div>\n\n<hr>\n\n<div dir=\"rtl\" style=\"text-align: right;\">\nبینک آف آزاد جموں و کشمیر (BAJK) کے بورڈ آف ڈائریکٹرز کا 90 واں اجلاس منگل کے روز بینک کے ہیڈ آفس مظفرآباد میں منعقد ہوا۔ اجلاس کی صدارت محترم خان عبدالمجید خان، وزیر خزانہ و کوآپریٹو، حکومت آزاد جموں و کشمیر، اور چیئرمین BAJK نے کی۔<br><br>\n\nتمام اراکین نے اجلاس میں ذاتی طور پر شرکت کی، سوائے محترمہ بشریٰ ناز ملک کے، جنہوں نے زوم کے ذریعے شرکت کی۔ جناب مبشر نبی نے بھی اجلاس میں شرکت کی، جنہیں بطور بورڈ ممبر مزید توسیع دی گئی ہے۔<br><br>\n\n<strong>اہم شرکاء:</strong><br>\nصدر و سی ای او جناب شاہد شہزاد میر<br>\nسیکرٹری خزانہ، آزاد کشمیر جناب اسلام زیب<br>\nسیکرٹری صنعت و تجارت جناب خالد محمود مرزا<br>\nسیکرٹری قانون و انصاف جناب محمد سجاد<br>\nمحترمہ بشریٰ ناز ملک (زوم کے ذریعے)<br>\nجناب مبشر نبی<br>\nکمپنی سیکرٹری ڈاکٹر عدنان اللہ خان<br><br>\n\n<strong>اہم امور و فیصلے:</strong><br>\n<strong>1. کور بینکنگ سسٹم کی اپ گریڈیشن:</strong><br>\nسلورلیک کمپنی کے ساتھ کور بینکنگ سسٹم کو جدید بنانے کے معاہدے (MoU) میں پیش رفت کا جائزہ لیا گیا، تاکہ ڈیجیٹل بینکنگ خدمات، آپریشنل کارکردگی، اور تیزی سے عملدرآمد کو بہتر بنایا جا سکے۔<br><br>\n\n<strong>2. دیگر حکمتِ عملی امور:</strong><br>\nبورڈ نے مالی کارکردگی، صارف خدمات، اور ٹیکنالوجی میں ترقی سے متعلق موجودہ اور مستقبل کے اقدامات پر تبادلہ خیال کیا۔<br><br>\n\n<strong>چیئرمین کی ستائش:</strong><br>\nچیئرمین محترم خان عبدالمجید خان نے بینک کی انتظامیہ، بورڈ اراکین اور اسٹیک ہولڈرز کی کوششوں کو سراہا، جنہوں نے بینک کی کامیابی میں اہم کردار ادا کیا۔ انہوں نے جدت، ترقی اور عمدگی کے عزم پر زور دیا، اور کہا کہ بینک کو خطے کا ایک ممتاز مالیاتی ادارہ بنانے کے ویژن کو مزید مضبوط کیا جا رہا ہے۔<br><br>\n\n<strong>آئندہ کا لائحہ عمل:</strong><br>\nبورڈ نے پائیدار ترقی، سروسز کی توسیع، اور جدید بینکاری ٹیکنالوجیز کو اپنانے پر زور دیا تاکہ صارفین اور اسٹیک ہولڈرز کو بہتر خدمات فراہم کی جا سکیں۔<br>\n</div>', 'The 90th meeting of the Board of Directors of Bank of Azad Jammu & Kashmir (BAJK) was held at the Bank\'s Head Office in Muzaffarabad on Tuesday. The meeting was chaired by Mr. Khan Abdul Majid Khan, ...', 'news-images/90thmeeting.jpg', '2025-06-25', 0, 'banking', '90th-meeting-board-of-directors-bajk-held-successfully', 1, '2025-07-17 08:08:32', '2026-02-02 05:21:57'),
(5, 'Bank of Azad Jammu & Kashmir Holds 89th Board Meeting: Strategic Approvals and Vision for Future Growth', '<strong>BAJK Board of Directors 89th Meeting Held at Bank Head Office, Muzaffarabad</strong><br>\nMuzaffarabad<br>\nJune 04, 2025<br>\nThe 89th meeting of the Board of Directors of Bank of Azad Jammu & Kashmir (BAJK) was held on Wednesday at the Bank’s Head Office in Muzaffarabad under the chairmanship of Mr. Khan Abdul Majid Khan, Honorable Minister for Finance & Cooperatives, Government of Azad Jammu & Kashmir, and Chairman of BAJK.<br>\nThe meeting was attended by President & CEO Mr. Shahid Shahzad Mir, members of the Board of Directors, Secretary Finance, AJK Mr. Islam Zaib, Secretary Industries & Commerce Mr. Khalid Mahmood Mirza, Secretary Law & Justice Mr. Muhammad Sajjad, Ms. Bushra Naz Malik (via Zoom), and Company Secretary Dr. Adnanullah Khan.<br><br>\n\n<strong>Key Agenda Items Discussed & Approved:</strong><br>\n1. Financial Accounts (Q1 2025): The Board reviewed and approved the financial results for the first quarter of 2025, reflecting strong growth in profitability, assets, deposits, and remittances.<br><br>\n2. Core Banking Modernization (MoU with Silverlake): A detailed briefing was given on the Memorandum of Understanding (MoU) with Silverlake for the upgradation of BAJK’s Core Banking System, aimed at enhancing digital banking services and operational efficiency.<br><br>\n3. Consumer-Friendly Initiatives: Multiple public-oriented steps were discussed.<br><br>\n\n<strong>Chairman’s Remarks:</strong><br>\nChairman Mr. Khan Abdul Majid Khan commended the dedication of BAJK’s team, management, and stakeholders in achieving remarkable milestones. He reiterated the Bank’s commitment to excellence, innovation, and growth, ensuring BAJK emerges as a leading financial institution under the government’s patronage.<br><br>\n\n<strong>Future Vision:</strong><br>\nThe Board reaffirmed its resolve to sustain progress, expand services, and adopt cutting-edge banking technologies for the benefit of customers and stakeholders.<br><br><br>\n\n<div dir=\"rtl\" style=\"text-align: right;\">\n<strong>بینک آف آزاد جموں و کشمیر کے بورڈ آف ڈائریکٹرز کا 89 واں اجلاس</strong><br>\nمظفرآباد<br>\n4 جون 2025<br><br>\n\nبینک آف آزاد جموں و کشمیر (BAJK) کے بورڈ آف ڈائریکٹرز کا 89 واں اجلاس بدھ کے روز بینک کے ہیڈ آفس مظفرآباد میں منعقد ہوا۔ اجلاس کی صدارت محترم خان عبدالماجد خان، وزیر خزانہ و کوآپریٹو، حکومت آزاد جموں و کشمیر اور چیئرمین BAJK نے کی۔<br><br>\n\nاجلاس میں صدر و چیف ایگزیکٹو آفیسر جناب شاہد شہزاد میر، بورڈ آف ڈائریکٹرز کے ممبران، سیکرٹری خزانہ آزاد کشمیر جناب اسلام زیب، سیکرٹری صنعت و تجارت جناب خالد محمود مرزا، سیکرٹری قانون و انصاف جناب محمد سجاد، محترمہ بشریٰ ناز ملک (زوم کے ذریعے)، اور کمپنی سیکرٹری ڈاکٹر عدنان اللہ خان نے شرکت کی۔<br><br>\n\n<strong>زیر بحث اور منظور شدہ اہم ایجنڈا نکات:</strong><br>\n1. مالیاتی اکاؤنٹس (پہلی سہ ماہی 2025): بورڈ نے سال 2025 کی پہلی سہ ماہی کے مالیاتی نتائج کا جائزہ لیا اور منظوری دی، جن میں منافع، اثاثہ جات، ڈپازٹس اور ترسیلات زر میں نمایاں اضافہ ظاہر کیا گیا۔<br><br>\n\n2. کور بینکنگ نظام کی جدید کاری (Silverlake کے ساتھ مفاہمتی یادداشت): Silverlake کمپنی کے ساتھ کور بینکنگ سسٹم کی اپ گریڈیشن سے متعلق مفاہمتی یادداشت (MoU) پر تفصیلی بریفنگ دی گئی، جس کا مقصد ڈیجیٹل بینکنگ خدمات اور عملیاتی کارکردگی کو بہتر بنانا ہے۔<br><br>\n\n3. صارف دوست اقدامات: متعدد عوامی مفاد میں اقدامات بھی زیر غور آئے۔<br><br>\n\n<strong>چیئرمین کے تاثرات:</strong><br>\nچیئرمین محترم خان عبدالماجد خان نے BAJK کی ٹیم، انتظامیہ اور تمام شراکت داروں کی محنت اور لگن کو سراہا اور بینک کی ترقی، جدت اور معیار کے لیے مسلسل کوششوں کے عزم کا اظہار کیا۔ انہوں نے اس بات پر زور دیا کہ حکومت کی سرپرستی میں BAJK ایک نمایاں مالیاتی ادارہ بن کر ابھرے گا۔<br><br>\n\n<strong>مستقبل کا وژن:</strong><br>\nبورڈ نے اس عزم کا اعادہ کیا کہ وہ ترقی کا سفر جاری رکھے گا، خدمات میں توسیع کرے گا، اور صارفین و شراکت داروں کے مفاد میں جدید ترین بینکاری ٹیکنالوجی اپنائے گا۔<br>\n</div>', 'BAJK Board of Directors 89th Meeting Held at Bank Head Office, Muzaffarabad\nMuzaffarabad\nJune 04, 2025\nThe 89th meeting of the Board of Directors of Bank of Azad Jammu & Kashmir (BAJK) was held on Wed...', 'news-images/89meeting.jpg', '2025-06-04', 0, 'general', '89th-board-meeting-bajk-muzaffarabad', 1, '2025-07-17 08:08:32', '2026-01-29 12:43:51'),
(6, 'Bank of Azad Jammu and Kashmir Signs Strategic MoU with Silverlake to Advance Digital Banking Infrastructure', 'The Bank of Azad Jammu and Kashmir (BAJK) has signed a Memorandum of Understanding (MoU) with Silverlake, a world-renowned Malaysian company, marking a significant step towards digitalization and scheduling. The MoU was signed during a ceremony held in Kuala Lumpur, Malaysia, after which documents were exchanged. Azad Jammu and Kashmir Minister for Finance and Cooperatives/Chairman of BAJK, Khan Abdul Majid Khan, President/CEO of BAJK, Mr. Shahid Shahzad Mir, and representatives of Silverlake were present on the occasion.<br>\nNotably, the local partner of Silverlake, I-Consult played an instrumental role in facilitating this MoU, and its representatives Mr. Shahid Ahmed Khan and Mr. Khurram Jamal were also present during the signing ceremony, contributing to the successful collaboration.<br>\nSilverlake is a leading company providing core banking and digital technology services to over 370 banks and financial institutions across 80 countries. It is globally recognized for its advanced core banking software technology and a 100% success rate.<br>\nWith this agreement, BAJK has achieved a major milestone in modernizing its banking infrastructure. The partnership will enable the bank to implement the latest banking software, a key requirement for obtaining a scheduling license under the regulatory framework of the State Bank of Pakistan. This development will bring Kashmir Bank on par with all major banks in Pakistan.<br>\nSpeaking at the event, Chairman Khan Abdul Majid Khan stated that this MoU is not just a technical upgrade but the foundation of a revolution. It will allow BAJK to serve its customers more efficiently and transparently while contributing to the economic growth and prosperity of Azad Jammu and Kashmir.<br><br>\n\n<div dir=\"rtl\" style=\"text-align: right;\">\nبینک آف آزاد جموں و کشمیر نے شیڈولنگ کے حصول اور ڈیجیٹلائزیشن کی جانب اہم پیش رفت کرتے ہوئے ملائیشیا کی عالمی شہرت یافتہ کمپنی سلور لیک کے ساتھ مفاہمت کی یادداشت پر دستخط کر دیئے ہیں۔ بدھ کی شام کوالالمپور، ملائیشیا میں منعقدہ ایک تقریب کے دوران مفاہمت کی یادداشت پر دستخط کے بعد دستاویزات کا تبادلہ کیا گیا۔ اس موقع پر آزاد جموں و کشمیر کے وزیر خزانہ و کواپریٹوز / چیئرمین بینک خان عبدالماجد خان، صدر/ سی ای او بینک جناب شاہد شہزاد میر اور سلور لیک کے نمائندگان بھی موجود تھے۔<br><br>\nسلور لیک دنیا کے 80 ممالک میں 370 سے زیادہ بینکوں اور مالیاتی اداروں کو کور بینکنگ اور دیگر ڈیجیٹل ٹیکنالوجی خدمات فراہم کرنے والی کمپنی ہے جو کور بینکنگ سافٹ ویئر ٹیکنالوجی اور اس کے سو فیصد کامیابی کے لئے بھی مشہور ہے، کے ساتھ اس اہم معاہدہ سے بینک آف آزاد جموں و کشمیر نے اپنے بینکنگ انفراسٹرکچر میں جدت لانے کے لئے ایک اہم سنگ میل عبور کیا ہے۔<br><br>\nاس شراکت داری کے ذریعہ بینک میں جدید ترین بینکنگ سافٹ ویئر کی تنصیب کی جائے گی، جو کہ اسٹیٹ بینک آف پاکستان کے ریگولیٹری فریم ورک کے تحت شیڈولنگ لائسنس کے حصول کے لئے ایک بنیادی ضرورت ہے۔ اس تبدیلی کے نتیجہ میں کشمیر بینک پاکستان کے تمام بینکوں کے ساتھ برابری کی پوزیشن پر آ جائے گا۔<br><br>\nتقریب سے خطاب کرتے ہوئے، چیئرمین بینک خان عبدالماجد خان نے کہا کہ مفاہمت کی یہ یادداشت صرف ایک تکنیکی اپ گریڈیشن نہیں ہے بلکہ ایک انقلاب کی بنیاد ہے۔ یہ ہمیں آزاد جموں کشمیر کی اقتصادی ترقی اور خوشحالی میں اپنا کردار ادا کرتے ہوئے اپنے صارفین کو زیادہ بہتر اور شفافیت کے ساتھ خدمت کرنے کا موقع دے گا۔<br><br>\nسلور لیک کی ٹیم نے کہا سلور لیک کو کشمیر بینک کی ترقی میں اپنا کردار ادا کرنے پر فخر ہے اور یہ کور بینکنگ سلوشن پاکستان کے مالیاتی منظر نامے کے لئے ایک معیار قائم کرے گا۔ یہ معاہدہ طویل المدتی شراکت کی بنیاد بنے گا۔ دونوں اداروں نے اپنی ٹیموں کی محنت کو سراہا اور اس منصوبے کو کامیاب بنانے کا عہد کیا۔<br>\n</div>', 'The Bank of Azad Jammu and Kashmir (BAJK) has signed a Memorandum of Understanding (MoU) with Silverlake, a world-renowned Malaysian company, marking a significant step towards digitalization and sche...', 'news-images/silverlink.jpg', '2025-05-29', 0, 'general', 'bajk-signs-mou-with-silverlake-digital-banking', 1, '2025-07-17 08:08:32', '2026-01-29 12:43:51'),
(7, 'Bank of AJK Convenes 88th Board of Directors Meeting Under the Chairmanship of Finance Minister Khan Abdul Majid Khan', 'The 88th Meeting of the Board of Directors of Bank of Azad Jammu & Kashmir Held Under the Chairmanship of Finance Minister Khan Abdul Majid Khan<br>\nThe 88th meeting of the Board of Directors of Bank of Azad Jammu & Kashmir was held under the chairmanship of Mr. Khan Abdul Majid Khan, Minister for Finance & Cooperatives, Government of Azad Jammu & Kashmir, and Chairman of the Bank. The meeting was convened on Monday at the Bank’s Head Office.<br>\nThe meeting was attended by Mr. Shahid Shahzad Mir, President & CEO, members of the Board of Directors, Mr. Islam Zaib, Secretary Finance, Government of AJK, Mr. Khalid Mahmood Mirza, Secretary Industries & Commerce, Mr. Muhammad Sajjad, Secretary Law & Justice, Ms. Bushra Naz Malik (via Zoom), and Dr. Adnanullah Khan, Company Secretary.<br>\nThe meeting included a review of various operational agenda items, including the financial accounts for the year 2024 (as of December 31, 2024), which were discussed in detail and approved. A comprehensive briefing was also given on core banking matters.<br>\nAccording to the financial accounts, the Bank continues to witness consistent growth in profitability, assets, deposits, and remittances. Attractive loan schemes on easy terms and low markup rates are being provided to customers.<br>\nThe Board appreciated the outstanding performance and cooperation of all stakeholders and reaffirmed its commitment to continue the Bank’s journey of success and progress.<br>\nOn this occasion, the Chairman stated that every effort is being made to position the institution among the leading banks under the patronage of the government. He added that with the staff’s hard work, teamwork, and the full support of valued customers, the Bank will continue to achieve excellent business results.<br><br>\n\n<div dir=\"rtl\" style=\"text-align: right;\">\nآزاد حکومت ریاست جموں وکشمیر کے وزیر خزانہ و امداد باہمی اور بینک آف آزاد جموں وکشمیر کے چیئرمین جناب خان عبدالماجد خان کی زیرصدارت بینک کے بورڈ آف ڈائریکٹرز کا 88 واں اجلاس منعقد ہوا۔ پیر کے روز بینک کے ہیڈ آفس میں منعقدہ اجلاس میں صدر و چیف ایگزیکٹو آفیسر جناب شاہد شہزاد میر، ڈائریکٹرز صاحبان، سیکریٹری فنانس حکومت آزاد جموں وکشمیر جناب اسلام زیب، سیکریٹری صنعت و حرفت جناب خالد محمود مرزا، سیکریٹری قانون و انصاف جناب محمد سجاد، زوم پر محترمہ بشریٰ ناز ملک اور کمپنی سیکریٹری ڈاکٹر عدنان اللہ خان نے شرکت کی۔<br><br>\nاجلاس میں گزشتہ سال 2024 کے فنانشل اکاؤنٹس (31 دسمبر 2024) سمیت مختلف آپریشنل ایجنڈے پیش کئے گئے جن کی مفصل بحث و مباحثہ کے بعد منظوری دی گئی۔ اجلاس کو کور بینکنگ سے متعلق مفصل بریفننگ دی گئی۔<br><br>\nفنانشل اکاؤنٹس کے مطابق بینک کے منافع، اثاثہ جات، ڈیپازٹس اور ترسیلات زر میں مسلسل اضافہ ہو رہا ہے۔ صارفین کو آسان شرائط اور کم از کم مارک اپ پر پرکشش قرضہ جات فراہم کئے جا رہے ہیں۔<br><br>\nبورڈ نے شاندار کارکردگی اور تعاون پر تمام سٹیک ہولڈرز کے کردار کی تعریف کرتے ہوئے بینک کی کامیابی اور ترقی کے سفر کو جاری رکھنے کے عزم کا اعادہ کیا۔<br><br>\nاس موقع پر جناب چیئرمین نے کہا کہ حکومت کی سرپرستی میں ادارے کو کامیاب اور صف اول کے بینکوں میں شامل کرنے کے لئے تمام کوششیں بروئے کار لائی جا رہی ہیں۔ انہوں نے کہا کہ عملے کی محنت، ٹیم ورک، معزز صارفین کے بھرپور تعاون سے بہترین بزنس نتائج کے حصول کا سلسلہ جاری رکھا جائے گا۔<br>\n</div>', 'The 88th Meeting of the Board of Directors of Bank of Azad Jammu & Kashmir Held Under the Chairmanship of Finance Minister Khan Abdul Majid Khan\nThe 88th meeting of the Board of Directors of Bank of A...', 'news-images/meeting2.jpg', '2025-04-28', 0, 'general', 'bank-of-ajk-88th-board-meeting-chaired-by-finance-minister-khan-abdul-majid', 1, '2025-07-17 08:08:32', '2026-01-29 12:43:51'),
(8, 'Bank of AJK Convenes 106th Management Committee Meeting to Drive Strategic Growth and Innovation', 'Bank of AJK Holds 106th Management Committee Meeting<br>\nThe Bank of Azad Jammu and Kashmir (BAJK) marked a significant milestone with the successful convening of its 106th Management Committee Meeting at the bank’s head office in Muzaffarabad. The session, held under the leadership of Khan Abdul Majid Khan, Chairman of the Board of Directors and Minister for Finance & Cooperative, AJK, brought together key decision-makers to review progress, strategize future initiatives, and reinforce the institution’s commitment to excellence in banking services.<br>\nKhan Abdul Majid Khan presided over the meeting, emphasizing the bank’s role in driving economic growth and financial inclusion across AJK. In his remarks, he underscored the importance of innovation, customer-centric policies, and adherence to governance standards. “Our focus remains on empowering communities through accessible financial solutions while maintaining transparency and accountability at all levels,” he stated.<br><br>\n\nCEO’s Comprehensive Briefing Highlights Achievements and Goals<br>\nMr. Shahid Shahzad Mir, President and CEO of BAJK, delivered a detailed presentation outlining the bank’s financial performance, operational milestones, and strategic priorities. Key highlights included:<br>\n- Financial Stability: Robust growth in deposits, loans, and profitability despite economic challenges.<br>\n- Digital Transformation: Progress on expanding digital banking services, including mobile apps and online platforms, to enhance customer convenience.<br>\n- Branch Network Expansion: Plans to extend services to underserved regions of AJK.<br>\n- Sustainability Initiatives: Commitment to green financing and CSR projects focused on education, healthcare, and disaster relief.<br>\nMr. Mir also addressed challenges such as cybersecurity, market competition, and regulatory compliance, stressing the need for agility and proactive risk management.<br><br>\n\nCollaborative Dialogue with Divisional Head<br>\nThe meeting saw active participation from all divisional heads, who provided updates on their respective domains, including retail banking, corporate finance, IT, HR, and compliance. Discussions centered on improving operational efficiency, staff training programs, and leveraging technology to streamline processes. The Company Secretary ensured adherence to procedural and regulatory frameworks during deliberations.<br><br>\n\nKey Resolutions and Forward-Looking Agenda<br>\n- Customer Experience Enhancement: Initiatives to reduce service turnaround times and introduce tailored financial products.<br>\n- Employee Development: Launch of skill-building workshops and leadership programs to foster a culture of excellence.<br>\n- Community Engagement: Strengthening partnerships with local stakeholders to address socio-economic needs.<br><br>\n\nA Unified Commitment to Progress<br>\nThe meeting concluded with a consensus on maintaining momentum toward BAJK’s vision of becoming a benchmark institution in regional banking. Chairman Khan commended the team’s dedication and urged continued collaboration to achieve shared goals.<br><br>\n\nLooking Ahead<br>\nAs BAJK moves forward, the resolutions from the 106th Management Committee Meeting will serve as a roadmap for sustainable growth, innovation, and community impact. The bank reaffirms its pledge to stakeholders: delivering value-driven banking while contributing to the prosperity of Azad Jammu and Kashmir.<br><br>\n\n<div dir=\"rtl\" style=\"text-align: right;\">\nبینک آف آزاد جموں و کشمیر کا 106واں مینجمنٹ کمیٹی اجلاس منعقد<br><br>\nبینک آف آزاد جموں و کشمیر (BAJK) نے ایک اہم سنگِ میل عبور کرتے ہوئے اپنا 106واں مینجمنٹ کمیٹی اجلاس کامیابی سے بینک کے ہیڈ آفس مظفرآباد میں منعقد کیا۔ یہ اجلاس خان عبدالمجید خان، چیئرمین بورڈ آف ڈائریکٹرز و وزیر خزانہ و کواپریٹو حکومت آزاد کشمیر، کی سربراہی میں منعقد ہوا۔ اجلاس میں اہم فیصلہ سازوں نے شرکت کی تاکہ بینک کی پیش رفت کا جائزہ لیا جا سکے، آئندہ کے اقدامات پر حکمت عملی تیار کی جا سکے اور بینکنگ خدمات میں اعلیٰ معیار کے عزم کو مزید مضبوط کیا جا سکے۔<br><br>\nخان عبدالمجید خان نے اجلاس کی صدارت کرتے ہوئے آزاد کشمیر میں اقتصادی ترقی اور مالی شمولیت کے فروغ میں بینک کے کردار کو اجاگر کیا۔ انہوں نے زور دیا کہ جدت، صارف دوست پالیسیوں اور معیاری طرز حکمرانی کو اپنانا وقت کی ضرورت ہے۔ انہوں نے کہا: \"ہماری توجہ ایسی مالی سہولیات کی فراہمی پر ہے جو عوام کو بااختیار بنائیں، شفافیت اور جوابدہی کو یقینی بناتے ہوئے۔\"<br><br>\n\n<b>صدر و سی ای او کی جامع بریفنگ: کارکردگی اور اہداف کی تفصیل</b><br>\nجناب شاہد شہزاد میر، صدر و چیف ایگزیکٹو آفیسر (CEO) BAJK نے ایک مفصل پریزنٹیشن دی جس میں بینک کی مالی کارکردگی، آپریشنل کامیابیاں اور اسٹریٹجک ترجیحات بیان کی گئیں۔<br>\nاہم نکات درج ذیل تھے:<br>\n- مالی استحکام: چیلنجز کے باوجود ڈپازٹس، قرضوں اور منافع میں مضبوط اضافہ۔<br>\n- ڈیجیٹل تبدیلی: موبائل ایپلیکیشنز اور آن لائن پلیٹ فارمز کے ذریعے ڈیجیٹل سروسز کی توسیع میں پیش رفت۔<br>\n- برانچ نیٹ ورک میں توسیع: آزاد کشمیر کے پسماندہ علاقوں تک بینکنگ خدمات کو وسعت دینے کے منصوبے۔<br>\n- پائیداری اقدامات: گرین فنانسنگ اور CSR منصوبے (تعلیم، صحت، قدرتی آفات سے بحالی پر توجہ)۔<br>\nانہوں نے سائبر سیکیورٹی، مارکیٹ میں مقابلہ اور ریگولیٹری تقاضوں جیسے چیلنجز کا بھی ذکر کیا اور چابک دستی اور خطرات کے فعال انتظام پر زور دیا۔<br><br>\n\n<b>ڈویژنل ہیڈز کے ساتھ تعمیری مکالمہ</b><br>\nاجلاس میں تمام ڈویژنل ہیڈز نے بھرپور شرکت کی اور اپنی اپنی فیلڈز جیسے ریٹیل بینکنگ، کارپوریٹ فنانس، آئی ٹی، ایچ آر اور کمپلائنس پر اپ ڈیٹس پیش کیں۔<br>\nتبادلہ خیال کا محور درج ذیل موضوعات رہے:<br>\n- آپریشنل کارکردگی کو بہتر بنانا<br>\n- عملے کی تربیتی پروگرام<br>\n- جدید ٹیکنالوجی کا استعمال<br>\n- پراسیسز کی آسانی اور بہتری<br>\nکمپنی سیکریٹری نے اجلاس کے دوران ریگولیٹری اور طریقہ کار کی مکمل پابندی کو یقینی بنایا۔<br><br>\n\n<b>اہم فیصلے اور مستقبل کی حکمت عملی</b><br>\n- کسٹمر تجربہ میں بہتری: فوری خدمات کی فراہمی اور صارفین کی ضروریات کے مطابق مالیاتی مصنوعات کی تیاری۔<br>\n- ملازمین کی ترقی: مہارت میں اضافے کے ورکشاپس اور لیڈرشپ پروگرامز کا آغاز۔<br>\n- سماجی شراکت داری: مقامی اسٹیک ہولڈرز کے ساتھ شراکت کو مضبوط بنانا تاکہ معاشرتی و اقتصادی مسائل حل کیے جا سکیں۔<br><br>\n\n<b>ترقی کے لیے مشترکہ عزم</b><br>\nاجلاس کا اختتام BAJK کے وژن کو حاصل کرنے کے لیے متحد رہنے کے عزم کے ساتھ ہوا، تاکہ اسے علاقائی بینکاری میں مثالی ادارہ بنایا جا سکے۔ چیئرمین خان عبدالمجید خان نے ٹیم کے جذبے کو سراہا اور باہمی تعاون سے آگے بڑھنے پر زور دیا۔<br><br>\n\n<b>مستقبل کی سمت</b><br>\nBAJK مستقبل میں اپنی ترقی، جدت، اور سماجی اثرات کے لیے 106ویں مینجمنٹ کمیٹی اجلاس کے فیصلوں کو رہنما اصول کے طور پر استعمال کرے گا۔ بینک نے اپنے تمام اسٹیک ہولڈرز سے یہ عہد دہرایا کہ وہ قدر پر مبنی بینکاری خدمات فراہم کرتے رہیں گے اور آزاد جموں و کشمیر کی خوشحالی میں کردار ادا کرتے رہیں گے۔<br>\n</div>', 'Bank of AJK Holds 106th Management Committee Meeting\nThe Bank of Azad Jammu and Kashmir (BAJK) marked a significant milestone with the successful convening of its 106th Management Committee Meeting at...', 'news-images/106meeting.jpg', '2025-04-11', 0, 'general', 'bajk-106th-management-committee-meeting-strategic-growth-innovation', 1, '2025-07-17 08:08:32', '2026-01-29 12:43:51');
INSERT INTO `news_announcements` (`id`, `title`, `content`, `excerpt`, `image`, `published_date`, `is_featured`, `category`, `slug`, `is_published`, `created_at`, `updated_at`) VALUES
(9, 'Recognizing Excellence: BAJK Awards Outstanding Employees for Exceptional Performance', 'Muzaffarabad<br>\n<strong>Bank of Azad Jammu and Kashmir Honors Top Performers in Prestigious Ceremony</strong><br><br>\n\nIn a ceremony marked by celebration and recognition, the Bank of Azad Jammu and Kashmir (BAJK) honored its outstanding employees for their exceptional contributions to the institution’s success. The event, held under the leadership of Chairman Khan Abdul Majid Khan—who also serves as AJK’s Minister for Finance and Cooperative—and President & CEO Shahid Shahzad Mir, underscored the bank’s commitment to excellence and employee motivation.<br><br>\n\n<strong>Dignitaries Celebrate Employee Achievements</strong><br>\nMr. Khan Abdul Majid Khan, in his dual role as Chairman of the bank and Minister for Finance, emphasized the critical link between employee dedication and institutional growth. Addressing the gathering, he praised the awardees for their hard work and innovation, stating, “Our employees are the backbone of this institution. Their relentless efforts not only drive the bank forward but also contribute to the economic prosperity of Azad Jammu and Kashmir.” He further highlighted the Government’s support for initiatives aimed at enhancing financial inclusion and modernizing banking services across the region.<br><br>\n\nAccompanying him, President & CEO Shahid Shahzad Mir echoed these sentiments, applauding the award-winning staff for their role in achieving milestones under his leadership. Mr. Mir remarked, “Today’s honorees exemplify the values of integrity, customer focus, and teamwork that define our bank. Their achievements inspire us all to aim higher and strengthen our position as a trusted financial partner for the people of AJK.”<br><br>\n\n<strong>Awards and Accolades</strong><br>\nThe ceremony saw cash prizes and certificates of appreciation distributed to top performers across various departments, including customer service, operational efficiency, and innovative problem-solving. The recipients, visibly moved by the recognition, expressed gratitude for the bank’s supportive environment and leadership. One awardee shared, “This acknowledgment fuels our passion to continue delivering excellence and contributing to the bank’s mission.”<br><br>\n\n<strong>A Vision for the Future</strong><br>\nThe event also served as a platform to reiterate the bank’s strategic goals. Mr. Khan and Mr. Mir outlined plans to expand digital banking solutions, improve rural financial access, and invest in employee development programs. Their shared vision positions the Bank of AJK as a catalyst for regional economic growth, aligned with the government’s agenda for sustainable development.<br><br>\n\n<strong>A Moment of Pride</strong><br>\nAttended by executives, the ceremony concluded on a note of collective pride and optimism. The fusion of formal recognition and heartfelt appreciation highlighted the institution’s culture of valuing its workforce.<br><br>\n\nAs the Bank of Azad Jammu and Kashmir continues to break new ground, events like these reaffirm its commitment to nurturing talent, fostering innovation, and serving the community with unwavering dedication. Here’s to many more milestones ahead!<br><br>\n\n<div dir=\"rtl\" style=\"text-align: right;\">\n<strong>مظفرآباد<br>\nبینک آف آزاد جموں و کشمیر کی جانب سے اعلیٰ کارکردگی دکھانے والے ملازمین کو خراجِ تحسین</strong><br><br>\n\nایک پُروقار تقریب میں بینک آف آزاد جموں و کشمیر (BAJK) نے اپنے نمایاں کارکردگی دکھانے والے ملازمین کو ادارے کی ترقی میں ان کے شاندار کردار پر اعزازات سے نوازا۔ یہ تقریب چیئرمین خان عبدالمجید خان (جو وزیر خزانہ و کواپریٹو، آزاد کشمیر بھی ہیں) اور صدر و سی ای او شاہد شہزاد میر کی قیادت میں منعقد ہوئی، جس کا مقصد بہترین کارکردگی کو سراہنا اور ملازمین کی حوصلہ افزائی کرنا تھا۔<br><br>\n\n<strong>شخصیات نے ملازمین کی کامیابیوں کو سراہا</strong><br>\nچیئرمین خان عبدالمجید خان نے اپنے خطاب میں کہا کہ ملازمین کی محنت اور لگن ہی ادارے کی ترقی کی بنیاد ہے۔ انہوں نے اعزاز حاصل کرنے والے ملازمین کی تعریف کرتے ہوئے کہا:<br>\n\"ہمارے ملازمین اس ادارے کی ریڑھ کی ہڈی ہیں۔ ان کی انتھک محنت نہ صرف بینک کو کامیابی کی راہ پر گامزن رکھتی ہے بلکہ آزاد جموں و کشمیر کی معاشی خوشحالی میں بھی اہم کردار ادا کرتی ہے۔\"<br><br>\n\nانہوں نے مزید کہا کہ حکومت مالی شمولیت کے فروغ اور بینکنگ خدمات کو جدید بنانے کے لیے مکمل تعاون فراہم کر رہی ہے۔<br><br>\n\nصدر و سی ای او جناب شاہد شہزاد میر نے بھی اعزاز یافتگان کی تعریف کی اور کہا:<br>\n\"آج کے اعزاز یافتہ ملازمین دیانتداری، صارف پر توجہ، اور ٹیم ورک کی اعلیٰ مثال ہیں۔ ان کی کامیابیاں ہم سب کو مزید بہتر کام کرنے کی ترغیب دیتی ہیں اور ہمیں ایک قابلِ اعتماد مالی ادارہ بننے کی راہ پر گامزن رکھتی ہیں۔\"<br><br>\n\n<strong>اعزازات اور انعامات</strong><br>\nتقریب کے دوران مختلف شعبوں میں نمایاں کارکردگی دکھانے والے ملازمین کو نقد انعامات اور تعریفی اسناد دی گئیں۔ شعبوں میں کسٹمر سروس، آپریشنل ایفیشنسی، اور جدید مسئلہ حل کرنے کی صلاحیت شامل تھیں۔<br><br>\n\nاعزاز حاصل کرنے والے ملازمین نے اپنے خیالات کا اظہار کرتے ہوئے بینک کے سازگار ماحول اور قیادت کی تعریف کی۔ ایک اعزاز یافتہ ملازم نے کہا:<br>\n\"یہ اعتراف ہماری محنت کو جِلا بخشتا ہے اور ہمیں مزید جوش و جذبے کے ساتھ ادارے کے مشن میں حصہ ڈالنے کی ترغیب دیتا ہے۔\"<br><br>\n\n<strong>مستقبل کے اہداف</strong><br>\nتقریب میں بینک کی آئندہ حکمت عملی پر بھی روشنی ڈالی گئی۔ چیئرمین اور سی ای او نے ڈیجیٹل بینکنگ میں وسعت، دیہی علاقوں میں مالی سہولیات کی بہتری، اور ملازمین کی تربیت و ترقی کے لیے اقدامات کا اعلان کیا۔<br>\nیہ وژن بینک آف AJK کو خطے کی معاشی ترقی کا محرک بنانے کے لیے حکومت کے پائیدار ترقی کے ایجنڈے سے ہم آہنگ ہے۔<br><br>\n\n<strong>فخر کا لمحہ</strong><br>\nاعلیٰ عہدیداران کی موجودگی میں تقریب کا اختتام فخر اور اُمید کے جذبات کے ساتھ ہوا۔ بینک کی جانب سے اپنے عملے کی باقاعدہ قدر دانی اور سراہنے کا یہ انداز ادارے کے مثبت اور باہمی احترام پر مبنی ماحول کو ظاہر کرتا ہے۔<br><br>\n\nجوں جوں بینک آف آزاد جموں و کشمیر نئی کامیابیاں حاصل کر رہا ہے، ایسی تقریبات اس بات کا ثبوت ہیں کہ ادارہ اپنے ہنرمند ملازمین کو قدر کی نگاہ سے دیکھتا ہے، جدت کی حوصلہ افزائی کرتا ہے، اور کمیونٹی کی خدمت کو اپنا مشن سمجھتا ہے۔\n</div>', 'Muzaffarabad\nBank of Azad Jammu and Kashmir Honors Top Performers in Prestigious Ceremony\n\nIn a ceremony marked by celebration and recognition, the Bank of Azad Jammu and Kashmir (BAJK) honored its ou...', 'news-images/honor.jpg', '2025-04-10', 0, 'announcements', 'bajk-awards-outstanding-employees-for-exceptional-performance', 1, '2025-07-17 08:08:32', '2026-02-02 05:26:55'),
(10, 'Barrister Sultan Mehmood Assures Maximum Facilitation for Bank of AJK’s Institutional Growth', 'Presidential Secretariat, Aiwan-e-Sadr, Kashmir House, Islamabad<br>\n07 April 2025<br>\nIslamabad () 07 April 2025<br><br>\n\n<strong>President of Azad Jammu and Kashmir, Barrister Sultan Mehmood Chaudhry, Holds Detailed Meeting with BAJK President Shahid Shahzad Mir at Kashmir House, Islamabad</strong><br><br>\n\nPresident of the Bank of Azad Jammu and Kashmir (BAJK), Mr. Shahid Shahzad Mir, held a comprehensive meeting with the President of Azad Jammu and Kashmir, Barrister Sultan Mehmood Chaudhry, at Kashmir House, Islamabad.<br><br>\n\nDuring the meeting, Mr. Shahid Shahzad Mir briefed the President in detail on the performance, ongoing challenges, and various affairs of the Bank of Azad Jammu and Kashmir.<br><br>\n\nPresident Barrister Sultan Mehmood Chaudhry instructed Mr. Mir to utilize all available resources to transform the Bank of Azad Jammu and Kashmir into a scheduled bank.<br><br>\n\nHe also assured his full cooperation and support in this regard.<br><br>\n\n<div dir=\"rtl\" style=\"text-align: right;\">\nصدارتی سیکرٹریٹ، ایوان صدر، کشمیر ہاؤس، اسلام آباد<br>\n07 اپریل 2025<br>\nاسلام آباد () 07 اپریل 2025ء<br><br>\n\n<strong>صدر ریاست آزاد جموں و کشمیر بیرسٹر سلطان محمود چوہدری سے صدر بینک آف آزاد جموں و کشمیر شاہد شہزاد میر کی تفصیلی ملاقات</strong><br><br>\n\nایوان صدر کشمیر ہاؤس اسلام آباد میں صدر بینک آف آزاد جموں و کشمیر جناب شاہد شہزاد میر نے صدر ریاست آزاد جموں و کشمیر بیرسٹر سلطان محمود چوہدری سے تفصیلی ملاقات کی۔<br><br>\n\nاس موقع پر جناب شاہد شہزاد میر نے بینک کی کارکردگی، درپیش مسائل اور مختلف امور پر صدر ریاست کو تفصیلی بریفنگ دی۔<br><br>\n\nصدر ریاست بیرسٹر سلطان محمود چوہدری نے ہدایت کی کہ بینک کو شیڈول بینک بنانے کے لیے تمام تر وسائل بروئے کار لائے جائیں۔<br><br>\n\nانہوں نے اس مقصد کے لیے اپنے مکمل تعاون اور حمایت کی یقین دہانی بھی کروائی۔<br><br>\n\nاس موقع پر دونوں رہنماؤں کے درمیان باہمی دلچسپی کے امور پر بھی تبادلہ خیال ہوا۔\n</div>', 'Presidential Secretariat, Aiwan-e-Sadr, Kashmir House, Islamabad\n07 April 2025\nIslamabad () 07 April 2025\n\nPresident of Azad Jammu and Kashmir, Barrister Sultan Mehmood Chaudhry, Holds Detailed Meetin...', 'news-images/barister.jpg', '2025-04-09', 0, 'banking', 'barrister-sultan-mehmood-assures-support-for-bajk-growth', 1, '2025-07-17 08:08:32', '2026-02-02 05:28:04'),
(11, 'HR Division of BAJK Organizes Comprehensive Training on Islamic Banking Operations', 'HR Division of BAJK Organizes Comprehensive Training on Islamic Banking Operations<br>\n<strong>Muzaffarabad</strong><br><br>\n\nThe Human Resources (HR) Division of Bank of Azad Jammu and Kashmir (BAJK) successfully organized a comprehensive training program on Islamic Banking Operations for its staff on Thursday. The training was conducted by a renowned Sharia consultancy trainer and was attended by officials from the Islamic Banking Division and other nominated staff members.<br><br>\n\n<strong>Key Highlights of the Training:</strong><br>\n<ul>\n<li><strong>Deep Dive into Sharia Principles:</strong> The training delved into the fundamental principles of Islamic finance, including the prohibition of Riba (interest), Gharar (uncertainty), and Maysir (gambling). Participants gained a thorough understanding of the ethical and legal framework governing all Islamic financial transactions.</li>\n<li><strong>Focus on Islamic Banking Products and Services:</strong> The trainer provided in-depth explanations of various Sharia-compliant products and services offered by Islamic banks, such as Mudarabah, Musharakah, Murabaha, Ijarah, and Istisna.</li>\n<li><strong>Emphasis on Risk Management:</strong> The training emphasized the crucial role of risk management in Islamic banking operations.</li>\n<li><strong>Regulatory Compliance:</strong> A comprehensive overview of the regulatory framework for Islamic banking was also presented.</li>\n<li><strong>Practical Case Studies and Simulations:</strong> Participants engaged in simulations to understand real-world scenarios.</li>\n</ul><br>\n\n<strong>Participant Testimonials:</strong><br>\n<ul>\n<li>\"The training provided invaluable insights into the intricacies of Islamic banking operations. The trainer’s expertise and engaging delivery made the learning experience truly enriching.\" — Participant from Islamic Banking Division</li>\n<li>\"The training has equipped me with the necessary knowledge and skills to effectively contribute to the growth of Islamic banking within BAJK.\" — Another participant</li>\n</ul><br>\n\n<strong>About the Trainer:</strong><br>\nThe trainer is a highly respected Sharia consultant with vast experience in Islamic finance. His deep understanding and practical insights have made him a leading authority in Islamic banking training.<br><br>\n\n<strong>HR Division’s Commitment to Professional Development:</strong><br>\nThe HR Division of BAJK is committed to continuous employee development. This training program reflects the bank’s dedication to equipping its team with specialized skills to boost the success of Islamic banking operations.<br><br>\n\n<div dir=\"rtl\" style=\"text-align: right;\">\n<strong>بینک آف آزاد جموں و کشمیر کے ایچ آر ڈویژن کی جانب سے اسلامی بینکاری آپریشنز پر جامع تربیتی پروگرام کا انعقاد</strong><br>\n<strong>مظفرآباد</strong><br><br>\n\nبینک آف آزاد جموں و کشمیر (BAJK) کے ہیومن ریسورسز (HR) ڈویژن نے جمعرات کے روز اسلامی بینکاری آپریشنز پر ایک جامع تربیتی پروگرام کامیابی سے منعقد کیا۔ تربیت ایک معروف شریعہ کنسلٹنسی ٹرینر نے دی، جس میں اسلامی بینکاری ڈویژن کے افسران اور دیگر نامزد ملازمین نے شرکت کی۔<br><br>\n\n<strong>تربیت کے اہم نکات:</strong><br>\n<ul style=\"list-style: square;\">\n<li><strong>شریعت کے اصولوں پر روشنی:</strong> تربیت میں اسلامی مالیات کے بنیادی اصولوں جیسے ربا، غرر اور میسر کی وضاحت کی گئی۔</li>\n<li><strong>اسلامی بینکاری مصنوعات و خدمات:</strong> مضاربہ، مشارکہ، مرابحہ، اجارہ، اور استصناع جیسی مصنوعات کی تفصیلات پیش کی گئیں۔</li>\n<li><strong>رسک مینجمنٹ:</strong> اسلامی مالیاتی لین دین میں خطرات کے مؤثر انتظام کی تکنیکیں سکھائی گئیں۔</li>\n<li><strong>ریگولیٹری فریم ورک:</strong> اسلامی بینکاری کے قانونی تقاضوں پر روشنی ڈالی گئی۔</li>\n<li><strong>عملی کیس اسٹڈیز:</strong> عملی مثالوں اور سیمولیشنز سے سیکھنے کے مواقع فراہم کیے گئے۔</li>\n</ul><br>\n\n<strong>شرکاء کے تاثرات:</strong><br>\n<ul style=\"list-style: square;\">\n<li>“یہ تربیت اسلامی بینکاری کے پیچیدہ پہلوؤں کو سمجھنے کے لیے انتہائی مددگار ثابت ہوئی۔” — اسلامی بینکاری ڈویژن کے رکن</li>\n<li>“اس تربیت نے مجھے اسلامی بینکاری کی ترقی میں مؤثر کردار ادا کرنے کے لیے ضروری مہارت فراہم کی۔” — ایک اور شریک</li>\n</ul><br>\n\n<strong>ٹرینر کا تعارف:</strong><br>\nٹرینر ایک ممتاز شریعہ کنسلٹنٹ ہیں جنہیں اسلامی مالیاتی شعبے میں وسیع تجربہ حاصل ہے۔ ان کی تدریسی مہارت اور عملی فہم نے انہیں اسلامی بینکاری تربیت میں نمایاں مقام عطا کیا ہے۔<br><br>\n\n<strong>پیشہ ورانہ ترقی کے لیے HR ڈویژن کا عزم:</strong><br>\nBAJK کا HR ڈویژن مسلسل پیشہ ورانہ تربیت کے مواقع فراہم کرنے کے لیے کوشاں ہے۔ یہ پروگرام بینک کی اپنے ملازمین کو اسلامی بینکاری کے شعبے میں مہارت دلانے کی سنجیدہ کوششوں کا عکاس ہے۔\n</div>', 'HR Division of BAJK Organizes Comprehensive Training on Islamic Banking Operations\nMuzaffarabad\n\nThe Human Resources (HR) Division of Bank of Azad Jammu and Kashmir (BAJK) successfully organized a com...', 'news-images/Hr.jpg', '2025-01-23', 0, 'general', 'bajk-hr-organizes-islamic-banking-training', 1, '2025-07-17 08:08:32', '2026-01-29 12:43:51'),
(12, 'Proudly Honoring Pakistan’s Brave Forces', 'The Bank of Azad Jammu and Kashmir pays heartfelt tribute to the courageous armed forces of Pakistan, recognizing their unwavering dedication and sacrifices for national security and peace. Their bravery continues to inspire the nation with pride and gratitude.<br><br>\n\n<div dir=\"rtl\" style=\"text-align: right;\">\nبینک آف آزاد جموں و کشمیر پاکستان کی بہادر مسلح افواج کو دل کی گہرائیوں سے خراجِ تحسین پیش کرتا ہے، جو قومی سلامتی اور امن کے لیے اپنی بے مثال قربانیوں اور غیر متزلزل عزم کے لیے جانے جاتے ہیں۔ ان کی بہادری پوری قوم کے لیے فخر اور شکرگزاری کا باعث ہے۔\n</div>', 'The Bank of Azad Jammu and Kashmir pays heartfelt tribute to the courageous armed forces of Pakistan, recognizing their unwavering dedication and sacrifices for national security and peace. Their brav...', 'news-images/pkforce.jpg', '2025-05-10', 0, 'general', 'proudly-honoring-pakistans-brave-forces', 1, '2025-07-17 08:08:32', '2026-01-29 12:43:51'),
(13, 'BAJK Partners with Faysal Bank to Revolutionize Financial Transactions and Cash Management', 'Bank of AJK Partners with Faysal Bank to Revolutionize Financial Transactions and Enhance Cash Management<br><br>\n<b>Islamabad</b><br>\nBank of Azad Jammu and Kashmir (BAJK), a leading financial institution, has entered into a strategic partnership with Faysal Bank Limited. This collaboration aims to revolutionize the way financial transactions are conducted by integrating the International Bank Account Number (IBAN) system and enhancing cash management operations.<br><br>\n\nBy adopting IBAN, BAJK will streamline its financial operations, enhancing efficiency and transparency. This move is expected to significantly benefit both the company and its customers.<br><br>\n\n<b>Key Benefits of the Partnership:</b><br>\n<ul>\n<li><b>Enhanced Efficiency:</b> The IBAN system will expedite domestic and international fund transfers, reducing processing time and minimizing errors.</li>\n<li><b>Improved Security:</b> The standardized format of IBAN ensures greater security and reduces the risk of fraudulent activities.</li>\n<li><b>Global Recognition:</b> IBAN is an internationally recognized standard, facilitating seamless cross-border transactions.</li>\n<li><b>Enhanced Cash Management:</b> Through this partnership, BAJK will benefit from Faysal Bank’s robust cash management solutions, including:\n    <ul>\n        <li><b>Cash Collection:</b> Efficient and secure collection of cash from multiple sources.</li>\n        <li><b>Cash Disbursement:</b> Timely and accurate disbursement of funds to various payees.</li>\n        <li><b>Cash Forecasting:</b> Accurate prediction of cash flow needs to optimize liquidity management.</li>\n        <li><b>Cash Pooling:</b> Centralization of cash balances to optimize interest income and reduce borrowing costs.</li>\n    </ul>\n</li>\n</ul>\n\nThe signing ceremony was attended by key representatives from both organizations, including the Chief Compliance Officer, DH Risk Management Division, and DH Treasury Management Division from BAJK, and the Head of Cash Management and Regional Head Islamabad from FBL.<br><br>\n\nThis partnership between BAJK and Faysal Bank marks a significant step forward in the adoption of modern financial technologies in Pakistan. It is anticipated that this collaboration will have a positive impact on the broader economy.<br><br>\n\n<div dir=\"rtl\" style=\"text-align: right;\">\n<b>بینک آف آزاد جموں و کشمیر اور فیصل بینک کے درمیان مالیاتی لین دین اور کیش مینجمنٹ میں انقلابی شراکت</b><br><br>\n<b>اسلام آباد</b><br>\nبینک آف آزاد جموں و کشمیر (BAJK)، جو ایک نمایاں مالیاتی ادارہ ہے، نے فیصل بینک لمیٹڈ کے ساتھ ایک اسٹریٹجک شراکت داری قائم کی ہے۔ اس اشتراک کا مقصد مالیاتی لین دین کے طریقہ کار میں انقلابی تبدیلی لانا ہے، جس میں انٹرنیشنل بینک اکاؤنٹ نمبر (IBAN) سسٹم کو شامل کرنا اور کیش مینجمنٹ آپریشنز کو مزید مؤثر بنانا شامل ہے۔<br><br>\n\nIBAN سسٹم کو اپنانے کے ذریعے BAJK اپنے مالیاتی آپریشنز کو مزید منظم، شفاف اور مؤثر بنائے گا، جس سے ادارے اور صارفین دونوں کو خاطر خواہ فائدہ ہوگا۔<br><br>\n\n<b>شراکت کے اہم فوائد:</b>\n<ul>\n<li>🔹 <b>بہتر کارکردگی:</b> IBAN سسٹم کے ذریعے ملکی اور بین الاقوامی فنڈ ٹرانسفرز تیز ہوں گے، وقت کی بچت ہوگی اور غلطیوں میں کمی آئے گی۔</li>\n<li>🔹 <b>بہتر سیکیورٹی:</b> IBAN کا معیاری فارمیٹ مالیاتی تحفظ کو یقینی بناتا ہے اور دھوکہ دہی کے خطرات کو کم کرتا ہے۔</li>\n<li>🔹 <b>عالمی سطح پر شناخت:</b> IBAN ایک بین الاقوامی سطح پر تسلیم شدہ معیار ہے، جو سرحد پار لین دین کو آسان بناتا ہے۔</li>\n<li>🔹 <b>کیش مینجمنٹ میں بہتری:</b> اس شراکت کے ذریعے BAJK کو فیصل بینک کی جدید کیش مینجمنٹ خدمات حاصل ہوں گی، جن میں شامل ہیں:\n    <ul>\n        <li><b>کیش کلیکشن:</b> مختلف ذرائع سے رقم کی مؤثر اور محفوظ وصولی</li>\n        <li><b>کیش ڈسبرسمنٹ:</b> رقوم کی بروقت اور درست ادائیگی</li>\n        <li><b>کیش فورکاسٹنگ:</b> نقدی کی ضروریات کی درست پیش گوئی تاکہ لیکویڈیٹی کا بہتر انتظام کیا جا سکے</li>\n        <li><b>کیش پولنگ:</b> مختلف اکاؤنٹس سے رقم کو مجتمع کر کے منافع میں اضافہ اور قرض کے اخراجات میں کمی</li>\n    </ul>\n</li>\n</ul>\n\nتقریبِ دستخط میں دونوں اداروں کے نمایاں افسران نے شرکت کی، جن میں BAJK کی جانب سے چیف کمپلائنس آفیسر، ڈویژنل ہیڈ رسک مینجمنٹ، اور ڈویژنل ہیڈ ٹریژری مینجمنٹ شامل تھے جبکہ فیصل بینک کی جانب سے ہیڈ آف کیش مینجمنٹ اور ریجنل ہیڈ اسلام آباد نے شرکت کی۔<br>\n</div>', 'Bank of AJK Partners with Faysal Bank to Revolutionize Financial Transactions and Enhance Cash Management\nIslamabad\nBank of Azad Jammu and Kashmir (BAJK), a leading financial institution, has entered ...', 'news-images/fasalbank.jpg', '2024-12-16', 0, 'announcements', 'bajk-partners-with-faysal-bank-for-financial-transformation', 1, '2025-07-17 08:08:32', '2026-02-02 05:32:08'),
(14, 'Bank of AJK Collaborates with NIBAF to Elevate Enterprise Risk Management Standards', 'Bank of AJK Strengthens Risk Management with NIBAF’s Support<br><br>\n<b>Muzaffarabad,</b><br>\n<b>November 25, 2024:</b><br>\nBank of Azad Jammu and Kashmir (BAJK) has initiated a week-long Enterprise Risk Management (ERM) training program in collaboration with the National Institute of Banking and Finance (NIBAF). The program, held at the Ch. Ghulam Abbas Learning Hall, aims to equip BAJK’s staff with the essential tools and knowledge to effectively identify, assess, and mitigate risks.<br><br>\n\nThis initiative underscores BAJK’s commitment to fostering a robust risk culture and strengthening its overall risk management framework. The training program focuses on several key areas, including:<br>\n\n<ul>\n<li><b>Risk Identification and Assessment:</b> Participants will learn to identify potential risks, such as credit, market, operational, and reputational risks, and evaluate their impact on the bank.</li>\n<li><b>Risk Mitigation Strategies:</b> The training will delve into various risk mitigation techniques, including risk avoidance, reduction, transfer, and acceptance.</li>\n<li><b>Risk Monitoring and Reporting:</b> Participants will be trained on establishing robust systems for monitoring and reporting on risk exposures and control measures.</li>\n<li><b>Risk Culture and Governance:</b> The program will emphasize the importance of fostering a strong risk culture within the organization and integrating risk management into the bank’s overall governance framework.</li>\n</ul>\n\nBy partnering with NIBAF, BAJK aims to enhance its risk management capabilities and strengthen its position as a leading financial institution in the region. The bank remains dedicated to upholding the highest standards of risk governance and compliance.<br><br>\n\n<div dir=\"rtl\" style=\"text-align: right;\">\n<b>بینک آف آزاد جموں و کشمیر نے NIBAF کے تعاون سے رسک مینجمنٹ کو مزید مضبوط بنا دیا</b><br><br>\n<b>مظفرآباد،</b><br>\n<b>25 نومبر 2024:</b><br>\nبینک آف آزاد جموں و کشمیر (BAJK) نے نیشنل انسٹیٹیوٹ آف بینکنگ اینڈ فنانس (NIBAF) کے اشتراک سے ایک ہفتے پر محیط انٹرپرائز رسک مینجمنٹ (ERM) تربیتی پروگرام کا آغاز کیا ہے۔ یہ پروگرام چوہدری غلام عباس لرننگ ہال میں منعقد ہو رہا ہے، جس کا مقصد بینک کے عملے کو خطرات کی مؤثر طریقے سے شناخت، تجزیہ اور تدارک کے لیے ضروری علم اور مہارت فراہم کرنا ہے۔<br><br>\n\nیہ اقدام BAJK کے ایک مضبوط رسک کلچر کو فروغ دینے اور اپنے مجموعی رسک مینجمنٹ فریم ورک کو مستحکم کرنے کے عزم کی عکاسی کرتا ہے۔ تربیتی پروگرام درج ذیل اہم شعبوں پر مرکوز ہے:<br>\n\n<ul>\n<li>🔹 <b>خطرات کی شناخت اور تجزیہ:</b> شرکاء کو کریڈٹ، مارکیٹ، آپریشنل اور ساکھ جیسے ممکنہ خطرات کی شناخت اور ان کے بینک پر ممکنہ اثرات کے تجزیے کی تربیت دی جائے گی۔</li>\n<li>🔹 <b>خطرات کے تدارک کی حکمتِ عملی:</b> پروگرام میں خطرات سے بچاؤ، ان میں کمی، ان کا منتقلی اور قبول کرنے جیسے مختلف تدارکی طریقہ کار پر تفصیلی روشنی ڈالی جائے گی۔</li>\n<li>🔹 <b>خطرات کی نگرانی اور رپورٹنگ:</b> شرکاء کو خطرات کے انکشاف اور کنٹرول اقدامات کی نگرانی اور رپورٹنگ کے مضبوط نظام قائم کرنے کی تربیت دی جائے گی۔</li>\n<li>🔹 <b>رسک کلچر اور گورننس:</b> تربیت میں ادارے کے اندر ایک مضبوط رسک کلچر کو فروغ دینے اور رسک مینجمنٹ کو بینک کی مجموعی گورننس میں ضم کرنے کی اہمیت کو اجاگر کیا جائے گا۔</li>\n</ul>\n\nNIBAF کے ساتھ شراکت داری کے ذریعے BAJK کا مقصد اپنی رسک مینجمنٹ صلاحیتوں کو بہتر بنانا اور خطے کے ایک نمایاں مالیاتی ادارے کے طور پر اپنی پوزیشن کو مستحکم کرنا ہے۔ بینک اعلیٰ سطحی رسک گورننس اور تعمیل کے معیار کو برقرار رکھنے کے لیے پُرعزم ہے۔\n</div>', 'Bank of AJK Strengthens Risk Management with NIBAF’s Support\nMuzaffarabad,\nNovember 25, 2024:\nBank of Azad Jammu and Kashmir (BAJK) has initiated a week-long Enterprise Risk Management (ERM) trainin...', 'news-images/risk.jpg', '2024-11-25', 0, 'banking', 'bajk-collaborates-with-nibaf-to-elevate-enterprise-risk-management', 1, '2025-07-17 08:08:32', '2026-02-02 05:33:25'),
(15, 'BAJK Sharda Branch Commemorates 18th Anniversary with Community Leaders and Dignitaries', 'Celebrating the 18th Anniversary of the Bank of Azad Jammu and Kashmir<br><br>\nOn the occasion of the 18th anniversary of the Bank of Azad Jammu and Kashmir, a cake-cutting ceremony was held at the BAJK Sharda Branch. The event was graced by the presence of Assistant Commissioner Mr. Muhammad Qadeer Mughal, Principal of Boys Degree College Sharda Madam Sakeena Khawaja, President of the Sharda Bazaar Traders Association Mr. Babar Nawaz, and other respected local dignitaries.<br><br>\n\nThe guests expressed their heartfelt appreciation for the bank’s services and reaffirmed their commitment to continued cooperation. Prayers were offered for the continued growth and prosperity of the institution. Branch Manager Mr. Noor Zaman thanked all attendees for their participation and support.<br><br>\n\n<div dir=\"rtl\" style=\"text-align: right;\">\n<b>بینک آف آزاد جموں و کشمیر کی 18ویں سالگرہ کا جشن</b><br><br>\nبینک آف آزاد جموں و کشمیر کی 18ویں سالگرہ کے موقع پر شاردہ برانچ میں ایک پُروقار کیک کاٹنے کی تقریب کا انعقاد کیا گیا۔ اس تقریب میں اسسٹنٹ کمشنر جناب محمد قدیر مغل، پرنسپل بوائز ڈگری کالج شاردہ میڈم سکینہ خواجہ، بازار تاجر برادری کے صدر جناب بابر نواز اور دیگر معززین علاقہ نے شرکت کی۔<br><br>\n\nشرکاء نے بینک کی خدمات کو سراہا اور آئندہ بھی تعاون جاری رکھنے کے عزم کا اظہار کیا۔ بینک کی ترقی اور کامیابی کے لیے خصوصی دعا بھی کی گئی۔ برانچ منیجر نور زماں نے تمام مہمانوں کا شکریہ ادا کیا اور ان کی شرکت کو بینک کے لیے باعثِ اعزاز قرار دیا۔\n</div>', 'Celebrating the 18th Anniversary of the Bank of Azad Jammu and Kashmir\nOn the occasion of the 18th anniversary of the Bank of Azad Jammu and Kashmir, a cake-cutting ceremony was held at the BAJK Shard...', 'news-images/birthday.jpg', '2024-11-10', 0, 'general', 'bajk-sharda-branch-18th-anniversary-celebration-with-community-leaders', 1, '2025-07-17 08:08:32', '2026-01-29 12:43:51'),
(16, 'BAJK Celebrates 18th Anniversary at Pulmanda Branch, Khari Sharif', 'Khari Sharif<br><br>\nA grand ceremony was held at the Pulmanda Branch of Bank of Azad Jammu and Kashmir (BAJK) to mark the bank’s 18th anniversary. The event was graced by senior political, social, and education department officials from across the region. Regional Head of Mirpur, Raja Muhammad Waseem Khan, along with the bank staff, received high praise for their dedicated services.<br><br>\n\nPresident of the Anjuman-e-Tajran, Ch. Muhammad Afsar, appreciated the performance of the bank staff and assured full support. While addressing the ceremony, the Secretary of Anjuman-e-Tajran Pulmanda recalled the historic role of Jammu and Kashmir Bank, stating that even before the formation of Pakistan, it held a leading position. He emphasized the importance of supporting a bank that is truly their own.<br><br>\n\nRaja Sahib, impressed by the dedication of the staff, offered heartfelt prayers for the continuous progress and prosperity of Kashmir Bank, wishing it success \"day and night,\" and also shared valuable suggestions. Chairman Malik Mazhar Iqbal Awan, attending as the special guest, acknowledged the enduring relationship between his family and the bank, pledging continued cooperation.<br><br>\n\nAmong the attendees were senior education department officials, principals of Boys College and Girls College Afzalpur, and members of civil society, all of whom admired the commitment and service quality of the bank staff.<br><br>\n\nThe event concluded with a vote of thanks by Branch Manager Mr. Waqas Javed to all the esteemed guests.<br><br>\n\n<div dir=\"rtl\" style=\"text-align: right;\">\n<b>کھڑی شریف</b><br><br>\nبینک آف آزاد جموں و کشمیر پلمنڈا برانچ میں بھی بینک کی اٹھارویں سالگرہ کے موقع پر ایک پُروقار تقریب منعقد ہوئی۔ تقریب میں علاقہ بھر سے سیاسی، سماجی اور محکمہ تعلیم کے اعلیٰ افسران نے شرکت کی۔ ریجنل ہیڈ میرپور راجہ محمد وسیم خان اور بینک کے عملے کی خدمات کو سراہا گیا۔<br><br>\n\nانجمن تاجران کے صدر چوہدری محمد افسر نے بینک عملے کی کارکردگی کو سراہتے ہوئے خراج تحسین پیش کیا اور بینک سے مکمل تعاون کی یقین دہانی کروائی۔ انجمن تاجران پلمنڈا کے سیکرٹری نے خطاب کرتے ہوئے کہا کہ جموں و کشمیر بینک پاکستان کے قیام سے قبل بھی عروج پر تھا، یہ بینک ہمارا اپنا ہے اور ہمیں اس کے ساتھ تعاون کرنا چاہیے۔<br><br>\n\nبینک عملے کی کارکردگی سے متاثر ہو کر راجہ صاحب نے دعا دی کہ کشمیر بینک \"دن دوگنی رات چوگنی ترقی کرے\" اور اہم تجاویز بھی پیش کیں۔ چیئرمین ملک مظہر اقبال اعوان نے بطور مہمان خصوصی تقریب میں شرکت کی اور خطاب کرتے ہوئے بینک عملے کو خراج تحسین پیش کیا۔ انہوں نے کہا کہ ان کی فیملی کا بینک سے دیرینہ تعلق رہا ہے اور یہ تعاون مستقبل میں بھی جاری رہے گا۔<br><br>\n\nتقریب میں محکمہ تعلیم کے اعلیٰ افسران، پرنسپل بوائز کالج افضل پور، پرنسپل گرلز کالج افضل پور اور سول سوسائٹی کے معزز اراکین نے بھی شرکت کی اور بینک کے عملے کی خدمات کی تعریف کی۔<br><br>\n\nآخر میں برانچ منیجر وقاص جاوید نے تمام معزز مہمانوں کا شکریہ ادا کیا۔\n</div>', 'Khari Sharif\nA grand ceremony was held at the Pulmanda Branch of Bank of Azad Jammu and Kashmir (BAJK) to mark the bank’s 18th anniversary. The event was graced by senior political, social, and educ...', 'news-images/kharishreef.jpg', '2024-11-09', 0, 'announcements', 'bajk-celebrates-18th-anniversary-pulmanda-branch-khari-sharif', 1, '2025-07-17 08:08:32', '2026-02-02 05:36:08'),
(17, 'BAJK Celebrates 18th Anniversary with Cake-Cutting Ceremony in Rawalakot', 'Rawalakot<br><br>\nA cake-cutting ceremony took place at the Main Branch in Rawalakot to commemorate the 18th anniversary of the Bank of Azad Jammu and Kashmir (BAJK). The event was honored by the presence of Deputy Commissioner Poonch, Syed Mumtaz Kazmi, and Assistant Commissioner Sardar Mushtaq. They were warmly received by the Chief Manager of the Main Branch, Rawalakot.<br><br>\n\nDivisional Head of CMD, Mr. Imtiaz Shaheen, was also present and delivered an inspiring briefing highlighting the bank’s notable achievements over the years. The Regional Head, Regional Operations Manager (ROM), and Regional Business Manager (RBM) from the Rawalakot Region also participated, contributing to the celebratory atmosphere as all attendees marked this significant milestone with pride.<br><br>\n\n<div dir=\"rtl\" style=\"text-align: right;\">\n<b>راولا کوٹ</b><br><br>\nبینک آف آزاد جموں و کشمیر (BAJK) کی 18ویں سالگرہ کے موقع پر راولا کوٹ کی مین برانچ میں ایک پروقار کیک کاٹنے کی تقریب منعقد کی گئی۔ اس تقریب میں ڈپٹی کمشنر پونچھ، جناب سید ممتاز کاظمی، اور اسسٹنٹ کمشنر سردار مشتاق نے شرکت کی۔ مین برانچ راولا کوٹ کے چیف منیجر نے معزز مہمانوں کا استقبال کیا۔<br><br>\n\nاس موقع پر کمانڈ ڈویژن کے ڈویژنل ہیڈ، جناب امتیاز شاہین، بھی موجود تھے، جنہوں نے بینک کی گزشتہ سالوں کی کامیابیوں پر ایک حوصلہ افزا بریفنگ دی۔ راولا کوٹ ریجن کے ریجنل ہیڈ، ریجنل آپریشن منیجر (ROM)، اور ریجنل بزنس منیجر (RBM) نے بھی اس اہم موقع پر شرکت کی اور تقریب کو مزید خوشگوار اور یادگار بنایا۔\n</div>', 'Rawalakot\nA cake-cutting ceremony took place at the Main Branch in Rawalakot to commemorate the 18th anniversary of the Bank of Azad Jammu and Kashmir (BAJK). The event was honored by the presence of ...', 'news-images/rawlakot.jpg', '2024-11-09', 0, 'general', 'bajk-celebrates-18th-anniversary-cake-cutting-rawalakot', 1, '2025-07-17 08:08:32', '2026-01-29 12:43:51'),
(18, 'AJK Finance Minister and Chairman Bank of AJK Emphasizes Role of Kashmir Bank in Regional Business Growth', 'Mirpur<br><br>\nThe Finance and Cooperative Minister of the Azad Government of the State of Jammu and Kashmir, and Chairman of the Bank of Azad Jammu and Kashmir (BAJK), Khan Abdul Majid Khan, stated that Kashmir Bank is playing a vital role in promoting business activities across the region. Attractive loan schemes, including Small Business Trade Finance (SBTF), are significantly boosting business development.<br><br>\n\nHe made these remarks during a meeting with the leadership of the AJK Chamber of Commerce & Industry. The meeting, chaired by the Finance Minister, focused on strengthening the partnership between Kashmir Bank and the business community.<br><br>\n\nThe event was organized by BAJK and attended by Chamber President Mr. Umar Shehzad, General Secretary Syed Nishat Hussain Kazmi, former presidents Mr. Faisal Manzoor, Syed Sabir Hussain Shah, Mr. Azeem Mushtaq, Mr. Muhammad Rizwan, Sardar Azad Khan, Mr. Sohail Shuja, President of Anjuman Tajiran Raja Khalid Mehmood, and Ch. Muhammad Ayaz of Siraj Steel Mills, along with other distinguished business personalities.<br><br>\n\nCRBD Head Raja Ghulam Mustafa, Regional Head Mr. Muhammad Waseem Khan, and other BAJK officials welcomed the guests.<br><br>\n\nThe Chairman praised the outstanding performance of President Mr. Shahid Shahzad Mir and his team. He shared that under the SBTF scheme, BAJK is providing loans of up to PKR 500,000 to small business owners and traders on easy terms and low markup. These loans are processed quickly and include 100% life and stock insurance, contributing to rapid socio-economic development.<br><br>\n\n<div dir=\"rtl\" style=\"text-align: right;\">\n<b>میرپور</b><br><br>\nآزاد حکومت ریاست جموں و کشمیر کے وزیر خزانہ و امداد باہمی اور بینک آف آزاد جموں و کشمیر کے چیئرمین خان عبدالماجد خان نے کہا ہے کہ کشمیر بینک خطے میں کاروباری سرگرمیوں کے فروغ میں کلیدی کردار ادا کر رہا ہے۔ سمال بزنس ٹریڈ فنانس (SBTF) سمیت متعدد پرکشش قرضہ سکیمیں کاروباری ترقی کا ذریعہ بن رہی ہیں۔<br><br>\n\nانہوں نے یہ بات آزاد جموں و کشمیر چیمبر آف کامرس و انڈسٹری کے رہنماؤں سے ایک اجلاس میں کہی، جس کی صدارت انہوں نے خود کی۔ اجلاس میں کشمیر بینک اور تاجر برادری کے مابین کاروباری تعلقات کو مزید مستحکم بنانے پر تبادلہ خیال کیا گیا۔<br><br>\n\nبینک کے زیرِ اہتمام اس اجلاس میں چیمبر کے صدر عمر شہزاد، جنرل سیکریٹری سید نشاط حسین کاظمی، سابق صدور فیصل منظور، سید صابر حسین شاہ، عظیم مشتاق، محمد رضوان، سردار آزاد خان، سہیل شجاع، انجمن تاجراں کے صدر راجہ خالد محمود، سراج اسٹیل ملز کے چودھری محمد ایاز اور دیگر معزز کاروباری شخصیات نے شرکت کی۔ بینک کی جانب سے سی آر بی ڈی ہیڈ راجہ غلام مصطفیٰ، ریجنل ہیڈ محمد وسیم خان سمیت دیگر افسران نے معزز مہمانوں کا استقبال کیا۔<br><br>\n\nچیئرمین نے ادارے کی شاندار کارکردگی پر روشنی ڈالتے ہوئے صدر بینک جناب شاہد شہزاد میر اور ان کی ٹیم کو خراج تحسین پیش کیا۔ انہوں نے بتایا کہ SBTF اسکیم کے تحت چھوٹے تاجروں کو 5 لاکھ روپے تک کے قرضے آسان شرائط اور کم از کم مارک اپ پر دیے جا رہے ہیں، جن میں تیز ترین پراسیسنگ اور 100% لائف و سٹاک انشورنس شامل ہے، جو خطے کی سماجی و معاشی ترقی کا باعث بن رہی ہے۔<br><br>\n\nاس موقع پر بزنس کمیونٹی نے کشمیر بینک سے محبت کا اظہار کیا اور باہمی تعاون کو مزید فروغ دینے کا عزم ظاہر کیا، جبکہ کاروباری تعلقات کو مزید مضبوط بنانے کے لیے مفید تجاویز بھی پیش کی گئیں۔\n</div>', 'Mirpur\nThe Finance and Cooperative Minister of the Azad Government of the State of Jammu and Kashmir, and Chairman of the Bank of Azad Jammu and Kashmir (BAJK), Khan Abdul Majid Khan, stated that Kash...', 'news-images/business.jpg', '2024-11-01', 0, 'announcements', 'ajk-finance-minister-highlights-kashmir-bank-role-in-regional-business-growth', 1, '2025-07-17 08:08:32', '2026-02-02 05:41:05'),
(19, 'AJK Finance Minister Khan Abdul Majid Khan’s Visit to Bank of AJK: Focus on Service and Customer Relations', 'Muzaffarabad<br><br>\nThe Finance & Cooperatives Minister of the Azad Government of the State of Jammu & Kashmir and Chairman of the Bank of Azad Jammu & Kashmir (BAJK), Mr. Khan Abdul Majid Khan, recently visited the bank’s field monitoring offices and branches in Mirpur. He chaired a meeting with managers and officers at the regional office and also visited the Overseas Desk at the Main Branch. CRBD Head Raja Ghulam Mustafa and Mirpur Regional Head Muhammad Waseem Khan accompanied him during the visit.<br><br>\n\nOn this occasion, he reviewed the professional performance of the staff and issued directives regarding banking services for customers. He stated that the overall improvement in services and strengthened business relations with customers have earned the bank special attention and trust. As a result, there has been a notable increase in the bank’s profits, assets, deposits, and home remittances — reflecting the strong confidence of overseas Pakistanis and other valued customers in the institution.<br><br>\n\nWhile interacting with customers, he described them as the bank’s most valuable asset. He urged the staff to further strengthen business relationships and enhance customer service, emphasizing that stronger ties with clients will lead to greater growth for the bank.<br><br>\n\n<div dir=\"rtl\" style=\"text-align: right;\">\n<b>مظفر آباد</b><br><br>\nآزاد حکومت ریاست جموں و کشمیر کے وزیر خزانہ و امداد باہمی اور بینک آف آزاد جموں و کشمیر کے چیئرمین خان عبدالماجد خان نے گزشتہ روز میرپور میں ادارے کے فیلڈ نگراں دفاتر اور برانچوں کا دورہ کیا۔ ریجنل آفس میں منیجرز اور افسران کے اجلاس کی صدارت کی جبکہ مین برانچ میں اوورسیز ڈیسک کا دورہ بھی کیا۔ سی آر بی ڈی ہیڈ راجہ غلام مصطفیٰ اور میرپور ریجن ہیڈ محمد وسیم خان بھی ان کے ہمراہ تھے۔<br><br>\n\nاس موقع پر انہوں نے عملے کی پیشہ ورانہ سرگرمیوں کا جائزہ لیا اور صارفین کے لیے بینکاری خدمات سے متعلق ہدایات جاری کرتے ہوئے کہا کہ مجموعی طور پر خدمات میں بہتری اور صارفین کے ساتھ بزنس تعلقات میں اضافے کی بدولت ادارہ خصوصی توجہ حاصل کر رہا ہے۔ یہی وجہ ہے کہ بینک کے منافع، اثاثہ جات، ڈپازٹس اور ہوم ریمی ٹینسز میں اضافہ ہو رہا ہے، جو کہ سمندر پار پاکستانیوں اور معزز صارفین کے بھرپور اعتماد کا ثبوت ہے۔<br><br>\n\nانہوں نے صارفین کے ساتھ گفتگو کرتے ہوئے انہیں بینک کا قیمتی سرمایہ قرار دیا اور بینک کے عملے کو تلقین کی کہ وہ صارفین کے ساتھ بزنس تعلقات کو مزید مستحکم کریں اور کسٹمر سروس کو بہتر بنائیں۔ انہوں نے کہا کہ جتنا زیادہ صارفین سے تعلق مضبوط ہوگا، اتنا ہی بینک کے کاروبار میں اضافہ ہوگا۔\n</div>', 'Muzaffarabad\nThe Finance & Cooperatives Minister of the Azad Government of the State of Jammu & Kashmir and Chairman of the Bank of Azad Jammu & Kashmir (BAJK), Mr. Khan Abdul Majid Khan, recently vis...', 'news-images/visit.jpg', '2024-10-30', 0, 'general', 'ajk-finance-minister-khan-abdul-majid-khan-visits-bajk-focus-on-service-and-customer-relations', 1, '2025-07-17 08:08:32', '2026-01-29 12:43:51'),
(20, 'Bank of Azad Jammu and Kashmir Sponsors Shahidae Jammu Floodlight Football Tournament in Muzaffarabad', 'Muzaffarabad <br><br>\nWith the support of the Bank of Azad Jammu and Kashmir, the Shuhada-e-Jammu Floodlight Football Tournament was held in Muzaffarabad. A total of 23 teams participated in the tournament. The final match was played between Shah Football Club and Real Football Club, where Shah Club clinched the title in an exciting penalty shootout. This marked Shah Club’s fifth consecutive tournament victory.<br><br>\n\nA large number of spectators attended the match and applauded the players. During the final, a lucky draw was also held for the spectators, and Arsalan Maqbool Kayani won a ticket for Umrah.<br><br>\n\nThe President and CEO of the Bank of Azad Jammu and Kashmir, Mr. Shahid Shehzad Mir, was the chief guest on the occasion. He awarded the winning team with the trophy and distributed shields and prizes among the players.<br><br>\n\nThe efforts of District Football Association President Mehtab Ahmed Mir, Aamir Hussain Kayani, Raja Azhar Ali, and others were appreciated for successfully organizing and managing the event.<br><br>\n\n<div dir=\"rtl\" style=\"text-align: right;\">\n<b>مظفر آباد</b><br><br>\nبینک آف آزاد جموں و کشمیر کے تعاون سے مظفر آباد میں شہدائے جموں فلڈ لائٹ فٹبال ٹورنامنٹ کا انعقاد کیا گیا۔ ٹورنامنٹ میں 23 ٹیموں نے حصہ لیا۔ گزشتہ روز ٹورنامنٹ کا فائنل شاہ فٹبال کلب اور ریال فٹبال کلب کے درمیان کھیلا گیا۔ شاہ کلب نے ایک دلچسپ پینلٹی کک پر فائنل ٹائٹل اپنے نام کر لیا۔ یہ شاہ کلب کی مسلسل پانچویں ٹورنامنٹ جیت تھی۔<br><br>\n\nشائقین کی بڑی تعداد نے میچ دیکھا اور کھلاڑیوں کو داد دی۔ فائنل میچ کے شائقین کے لیے قرعہ اندازی کے ذریعے عمرہ کا ٹکٹ ارسلان مقبول کیانی حاصل کرنے میں کامیاب ہو گئے۔<br><br>\n\nاس موقع پر بینک آف آزاد جموں و کشمیر کے صدر و سی ای او جناب شاہد شہزاد میر مہمانِ خصوصی تھے۔ انہوں نے ٹورنامنٹ جیتنے والی ٹیم کو ٹرافی دی، کھلاڑیوں میں شیلڈز اور انعامات تقسیم کیے۔<br><br>\n\nٹورنامنٹ کے انتظامات، نظم و ضبط پر ڈسٹرکٹ فٹبال ایسوسی ایشن کے صدر مہتاب احمد میر، عامر حسین کیانی، راجہ اظہر علی اور دیگر کو مبارکباد پیش کی گئی۔<br><br>\n\nیہاں یہ بات قابل ذکر ہے کہ کشمیر بینک روایتی بینکاری کے ساتھ ساتھ صحت مند معاشرے کی تعمیر، کھیل اور کھلاڑی کی حوصلہ افزائی کے لیے بھی اپنا کردار ادا کر رہا ہے۔\n</div>', 'Muzaffarabad \nWith the support of the Bank of Azad Jammu and Kashmir, the Shuhada-e-Jammu Floodlight Football Tournament was held in Muzaffarabad. A total of 23 teams participated in the tournament. T...', 'news-images/jammu.jpg', '2024-10-03', 0, 'general', 'bajk-sponsors-shahidae-jammu-football-tournament-muzaffarabad', 1, '2025-07-17 08:08:32', '2026-01-29 12:43:51'),
(21, 'State Bank Governor Endorses Bank of AJK’s Growth and Path Toward Schedule Bank License', 'Islamabad <br><br>\nThe Governor of the State Bank of Pakistan highly appreciated the performance of the Bank of Azad Jammu and Kashmir (BAJK) and the steps taken towards acquiring scheduled bank status. He expressed principled agreement with the State Bank’s position to issue a license, commending the pace and manner in which Kashmir’s financial institution is progressing and contributing to the economic and social development of the state. He stated that this bank will soon be among the most successful banks.<br><br>\n\nThese remarks were made on Thursday by Governor State Bank Mr. Jameel Ahmed during a meeting with the Finance & Cooperatives Minister of Azad Kashmir and Chairman of the Bank’s Board of Directors, Mr. Khan Abdul Majid Khan, President & CEO Mr. Shahid Shehzad Mir, Secretary Finance and Bank Director Mr. Islam Zaib, and Company Secretary Dr. Adnanullah Khan.<br><br>\n\nWhile reviewing the performance of Kashmir Bank, the Governor stated that despite not having scheduled bank status, the bank’s performance has been outstanding. He appreciated the launch of Islamic banking by the Bank and advised that once equity and core banking requirements are completed, the bank may formally approach the State Bank.<br><br>\n\nHe also praised the bank’s initiative to establish an exchange company, assuring that a license would be issued by the State Bank upon completion of the required regulatory framework.<br><br>\n\nEarlier, the Chairman informed the Governor about the importance of BAJK in the state’s economy, the connection and interest of overseas Kashmiri expatriates in the bank, and the significance of acquiring a scheduled bank license.<br><br>\n\nHe highlighted several initiatives undertaken by the financial institution and the state government to achieve this status, including the installation of core banking software, improvement of loan schemes, preparation of a business case for submission to the State Bank, and hiring of a consultant to fulfill legal requirements. He also mentioned that the people of Azad Kashmir, especially overseas Kashmiris and the corporate sector, have shown a strong desire to see the bank attain scheduled status.<br><br>\n\nThe Chairman further emphasized that inclusion of the bank in government projects like hydropower, tourism, women’s economic empowerment, agriculture, and housing would significantly accelerate its growth. Additionally, the appointment of a focal person by the State Bank for licensing guidance and cooperation, along with the opening of a corporate office in Islamabad, would yield positive business outcomes.<br><br>\n\nEarlier, President Mr. Shahid Shehzad Mir briefed the Governor on the bank’s history, organizational structure, expanding network, customer outreach, paid-up capital, and overall financial performance.<br><br>\n\nThe Governor attentively listened to the bank team’s briefing and expressed principled agreement with the institution’s stance regarding the acquisition of scheduled bank status. Souvenirs were also presented to the Governor on this occasion.<br><br>\n\n<div dir=\"rtl\" style=\"text-align: right;\">\n<b>اسلام آباد</b><br><br>\nگورنر سٹیٹ بینک آف پاکستان نے بینک آف آزاد جموں و کشمیر کی کارکردگی اور شیڈول بینک درجہ کے حصول سے متعلق اقدامات کی زبردست تعریف اور حوصلہ افزائی کرتے ہوئے سٹیٹ بینک کی جانب سے لائسنس اجراء کرنے کے موقف سے اصولی اتفاق کر لیا اور کہا کہ جس انداز و رفتار سے کشمیر کا مالیاتی ادارہ ترقی کی جانب گامزن رہتے ہوئے ریاست کی معاشی و سماجی ترقی میں کردار ادا کر رہا ہے، اس سے ظاہر ہوتا ہے کہ یہ بینک بہت جلد کامیاب ترین بینکوں کی صف میں شامل ہو جائے گا۔<br><br>\n\nجمعرات کو یہاں ان خیالات کا اظہار گورنر سٹیٹ بینک جناب جمیل احمد نے آزاد کشمیر کے وزیر خزانہ و کوآپریٹوز اور بینک بورڈ آف ڈائریکٹرز کے چیئرمین خان عبدالماجد خان، صدر و چیف ایگزیکٹو آفیسر جناب شاہد شہزاد میر، آزاد کشمیر کے سیکریٹری فنانس اور ڈائریکٹر بینک جناب اسلام زیب، کمپنی سیکرٹری ڈاکٹر عدنان اللہ خان کے ساتھ ایک میٹنگ کے دوران بات چیت کرتے ہوئے کیا۔<br><br>\n\nگورنر نے کشمیر بینک کی کارکردگی کا جائزہ لیتے ہوئے کہا کہ شیڈول نہ ہونے کے باوجود آزاد کشمیر بینک کی کارکردگی شاندار رہی ہے۔ انہوں نے کشمیر بینک کی جانب سے اسلامک بینکنگ شروع کرنے کی تعریف کی اور کہا کہ بینک ایکویٹی اور کور بینکنگ سے متعلق لوازمات مکمل کر کے سٹیٹ بینک سے رجوع کرے۔<br><br>\n\nبینک کی جانب سے ایکسچینج کمپنی کھولنے کی بھی تعریف کرتے ہوئے گورنر نے کہا کہ اس سلسلے میں قواعد و ضوابط مکمل ہونے پر سٹیٹ بینک کی جانب سے لائسنس جاری کر دیا جائے گا۔<br><br>\n\nقبل ازیں، چیئرمین نے ریاستی معیشت میں بینک آف آزاد جموں و کشمیر کی اہمیت، ادارے کے ساتھ سمندر پار کشمیری تارکین وطن کی وابستگی اور دلچسپی، شیڈول درجہ دلانے کے لیے لائسنس اجرائیگی کی اہمیت و افادیت، مالیاتی ادارے اور ریاستی حکومت کی جانب سے ترقی اور شیڈول بینک درجہ کے حصول کے لیے اٹھائے گئے اقدامات سے آگاہ کیا۔<br><br>\n\nجن میں قابل ذکر کور بینکنگ سافٹ ویئر کی تنصیب، قرضہ جات منصوبوں کی از سر نو بہتری، اسٹیٹ بینک میں درخواست دائر کرنے کے لیے بزنس کیس کی تیاری اور قانونی لوازمات کی تکمیل کے لیے کنسلٹنٹ کی خدمات کا حصول شامل ہیں۔<br><br>\n\nآزاد کشمیر کے عوام بالخصوص سمندر پار تارکین وطن کشمیریوں و کارپوریٹ سیکٹر کی بینک کو شیڈول کا درجہ دینے کی خواہشات بھی شامل ہیں۔<br><br>\n\nچیئرمین نے مزید بتایا کہ بینک کو حکومت پاکستان کے پن بجلی، سیاحت، معاشی طور پر خواتین کو بااختیار بنانے، زراعت و ہاؤسنگ جیسے خصوصی منصوبوں میں شامل کرنے سے بینک کی ترقی میں تیزی آئے گی۔<br><br>\n\nعلاوہ ازیں سٹیٹ بینک کی جانب سے اس بینک کو لائسنس کے اجراء، رہنمائی و تعاون کے لیے فوکل پرسن کی نامزدگی جب کہ اسلام آباد میں بینک کے کارپوریٹ دفتر کھولنے کے مثبت کاروباری نتائج برآمد ہوں گے۔<br><br>\n\nقبل ازیں گورنر سٹیٹ بینک کو صدر بینک جناب شاہد شہزاد میر کی جانب سے ریاستی بینک کی تاریخ، انتظامی ڈھانچے، پھیلتے ہوئے نیٹ ورک اور صارفین تک رسائی، ادا شدہ سرمایہ سمیت فنانشل ترقی کی صورتحال سے متعلق بریفنگ دی گئی۔<br><br>\n\nجناب گورنر نے بینک ٹیم کی بریفنگ دلچسپی اور توجہ سے سنی اور شیڈول بینک درجہ کے حصول کے لیے ادارے کے موقف پر اصولی اتفاق کر لیا۔ اس موقع پر گورنر سٹیٹ بینک کو سوینئرز پیش کی گئیں۔\n</div>', 'Islamabad \nThe Governor of the State Bank of Pakistan highly appreciated the performance of the Bank of Azad Jammu and Kashmir (BAJK) and the steps taken towards acquiring scheduled bank status. He ex...', 'news-images/schedule.jpg', '2024-09-19', 0, 'general', 'state-bank-governor-endorses-bajk-growth-schedule-bank-license-path', 1, '2025-07-17 08:08:32', '2026-01-29 12:43:51');
INSERT INTO `news_announcements` (`id`, `title`, `content`, `excerpt`, `image`, `published_date`, `is_featured`, `category`, `slug`, `is_published`, `created_at`, `updated_at`) VALUES
(22, '79th Board of Directors Meeting of BAJK Approves Semi-Annual Financial Accounts, Expresses Satisfaction Over Profit and Asset Growth', 'Muzaffarabad <br><br>\nThe 79th meeting of the Board of Directors of the Bank of Azad Jammu & Kashmir was held under the chairmanship of Mr. Khan Abdul Majid Khan, Honorable Minister for Finance & Cooperatives, Government of Azad Jammu & Kashmir, and Chairman of the Bank. The meeting took place on Monday at the Bank’s Head Office and was attended by President & Chief Executive Officer Mr. Shahid Shehzad Mir; Directors; Secretary Finance, Government of Azad Jammu & Kashmir, Mr. Islam Zaib; Secretary Industries & Commerce Mr. Khalid Mahmood Mirza; Secretary Law & Justice Mr. Muhammad Sajjad; Mr. Mubashir Nabi; Mr. Zulfiqar Abbasi; Ms. Bushra Naz Malik; and Company Secretary Dr. Adnan Ullah Khan.<br><br>\n\nVarious operational agendas, including the financial accounts for the first half of the year (as of June 30, 2024), were presented during the meeting. After detailed discussions, the items were approved. According to the half-yearly financial accounts, the Bank has recorded consistent growth in profit, assets, deposits, and remittances. Customers are being offered attractive loan schemes on easy terms and with minimal markup.<br><br>\n\nThe Board was informed that during the first half of the current year, the Bank earned an operating profit of Rs. 906 million. The Bank’s assets increased to Rs. 48 billion, and deposits rose to Rs. 39 billion. Under various attractive schemes, loans amounting to Rs. 4.5 billion were provided to customers.<br><br>\n\nThe Board appreciated the excellent performance and acknowledged the contributions of all stakeholders, reaffirming the commitment to continue the Bank’s journey of success and progress.<br><br>\n\n<div dir=\"rtl\" style=\"text-align: right;\">\n<b>مظفرآباد</b><br><br>\nآزاد حکومت ریاست جموں و کشمیر کے وزیر خزانہ و امداد باہمی اور بینک آف آزاد جموں و کشمیر کے چیئرمین جناب خان عبدالماجد خان کی زیر صدارت بینک کے بورڈ آف ڈائریکٹرز کا 79واں اجلاس منعقد ہوا۔ پیر کے روز بینک کے ہیڈ آفس میں منعقدہ اجلاس میں صدر و چیف ایگزیکٹو آفیسر جناب شاہد شہزاد میر، ڈائریکٹرز صاحبان، سیکریٹری فنانس حکومت آزاد جموں و کشمیر جناب اسلام زیب، سیکریٹری صنعت و حرفت جناب خالد محمود مرزا، سیکریٹری قانون و انصاف جناب محمد سجاد، جناب مبشر نبی، جناب ذوالفقار عباسی، محترمہ بشریٰ ناز ملک اور کمپنی سیکریٹری ڈاکٹر عدنان اللہ خان نے شرکت کی۔<br><br>\n\nاجلاس میں سال کے پہلے ششماہی فنانشل اکاؤنٹس (30 جون 2024) سمیت مختلف آپریشنل ایجنڈے پیش کئے گئے جن کی مفصل بحث و مباحثہ کے بعد منظوری دی گئی۔ ششماہی فنانشل اکاؤنٹس کے مطابق بینک کے منافع، اثاثہ جات، ڈیپازٹس اور ترسیلات زر میں مسلسل اضافہ ہو رہا ہے جب کہ صارفین کو آسان شرائط اور کم از کم مارک اپ پر پرکشش قرضہ جات فراہم کیے جا رہے ہیں۔<br><br>\n\nبورڈ کو بتایا گیا کہ رواں سال کی پہلی ششماہی میں بینک نے 906 ملین روپے آپریٹنگ منافع حاصل کیا، اثاثہ جات بڑھ کر 48 ارب روپے تک پہنچ گئے، اور ڈیپازٹس 39 ارب روپے ہو گئے۔ مختلف پرکشش اسکیموں کے تحت صارفین کو 4.5 ارب روپے کے قرضہ جات فراہم کیے گئے۔<br><br>\n\nبورڈ نے شاندار کارکردگی اور تعاون پر تمام اسٹیک ہولڈرز کے کردار کی تعریف کرتے ہوئے بینک کی کامیابی اور ترقی کے سفر کو جاری رکھنے کے عزم کا اعادہ کیا۔<br><br>\n\nاس موقع پر جناب چیئرمین نے کہا کہ حکومت کی سرپرستی میں ادارے کو کامیاب اور صف اول کے بینکوں میں شامل کرنے کے لیے تمام کوششیں بروئے کار لائی جا رہی ہیں۔ انہوں نے کہا کہ عملے کی محنت، ٹیم ورک، اور معزز صارفین کے بھرپور تعاون سے بہترین بزنس نتائج کے حصول کا سلسلہ جاری رکھا جائے گا۔\n</div>', 'Muzaffarabad \nThe 79th meeting of the Board of Directors of the Bank of Azad Jammu & Kashmir was held under the chairmanship of Mr. Khan Abdul Majid Khan, Honorable Minister for Finance & Cooperatives...', 'news-images/79meeting.jpg', '2024-09-02', 0, 'general', 'bajk-79th-board-meeting-approves-financials-highlights-growth', 1, '2025-07-17 08:08:32', '2026-01-29 12:43:51'),
(23, '92nd Meeting of the Board of Directors of BAJK Held in Islamabad', 'Islamabad <br>\n            The <strong>92nd meeting</strong> of the Board of Directors (BoD) of <strong>Bank of Azad Jammu & Kashmir (BAJK)</strong> was held on <strong>Monday in Islamabad</strong>, chaired by <strong>Mr. Khan Abdul Majid Khan</strong>, Honorable Minister for Finance & Cooperatives, Government of Azad Jammu & Kashmir, and Chairman of BAJK.<br><br>\n\n<strong>Board Members in Attendance:</strong><br>\n- <strong>Mr. Khan Abdul Majid Khan</strong> (Chairman)<br>\n- <strong>Mr. Shahid Shahzad Mir</strong> (President & CEO, BAJK)<br>\n- <strong>Mr. Islam Zaib</strong> (Secretary Finance, AJK)<br>\n- <strong>Mr. Khalid Mahmood Mirza</strong> (Secretary Industries & Commerce, AJK)<br>\n- <strong>Mr. Muhammad Sajjad</strong> (Secretary Law & Justice, AJK)<br>\n- <strong>Mr. Mubashar Nabi</strong><br>\n- <strong>Ms. Bushra Naz Malik</strong> (Board Member)<br>\n- <strong>Dr. Adnanullah Khan</strong> (Company Secretary)<br><br>\n\n<strong>Key Highlights:</strong><br>\n1. <strong>Core Banking System Contract Ceremony:</strong><br>\n&nbsp;&nbsp;- The Board expressed satisfaction over the recent <strong>Core Banking System contract signing ceremony</strong>, held in the presence of the <strong>Prime Minister of AJK</strong> and senior government officials.<br>\n&nbsp;&nbsp;- Emphasis was placed on the <strong>speedy implementation</strong> of the new system to enhance digital banking services and operational efficiency.<br><br>\n\n2. <strong>Approval of New ESG Committee:</strong><br>\n&nbsp;&nbsp;- The Board approved the <strong>Terms of Reference (ToRs)</strong> for the newly established <strong>Environmental, Social, and Governance (ESG) Committee</strong>, reinforcing BAJK’s commitment to sustainable and responsible banking practices.<br><br>\n\n3. <strong>Strategic Discussions:</strong><br>\n&nbsp;&nbsp;- Progress on ongoing initiatives was reviewed, focusing on <strong>financial growth, technological advancements, and customer service improvements</strong>.<br><br>\n\n<strong>Chairman’s Remarks:</strong><br>\nMr. Khan Abdul Majid Khan commended the efforts of BAJK’s leadership, Board members, and stakeholders in driving the Bank’s progress. He reiterated BAJK’s vision to become a <strong>leading financial institution</strong> through innovation, digital transformation, and sustainable development.<br><br>\n\n<strong>Way Forward:</strong><br>\nThe Board reaffirmed its focus on <strong>accelerating digital transformation, expanding services, and adopting best governance practices</strong> to better serve customers and stakeholders.<br><br>\n\n<div dir=\"rtl\" style=\"text-align: right;\">\n<strong>اسلام آباد –</strong> بینک آف آزاد جموں و کشمیر (BAJK) کے <strong>بورڈ آف ڈائریکٹرز</strong> کا <strong>92 واں اجلاس</strong> <strong>پیر کے روز اسلام آباد</strong> میں منعقد ہوا، جس کی صدارت <strong>محترم خان عبدالمجید خان</strong>، وزیرِ خزانہ و کوآپریٹیوز، حکومت آزاد جموں و کشمیر و چیئرمین BAJK نے کی۔<br><br>\n\n<strong>شرکاء بورڈ اجلاس:</strong><br>\n- <strong>محترم خان عبدالمجید خان</strong> (چیئرمین)<br>\n- <strong>جناب شاہد شہزاد میر</strong> (صدر و سی ای او، BAJK)<br>\n- <strong>جناب اسلام زیب</strong> (سیکرٹری خزانہ، آزاد کشمیر)<br>\n- <strong>جناب خالد محمود مرزا</strong> (سیکرٹری صنعت و تجارت، آزاد کشمیر)<br>\n- <strong>جناب محمد سجاد</strong> (سیکرٹری قانون و انصاف، آزاد کشمیر)<br>\n- <strong>جناب مبشر نبی</strong><br>\n- <strong>محترمہ بشریٰ ناز ملک</strong> (بورڈ ممبر)<br>\n- <strong>ڈاکٹر عدنان اللہ خان</strong> (کمپنی سیکرٹری)<br><br>\n\n<strong>اہم نکات:</strong><br>\n1. <strong>کور بینکنگ سسٹم معاہدے کی تقریب:</strong><br>\n&nbsp;&nbsp;- بورڈ نے حال ہی میں منعقدہ <strong>کور بینکنگ سسٹم معاہدے کی دستخطی تقریب</strong> پر اطمینان کا اظہار کیا، جو <strong>وزیراعظم آزاد کشمیر</strong> اور اعلیٰ حکومتی افسران کی موجودگی میں منعقد ہوئی۔<br>\n&nbsp;&nbsp;- اس موقع پر نئے نظام کے <strong>فوری نفاذ</strong> پر زور دیا گیا تاکہ ڈیجیٹل بینکنگ خدمات اور آپریشنز میں بہتری لائی جا سکے۔<br><br>\n\n2. <strong>نئی ESG کمیٹی کی منظوری:</strong><br>\n&nbsp;&nbsp;- بورڈ نے نئی تشکیل شدہ <strong>ماحولیاتی، سماجی و طرزِ حکمرانی (ESG) کمیٹی</strong> کے <strong>کارِ منصبی حدود (ToRs)</strong> کی منظوری دی، جو پائیدار اور ذمہ دار بینکاری کے عزم کی عکاسی کرتا ہے۔<br><br>\n\n3. <strong>اسٹریٹجک امور پر گفتگو:</strong><br>\n&nbsp;&nbsp;- جاری اقدامات کی پیش رفت کا جائزہ لیا گیا، جس میں <strong>مالی ترقی، ٹیکنالوجی میں بہتری، اور کسٹمر سروس میں بہتری</strong> پر توجہ دی گئی۔<br><br>\n\n<strong>چیئرمین کے تاثرات:</strong><br>\nمحترم خان عبدالمجید خان نے بینک کی قیادت، بورڈ ممبران اور تمام اسٹیک ہولڈرز کی کاوشوں کو سراہا جنہوں نے بینک کو ترقی کی راہ پر گامزن کیا۔ انہوں نے اس عزم کا اعادہ کیا کہ BAJK کا وژن <strong>ایک معروف مالیاتی ادارہ</strong> بننا ہے جو جدت، ڈیجیٹل ٹرانسفارمیشن اور پائیدار ترقی کے ذریعے ممکن ہو گا۔<br><br>\n\n<strong>آئندہ کا لائحہ عمل:</strong><br>\nبورڈ نے <strong>ڈیجیٹل تبدیلی کو تیز کرنے، سروسز میں توسیع، اور بہترین گورننس اصولوں کو اپنانے</strong> پر توجہ مرکوز رکھنے کا اعادہ کیا تاکہ صارفین اور شراکت داروں کو بہتر سہولیات فراہم کی جا سکیں۔<br><br>\n</div>', 'Islamabad \n            The 92nd meeting of the Board of Directors (BoD) of Bank of Azad Jammu & Kashmir (BAJK) was held on Monday in Islamabad, chaired by Mr. Khan Abdul Majid Khan, Honorable Minister...', 'news-images/YwQFU5bBk7RgCL5ldO3ILm7nNEXyaVYrhcHkQVbk.jpg', '2025-06-25', 0, 'banking', '92nd-meeting-of-the-board-of-directors-of-bajk-held-in-islamabad', 1, '2025-08-06 06:51:59', '2026-02-02 05:15:34'),
(24, 'Spirit of Unity and Patriotism Highlighted at BAJK Rawalakot Independence Day Celebration', 'Rawalakot<br>\nOn the occasion of <strong>Independence Day</strong>, a cake cutting ceremony was held at the <strong>BAJK-Regional Office Rawalakot</strong>. The event was graced by the <strong>Regional Head Rawalakot</strong>, accompanied by Regional Managers and staff from various branches. The ceremony reflected a <strong>spirit of patriotism and unity</strong>, bringing together team members to celebrate the national day with enthusiasm and pride.<br><br>\n\n<div dir=\"rtl\" style=\"text-align: right;\">\n<strong>یومِ آزادی کے موقع پر تقریب</strong><br>\n<strong>راولا کوٹ،</strong><br>\nیومِ آزادی کے موقع پر <strong>بینک آف آزاد جموں و کشمیر کے ریجنل آفس راولا کوٹ</strong> میں کیک کاٹنے کی تقریب منعقد ہوئی۔ اس تقریب میں <strong>ریجنل ہیڈ راولا کوٹ</strong> نے شرکت کی، جبکہ مختلف شاخوں کے ریجنل منیجرز اور عملہ بھی موجود تھا۔<br><br>\n\nیہ تقریب <strong>حب الوطنی اور اتحاد</strong> کے جذبے کی عکاسی کرتی ہے، جس میں ٹیم کے اراکین نے قومی دن کو جوش و خروش اور فخر کے ساتھ منایا۔<br>\n</div>', 'Rawalakot\nOn the occasion of Independence Day, a cake cutting ceremony was held at the BAJK-Regional Office Rawalakot. The event was graced by the Regional Head Rawalakot, accompanied by Regional Mana...', 'news-images/zLGuuThIRNOoBUAr4XjLk7uMyvNXOjrKNVVlC4ge.jpg', '2025-08-14', 0, 'general', 'spirit-of-unity-and-patriotism-highlighted-at-bajk-rawalakot-independence-day-celebration', 1, '2025-08-18 07:50:48', '2026-02-02 05:17:56'),
(25, 'Tribute on the 78th Independence Day by the President & CEO, BAJK', 'Independence Day Message<br>\nAs we celebrate the <strong>78th Independence Day</strong> of our beloved homeland, I extend my heartfelt greetings to the people of Pakistan and Azad Jammu & Kashmir. This day reminds us of the countless sacrifices made by our forefathers for the priceless gift of freedom, and now it is our duty to honor that legacy with unity, dedication, and purpose.<br><br>\n\nOn this occasion, I pay the highest tribute to the valiant <strong>Pakistan Armed Forces</strong>, who continue to guard our homeland with unwavering courage, unmatched dedication, and unshakable resolve. Their sacrifices—past and present—are the backbone of our sovereignty and the pride of every Pakistani and Kashmiri.<br><br>\n\nAs <strong>President & CEO</strong> of the Bank of Azad Jammu & Kashmir, I reaffirm our commitment to serving the people of AJK and Pakistan with integrity, innovation, and purpose. Let this Independence Day be a moment of renewal—of our unity, our resolve, and our shared vision for a stronger, more prosperous Pakistan.<br><br>\n\nMay our flag always fly with pride and may our beloved homeland continue to thrive as a beacon of peace, progress, and justice.<br><br>\n\n<strong>Pakistan Zindabad</strong><br>\n<strong>Salute to the Pakistan Army</strong><br><br>\n\n— <strong>Shahid Mir</strong><br>\n<strong>President/CEO</strong><br>\n<strong>Bank of Azad Jammu & Kashmir</strong><br><br>\n\n<div dir=\"rtl\" style=\"text-align: right;\">\n<strong>یومِ آزادی کا پیغام</strong><br>\nجیسے ہی ہم اپنی پیاری سرزمین کا <strong>78واں یومِ آزادی</strong> منا رہے ہیں، میں پاکستان اور آزاد جموں و کشمیر کے عوام کو دلی مبارکباد پیش کرتا ہوں۔ یہ دن ہمیں اُن بے شمار قربانیوں کی یاد دلاتا ہے جو ہمارے بزرگوں نے ہمیں آزادی کی انمول نعمت دینے کے لیے دی تھیں۔ اب یہ ہماری ذمہ داری ہے کہ ہم اس ورثے کو اتحاد، لگن اور مقصد کے ساتھ آگے بڑھائیں۔<br><br>\n\nاس موقع پر میں <strong>پاک افواج</strong> کے بہادر جوانوں کو خراجِ تحسین پیش کرتا ہوں جو جرات، غیر متزلزل عزم اور بے مثال قربانیوں کے ساتھ ہمارے وطن کی حفاظت کر رہے ہیں۔ اُن کی قربانیاں، چاہے وہ ماضی کی ہوں یا حال کی، ہماری خودمختاری کی بنیاد اور ہر پاکستانی و کشمیری کا فخر ہیں۔<br><br>\n\nبطور <strong>صدر و چیف ایگزیکٹو</strong> بینک آف آزاد جموں و کشمیر، میں اپنے عزم کی تجدید کرتا ہوں کہ ہم اے جے کے اور پاکستان کے عوام کی خدمت دیانتداری، جدت اور عزم کے ساتھ جاری رکھیں گے۔ آئیے اس یومِ آزادی کو تجدید کا لمحہ بنائیں — ہمارے اتحاد، ہمارے عزم اور ایک مضبوط اور خوشحال پاکستان کے ہمارے مشترکہ وژن کی تجدید۔<br><br>\n\nاللہ کرے ہمارا پرچم ہمیشہ سربلند رہے اور ہمارا پیارا وطن امن، ترقی اور انصاف کی علامت بن کر ہمیشہ پروان چڑھتا رہے۔<br><br>\n\n<strong>پاکستان زندہ باد</strong><br>\n<strong>پاک فوج کو سلام</strong><br><br>\n\n— <strong>شاہد میر</strong><br>\n<strong>صدر / چیف ایگزیکٹو</strong><br>\n<strong>بینک آف آزاد جموں و کشمیر</strong>\n</div>', 'Independence Day Message\nAs we celebrate the 78th Independence Day of our beloved homeland, I extend my heartfelt greetings to the people of Pakistan and Azad Jammu & Kashmir. This day reminds us of t...', 'news-images/dPirVd6Srkq0UG1p3CGyDmUThaGmIs2sGHEYSTmH.jpg', '2025-08-14', 0, 'general', 'tribute-on-the-78th-independence-day-by-the-president-ceo-bajk', 1, '2025-08-18 07:52:10', '2026-02-02 05:13:15'),
(26, 'President & CEO BAJK Mr. Shahid Shahzad Mir Undertakes Landmark Visit to Rawalakot Region', 'Rawalakot, Azad Jammu & Kashmir<br>\nThe <strong>President & Chief Executive Officer of Bank of Azad Jammu & Kashmir (BAJK), Mr. Shahid Shahzad Mir</strong>, undertook a significant visit to the Rawalakot region, where he was warmly welcomed by bank officials, local dignitaries, and the community.<br><br>\n\nDuring his visit, the CEO chaired high-level meetings to review the bank’s operational performance, customer service standards, and the progress of digital initiatives in the region. He reiterated the bank’s unwavering commitment to enhancing financial inclusion and delivering innovative, accessible banking solutions to the people of Azad Jammu & Kashmir.<br><br>\n\nMr. Mir was accompanied by the <strong>Divisional Head of Commercial & Retail Banking Division (CRBD), the Divisional Head of Credit Management Division (CMD), and the Regional Head of Rawalakot</strong>. The officials provided comprehensive insights into the bank’s regional growth, portfolio performance, and community outreach strategies.<br><br>\n\nAs a highlight of the visit, the CEO distributed certificates and awards among high-performing employees, recognizing their exceptional dedication and significant contribution to the bank’s success. He commended the entire Rawalakot team for their efforts in upholding BAJK’s core values and vigorously driving its mission forward.<br><br>\n\nThe visit underscored BAJK’s strategic focus on strengthening its regional presence, empowering local communities, and understanding the unique financial needs of the people it serves.<br><br>\n\n<div dir=\"rtl\" style=\"text-align: right;\">\n<strong>راولاکوٹ، آزاد جموں و کشمیر</strong><br>\n<strong>بینک آف آزاد جموں و کشمیر (BAJK) کے صدر و چیف ایگزیکٹو آفیسر، جناب شاہد شہزاد میر</strong> نے راولاکوٹ ریجن کا ایک اہم دورہ کیا، جہاں بینک افسران، مقامی معززین اور عوام نے ان کا پُرتپاک استقبال کیا۔<br><br>\n\nاپنے دورے کے دوران، سی ای او نے اعلیٰ سطحی اجلاسوں کی صدارت کی جن میں بینک کی عملی کارکردگی، صارفین کو فراہم کی جانے والی خدمات کے معیار اور ریجن میں جاری ڈیجیٹل اقدامات کی پیش رفت کا تفصیلی جائزہ لیا گیا۔ انہوں نے اس عزم کا اعادہ کیا کہ بینک مالی شمولیت کو فروغ دینے اور آزاد جموں و کشمیر کے عوام کو جدید، قابلِ رسائی اور جدت پر مبنی بینکاری سہولیات فراہم کرنے کے لیے پُرعزم ہے۔<br><br>\n\nاس موقع پر <strong>کمرشل و ریٹیل بینکنگ ڈویژن (CRBD) کے ڈویژنل ہیڈ، کریڈٹ مینجمنٹ ڈویژن (CMD) کے ڈویژنل ہیڈ اور ریجنل ہیڈ راولاکوٹ</strong> بھی ان کے ہمراہ تھے۔ ان افسران نے بینک کی ریجنل ترقی، پورٹ فولیو کارکردگی اور کمیونٹی سے روابط کی حکمت عملیوں پر جامع بریفنگ دی۔<br><br>\n\nدورے کی نمایاں جھلک میں، سی ای او نے شاندار کارکردگی دکھانے والے ملازمین میں اسناد اور ایوارڈز تقسیم کیے اور ان کی غیرمعمولی لگن اور بینک کی کامیابی میں نمایاں خدمات کو سراہا۔ انہوں نے پوری راولاکوٹ ٹیم کو خراجِ تحسین پیش کیا کہ انہوں نے BAJK کے بنیادی اقدار کو برقرار رکھتے ہوئے اس کے مشن کو بھرپور انداز میں آگے بڑھایا۔<br><br>\n\nیہ دورہ اس بات کی عکاسی کرتا ہے کہ BAJK اپنی ریجنل موجودگی کو مضبوط بنانے، مقامی کمیونٹیز کو بااختیار کرنے اور عوام کی منفرد مالی ضروریات کو سمجھنے پر اسٹریٹیجک توجہ دے رہا ہے۔<br>\n</div>', 'Rawalakot, Azad Jammu & Kashmir\nThe President & Chief Executive Officer of Bank of Azad Jammu & Kashmir (BAJK), Mr. Shahid Shahzad Mir, undertook a significant visit to the Rawalakot region, where he ...', 'news-images/Sv3Q3WTBJ8wCVjsNb8JZIJRnRLtGJl3TwXrusJTv.jpg', '2025-09-01', 0, 'banking', 'president-ceo-bajk-mr-shahid-shahzad-mir-undertakes-landmark-visit-to-rawalakot-region', 1, '2025-09-02 09:50:34', '2026-02-02 05:11:20'),
(27, 'BAJK President & CEO Mr. Shahid Shahzad Mir Undertakes Landmark Visit to Kotli Region', 'Kotli, Azad Jammu & Kashmir<br>\nThe <strong>President & Chief Executive Officer of Bank of Azad Jammu & Kashmir (BAJK), Mr. Shahid Shahzad Mir</strong>, undertook a landmark visit to the Kotli region, where he was warmly welcomed by bank officials, local dignitaries, and the community.<br><br>\n\nDuring the visit, the CEO chaired high-level meetings aimed at reviewing the bank’s operational performance, customer service standards, and the implementation of digital initiatives in the region. He emphasized the bank’s commitment to enhancing financial inclusion and delivering innovative banking solutions to the people of Azad Jammu & Kashmir.<br><br>\n\nMr. Mir was accompanied by the <strong>DH Commercial & Retail Banking Division (CRBD), Regional Head, and other senior officials</strong>, who provided insights into the bank’s regional growth and outreach strategies.<br><br>\n\nAs a highlight of the visit, the CEO distributed certificates and awards among high-performing employees, recognizing their dedication and contribution to the bank’s success. He commended the team’s efforts in upholding BAJK’s values and driving its mission forward.<br><br>\n\nThe visit underscored BAJK’s focus on strengthening its regional presence and fostering deeper connections with local communities.<br><br>\n\n<div dir=\"rtl\" style=\"text-align: right;\">\n<strong>کوٹلی، آزاد جموں و کشمیر</strong><br>\n<strong>بینک آف آزاد جموں و کشمیر (BAJK) کے صدر و چیف ایگزیکٹو آفیسر، مسٹر شاہد شہزاد میر</strong> نے کوٹلی ریجن کا ایک تاریخی دورہ کیا، جہاں ان کا پُرتپاک استقبال بینک افسران، مقامی معززین اور عوام نے کیا۔<br><br>\n\nاپنے دورے کے دوران، سی ای او نے اعلیٰ سطحی اجلاسوں کی صدارت کی جن میں بینک کی کارکردگی، صارفین کو فراہم کی جانے والی خدمات کے معیار اور ریجن میں ڈیجیٹل اقدامات کے نفاذ کا جائزہ لیا گیا۔ انہوں نے اس عزم کا اعادہ کیا کہ بینک مالی شمولیت کو فروغ دینے اور عوام کو جدید، ٹیکنالوجی پر مبنی بینکاری سہولیات فراہم کرنے کے لیے پرعزم ہے۔<br><br>\n\nاس موقع پر <strong>ڈی ایچ کمرشل اینڈ ریٹیل بینکنگ ڈویژن (CRBD)، ریجنل ہیڈ اور دیگر سینئر افسران</strong> بھی ان کے ہمراہ تھے، جنہوں نے ریجنل ترقی اور outreach منصوبوں پر تفصیلی بریفنگ دی۔<br><br>\n\nدورے کی نمایاں جھلک میں، سی ای او نے بہترین کارکردگی دکھانے والے ملازمین کو سرٹیفکیٹس اور ایوارڈز سے نوازا اور ان کی خدمات کو سراہا۔ انہوں نے کہا کہ ٹیم کی یہ کاوشیں BAJK کے اقدار کو برقرار رکھنے اور اس کے مشن کو آگے بڑھانے میں کلیدی کردار ادا کر رہی ہیں۔<br><br>\n\nیہ دورہ BAJK کے اس عزم کی عکاسی کرتا ہے کہ ادارہ اپنی ریجنل موجودگی کو مزید مستحکم بنائے گا، عوامی خدمات میں بہتری لائے گا اور مقامی کمیونٹی کے ساتھ مضبوط تعلقات استوار کرے گا۔<br>\n</div>', 'Kotli, Azad Jammu & Kashmir\nThe President & Chief Executive Officer of Bank of Azad Jammu & Kashmir (BAJK), Mr. Shahid Shahzad Mir, undertook a landmark visit to the Kotli region, where he was warmly ...', 'news-images/mltNaFtqU49s0oFNB93ZvPozRMOsIKSbMj4aMnjw.jpg', '2025-08-30', 0, 'general', 'bajk-president-ceo-mr-shahid-shahzad-mir-undertakes-landmark-visit-to-kotli-region', 1, '2025-09-02 09:54:41', '2026-02-02 05:10:01'),
(28, 'BAJK Board of Directors Holds 93rd Meeting to Accelerate Digital Transformation and Strategic Growth', 'Islamabad<br>\nThe 93rd meeting of the <strong>Board of Directors of Bank of Azad Jammu & Kashmir (BAJK)</strong> was convened at <strong>Kashmir House, Islamabad</strong> on Thursday. The meeting was chaired by <strong>Mr. Khan Abdul Majid Khan, Honorable Minister for Finance & Cooperatives, Government of Azad Jammu & Kashmir, and Chairman of BAJK</strong>.<br><br>\n\nThe Board members reviewed the Bank\\\'s strategic progress and charted the course for its future initiatives.<br><br>\n\nThe meeting saw participation from key members including:<br>\n- <strong>President & CEO, Mr. Shahid Shahzad Mir</strong><br>\n- <strong>Secretary Finance, AJK, Mr. Islam Zaib</strong><br>\n- <strong>Secretary Industries & Commerce, AJK, Ch. Abdul Rehman</strong><br>\n- <strong>Secretary Law & Justice, Mr. Muhammad Sajjad</strong><br>\n- <strong>Company Secretary, Dr. Adnanullah Khan</strong><br>\nOther directors, <strong>Mr. Mubashar Nabi</strong> and <strong>Ms. Bushra Naz Malik</strong>, joined the meeting via Zoom.<br><br>\n\n<strong>Key Discussions & Decisions:</strong><br>\n1. <strong>Expedited Core Banking System Implementation:</strong><br>\nThe Board received a comprehensive update on the ongoing project with Silverlake. Directives were issued to accelerate the implementation process and complete it at the earliest. The Board emphasized that this modernization is vital for enhancing digital banking services, operational efficiency, and superior customer experience.<br><br>\n\n2. <strong>Acquisition of Schedule Bank Status:</strong><br>\nA key strategic priority was the process of obtaining Schedule Bank status from the State Bank of Pakistan (SBP). The Board directed the management to complete the required steps and secure SBP approval as early as possible.<br><br>\n\n3. <strong>Strategic Roadmap Review:</strong><br>\nThe Board deliberated on ongoing initiatives aimed at strengthening the Bank\\\'s financial performance, expanding its service network, and adopting cutting-edge banking technologies.<br><br>\n\n<strong>Chairman\\\'s Direction:</strong><br>\nChairman <strong>Mr. Khan Abdul Majid Khan</strong> commended the management\\\'s efforts and reiterated the Board\\\'s full support for the Bank\\\'s transformational journey. He emphasized the collective commitment to innovation and sustainable growth, which is fundamental to realizing BAJK\\\'s vision of becoming a leading financial institution in the region.<br><br>\n\n<strong>Way Forward:</strong><br>\nThe Board remains focused on driving sustainable growth, expanding services, and leveraging advanced technology to deliver exceptional value to its customers and stakeholders.<br><br>\n\n<div dir=\"rtl\" style=\"text-align: right;\">\n<strong>اسلام آباد</strong><br>\n<strong>بینک آف آزاد جموں و کشمیر (بی اے جے کے)</strong> کے بورڈ آف ڈائریکٹرز کا 93واں اجلاس جمعرات کے روز <strong>کشمیر ہاؤس اسلام آباد</strong> میں منعقد ہوا۔ اجلاس کی صدارت <strong>وزیر خزانہ و کواپریٹوز حکومت آزاد جموں و کشمیر اور چیئرمین بی اے جے کے، جناب خان عبدالمجید خان</strong> نے کی۔<br><br>\n\nبورڈ کے اراکین نے بینک کی اسٹریٹیجک پیشرفت کا جائزہ لیا اور مستقبل کے اقدامات کے لیے رہنما اصول مرتب کیے۔<br><br>\n\nاجلاس میں اہم اراکین نے شرکت کی، جن میں شامل ہیں:<br>\n<strong>صدر و سی ای او جناب شاہد شہزاد میر</strong><br>\n<strong>سیکرٹری فنانس جناب اسلام زیب</strong><br>\n<strong>سیکرٹری انڈسٹریز و کامرس چوہدری عبدالرحمٰن</strong><br>\n<strong>سیکرٹری لاء اینڈ جسٹس جناب محمد سجاد</strong><br>\n<strong>کمپنی سیکرٹری ڈاکٹر عدنان اللہ خان</strong><br>\nدیگر ڈائریکٹرز <strong>جناب مبشر نبی</strong> اور <strong>محترمہ بشریٰ ناز ملک</strong> نے زوم کے ذریعے اجلاس میں شرکت کی۔<br><br>\n\n<strong>اہم امور اور فیصلے:</strong><br>\n1. <strong>بنیادی بینکاری نظام کے نفاذ میں تیزی:</strong><br>\nبورڈ کو سلورلیک کے ساتھ جاری منصوبے پر تفصیلی بریفنگ دی گئی۔ ہدایت دی گئی کہ اس کے نفاذ کے عمل کو تیز کیا جائے اور جلد از جلد مکمل کیا جائے۔ بورڈ نے اس بات پر زور دیا کہ یہ جدیدیت ڈیجیٹل بینکاری خدمات، آپریشنل کارکردگی اور اعلیٰ معیار کے صارفین کے تجربے کو بہتر بنانے کے لیے نہایت اہم ہے۔<br><br>\n\n2. <strong>شیڈول بینک کا درجہ حاصل کرنا:</strong><br>\nبورڈ نے ایک اہم اسٹریٹیجک ترجیح کے طور پر غور کیا کہ اسٹیٹ بینک آف پاکستان (ایس بی پی) سے شیڈول بینک کا درجہ حاصل کرنے کے لیے ضروری اقدامات مکمل کیے جائیں اور فوری منظوری لی جائے۔<br><br>\n\n3. <strong>اسٹریٹیجک روڈ میپ کا جائزہ:</strong><br>\nبورڈ نے مختلف جاری اقدامات پر غور کیا جن کا مقصد بینک کی مالی کارکردگی کو بہتر بنانا، سروس نیٹ ورک کو وسعت دینا اور جدید بینکاری ٹیکنالوجیز اپنانا ہے۔<br><br>\n\n<strong>چیئرمین کی ہدایت:</strong><br>\nچیئرمین <strong>جناب خان عبدالمجید خان</strong> نے مینجمنٹ کی کاوشوں کو سراہا اور بینک کے انقلابی سفر کے لیے بورڈ کی مکمل حمایت کا اعادہ کیا۔ انہوں نے جدت اور پائیدار ترقی کے اجتماعی عزم پر زور دیا، جو بی اے جے کے کے وژن کو ایک نمایاں مالیاتی ادارہ بنانے کے لیے بنیادی حیثیت رکھتا ہے۔<br><br>\n\n<strong>آئندہ کا لائحہ عمل:</strong><br>\nبورڈ پائیدار ترقی، خدمات کے دائرہ کار کو وسعت دینے اور جدید ٹیکنالوجی سے فائدہ اٹھا کر صارفین اور اسٹیک ہولڈرز کو شاندار قدر فراہم کرنے پر توجہ مرکوز رکھے گا۔<br>\n</div>', 'Islamabad\nThe 93rd meeting of the Board of Directors of Bank of Azad Jammu & Kashmir (BAJK) was convened at Kashmir House, Islamabad on Thursday. The meeting was chaired by Mr. Khan Abdul Majid Khan, ...', 'news-images/EnJTatQzFi9OSzwburEJjWtTpA4obBwk7yjpUrYI.jpg', '2025-08-29', 0, 'banking', 'bajk-board-of-directors-holds-93rd-meeting-to-accelerate-digital-transformation-and-strategic-growth', 1, '2025-09-02 09:58:19', '2026-02-02 05:09:09'),
(29, 'Prime Minister’s Youth Loan Program Launched to Support Startups Across Azad Kashmir', 'Islamabad: Under the vision of the Prime Minister of Azad Jammu & Kashmir, Chaudhry Anwar Haq, for Youth Empowerment, the Bank of Azad Jammu & Kashmir (BAJK) and the Azad Kashmir Small Industries Corporation (AKSIC) have signed a Memorandum of Understanding (MoU) for the implementation of the Prime Minister’s Youth Loan Program.<br><br>\n\nThe signing ceremony was held on Thursday at the BAJK Camp Office. It was attended by Minister for Finance & Cooperatives and Chairman of the Bank, Mr. Khan Abdul Majid Khan; Minister for Small Industries & TATA, Prof. Taqdees Gilani; Secretary Finance, Mr. Islam Zeb; Secretary Industries, Mr. Chaudhry Abdul Rehman; President/CEO BAJK, Mr. Shahid Shahzad Mir; Managing Director Small Industries, Mr. Muhammad Zeeshan; Director Small Industries, Mr. Abdul Khaliq Abbasi; DH CMD, Mr. Muhammad Imtiaz Shaheen; along with other distinguished personalities.<br><br>\n\n<hr> **Key Highlights:**<br> • Under this scheme, young people will be provided **interest-free loans (zero markup)** ranging from **PKR 100,000 to PKR 2,000,000**. These loans will be given for **new and startup businesses**.<br> • The primary objective of the scheme is to provide interest-free loans to the youth of the region, enabling them to **develop entrepreneurial skills**, **create new employment opportunities**, **reduce poverty**, and **promote economic activities in the private sector**.<br> • As per the agreement, both institutions will assist young people across **all ten districts of Azad Kashmir** in establishing and promoting small businesses.<br> • After the formal signing of the MoU, the scheme will become fully operational.<br> • The **Secretary Industries of AKSIC** stated: “This step is a significant milestone towards turning the dreams of young people into reality.”<br> • The **President of the Bank** said: “The entire team of the Bank is determined to make this scheme a success. We will provide not only financial but also technical support to young entrepreneurs.”<br> • Through this scheme, a new ray of hope is expected to shine for **thousands of young people in Azad Kashmir**, paving the way for a brighter future.<br><br> <hr> <div dir=\"rtl\" style=\"text-align: right;\"> <strong>BAJK نے وزیراعظم یوتھ لون پروگرام کے ذریعے آزاد کشمیر میں اسٹارٹ اپس کی حمایت شروع کی</strong><br><br>\n\nاسلام آباد: <strong>وزیراعظم آزاد جموں و کشمیر، چوہدری انور الحق</strong> کے وژن <strong>یوتھ ایمپاورمنٹ</strong> کے تحت، <strong>بینک آف آزاد جموں و کشمیر (BAJK)</strong> اور <strong>آزاد کشمیر اسمال انڈسٹریز کارپوریشن (AKSIC)</strong> نے <strong>وزیراعظم یوتھ لون پروگرام</strong> کے نفاذ کے لیے <strong>مفاہمتی یادداشت (MoU)</strong> پر دستخط کیے۔<br><br>\n\nدستخطی تقریب جمعرات کو <strong>BAJK کیمپ آفس</strong> میں منعقد ہوئی۔ اس میں <strong>وزیر خزانہ و کواپریٹوز و چئیرمین بینک، جناب خان عبدالماجد خان</strong>؛ <strong>وزیر سمال انڈسٹریز و ٹاٹا، پروفیسر تقدیس گیلانی</strong>؛ <strong>سیکرٹری خزانہ، جناب اسلام زیب</strong>؛ <strong>سیکرٹری انڈسٹریز، جناب چوہدری عبدالرحمن</strong>؛ <strong>صدر/سی ای او BAJK، جناب شاہد شہزاد میر</strong>؛ <strong>منیجنگ ڈائریکٹر اسمال انڈسٹریز، جناب محمد زیشان</strong>؛ <strong>ڈائریکٹر اسمال انڈسٹریز، جناب عبدالخالق عباسی</strong>؛ <strong>ڈی ایچ CMD، جناب محمد امتیاز شاہین</strong> اور دیگر معزز شخصیات نے شرکت کی۔<br><br>\n\n<hr> <strong>اہم نکات:</strong><br> • اس سکیم کے تحت نوجوانوں کو <strong>بلا سود قرضے (زیرو مارک اپ)</strong> فراہم کیے جائیں گے، جو <strong>1 لاکھ سے 20 لاکھ روپے</strong> تک ہوں گے اور <strong>نئے اور اسٹارٹ اپ کاروبار</strong> کے لیے دیے جائیں گے۔<br> • اس سکیم کا مقصد نوجوانوں کو بلاسود قرضے دے کر ان میں <strong>کاروباری مہارتیں پیدا کرنا</strong>، <strong>روزگار کے نئے مواقع فراہم کرنا</strong>، <strong>غربت میں کمی لانا</strong>، اور <strong>نجی شعبے میں معاشی سرگرمیوں کو فروغ دینا</strong> ہے۔<br> • معاہدے کے مطابق، دونوں ادارے آزاد کشمیر کے <strong>تمام دس اضلاع</strong> میں نوجوانوں کو چھوٹے کاروبار قائم کرنے اور ان کی ترقی میں مدد فراہم کریں گے۔<br> • MoU پر دستخط کے بعد یہ سکیم مکمل طور پر نافذ العمل ہو جائے گی۔<br> • <strong>سیکرٹری انڈسٹریز AKSIC</strong> نے کہا: \"یہ قدم نوجوانوں کے خوابوں کو حقیقت میں بدلنے کی جانب ایک اہم پیش رفت ہے۔\"<br> • <strong>صدر بینک</strong> نے کہا: \"بینک کی پوری ٹیم اس سکیم کو کامیاب بنانے کے لیے پرعزم ہے۔ ہم نوجوان کاروباریوں کو مالی اور تکنیکی معاونت فراہم کریں گے۔\"<br> • اس سکیم کے ذریعے آزاد کشمیر کے <strong>ہزاروں نوجوانوں</strong> کے لیے روشن مستقبل کی امید پیدا ہوگی۔<br> </div>', 'Islamabad: Under the vision of the Prime Minister of Azad Jammu & Kashmir, Chaudhry Anwar Haq, for Youth Empowerment, the Bank of Azad Jammu & Kashmir (BAJK) and the Azad Kashmir Small Industries Corp...', 'news-images/N9sUjk3rdcQ2TvLJKm2nZKcPvvLThFo0FG4M2R81.jpg', '2025-08-26', 0, 'announcements', 'prime-ministers-youth-loan-program-launched-to-support-startups-across-azad-kashmir', 1, '2025-09-02 10:00:47', '2026-01-29 12:43:51'),
(30, 'President & CEO BAJK Mr. Shahid Shahzad Mir Undertakes Landmark Visit to Mirpur Region', 'Mirpur, Azad Jammu & Kashmir<br>\r\nThe <strong>President & Chief Executive Officer of Bank of Azad Jammu & Kashmir (BAJK), Mr. Shahid Shahzad Mir</strong>, undertook a significant visit to the Mirpur region, where he was warmly welcomed by bank officials, local dignitaries, and the community.<br><br>\r\n\r\nDuring his visit, the CEO chaired high-level meetings to review the bank’s operational performance, customer service standards, and the progress of digital initiatives in the region. He reiterated the bank’s unwavering commitment to enhancing financial inclusion and delivering innovative, accessible banking solutions to the people of Azad Jammu & Kashmir.<br><br>\r\n\r\nMr. Mir was accompanied by the <strong>Divisional Head of Commercial & Retail Banking Division (CRBD) and the Regional Head of Mirpur</strong>. The officials provided comprehensive insights into the bank’s regional growth, portfolio performance, and community outreach strategies.<br><br>\r\n\r\nAs a highlight of the visit, the CEO distributed certificates and awards among high-performing employees, recognizing their exceptional dedication and significant contribution to the bank’s success. He commended the entire Mirpur team for their efforts in upholding BAJK’s core values and vigorously driving its mission forward.<br><br>\r\n\r\nThe visit underscored BAJK’s strategic focus on strengthening its regional presence, empowering local communities, and understanding the unique financial needs of the people it serves.<br><br>\r\n\r\n<div dir=\"rtl\" style=\"text-align: right;\">\r\n<strong>میرپور، آزاد جموں و کشمیر</strong><br>\r\n<strong>بینک آف آزاد جموں و کشمیر (BAJK) کے صدر و چیف ایگزیکٹو آفیسر، جناب شاہد شہزاد میر</strong> نے میرپور ریجن کا ایک اہم دورہ کیا، جہاں ان کا پُرتپاک استقبال بینک افسران، مقامی معززین اور عوام نے کیا۔<br><br>\r\n\r\nاپنے دورے کے دوران، سی ای او نے اعلیٰ سطحی اجلاسوں کی صدارت کی جن میں بینک کی عملی کارکردگی، صارفین کو فراہم کی جانے والی خدمات کے معیار اور ریجن میں جاری ڈیجیٹل اقدامات کی پیش رفت کا تفصیلی جائزہ لیا گیا۔ انہوں نے اس عزم کا اعادہ کیا کہ بینک مالی شمولیت کے فروغ اور آزاد جموں و کشمیر کے عوام کو جدید، قابلِ رسائی اور جدت پر مبنی بینکاری سہولیات فراہم کرنے کے لیے پُرعزم ہے۔<br><br>\r\n\r\n<strong>کمرشل و ریٹیل بینکنگ ڈویژن (CRBD) کے ڈویژنل ہیڈ اور ریجنل ہیڈ میرپور</strong> بھی ان کے ہمراہ تھے۔ ان افسران نے بینک کی ریجنل ترقی، پورٹ فولیو کارکردگی اور کمیونٹی سے روابط کی حکمت عملیوں پر جامع بریفنگ دی۔<br><br>\r\n\r\nدورے کی نمایاں جھلک میں، سی ای او نے شاندار کارکردگی دکھانے والے ملازمین میں اسناد اور ایوارڈز تقسیم کیے اور ان کی غیرمعمولی لگن اور بینک کی کامیابی میں نمایاں خدمات کو سراہا۔ انہوں نے پوری میرپور ٹیم کو خراجِ تحسین پیش کیا کہ انہوں نے BAJK کے بنیادی اقدار کو برقرار رکھتے ہوئے اس کے مشن کو بھرپور انداز میں آگے بڑھایا۔<br><br>\r\n\r\nیہ دورہ اس بات کی عکاسی کرتا ہے کہ BAJK اپنی ریجنل موجودگی کو مضبوط بنانے، مقامی کمیونٹیز کو بااختیار کرنے اور عوام کی منفرد مالی ضروریات کو سمجھنے پر اسٹریٹیجک توجہ دے رہا ہے۔<br>\r\n</div>', 'Mirpur, Azad Jammu & Kashmir\r\nThe President & Chief Executive Officer of Bank of Azad Jammu & Kashmir (BAJK), Mr. Shahid Shahzad Mir, undertook a significant visit to the Mirpur region, where he was w...', 'news-images/dd4DLa4H9tKQ2HPGuthTV2wRw4Kqo7sQskeHbdAR.jpg', '2025-09-02', 0, 'banking', 'president-ceo-bajk-mr-shahid-shahzad-mir-undertakes-landmark-visit-to-mirpur-region', 1, '2025-09-05 04:58:26', '2026-02-02 05:07:16'),
(31, '94th Meeting of the Board of Directors of Bank of Azad Jammu & Kashmir (BAJK)', 'Islamabad – The 94th meeting of the Board of Directors of Bank of Azad Jammu & Kashmir (BAJK) was convened at Kashmir House, Islamabad on Wednesday. The session was chaired by Mr. Khan Abdul Majid Khan, Honorable Minister for Finance & Cooperatives, Government of Azad Jammu & Kashmir, and Chairman of BAJK.<br><br>\n\nThe meeting was attended by Board members including:<br>\n• President & CEO, Mr. Shahid Shahzad Mir<br>\n• Secretary Finance, AJK, Mr. Islam Zaib<br>\n• Mr. Mubashar Nabi<br>\n• Secretary Industries & Commerce, AJK, Ch. Abdul Rehman<br>\n• Secretary Law & Justice, Mr. Muhammad Sajjad<br>\n• Company Secretary, Dr. Adnanullah Khan<br>\n• Ms. Bushra Naz Malik (joined via Zoom)<br><br>\n\n<hr>\n<strong>Key Discussions & Decisions:</strong><br>\n1. Review & Approval of Half-Year Financial Statements:<br>\n• The Board reviewed and approved the Bank’s financial statements for the half-year, expressing satisfaction over the robust financial performance and operational growth achieved during the period.<br><br>\n\n2. Five-Year Strategic Plan for Early Scheduling & Progress:<br>\n• The President & CEO presented a comprehensive five-year strategic roadmap focusing on early scheduling, sustainable growth, technological advancement, and expansion of services.<br>\n• The Board thoroughly discussed the plan and expressed full satisfaction, appreciating the management’s vision and commitment towards strengthening the Bank’s future.<br><br>\n\n3. Continued Focus on Schedule Bank Status:<br>\n• The Board reaffirmed its commitment to expedite the process of obtaining Scheduled Bank status from the State Bank of Pakistan (SBP), emphasizing its importance for BAJK’s regional and national growth.<br><br>\n\n<hr>\n<strong>Chairman’s Remarks:</strong><br>\nChairman Mr. Khan Abdul Majid Khan lauded the management for its dedicated efforts and assured the Board’s full support in executing the strategic roadmap. He stressed that BAJK’s transformation journey, rooted in innovation and sustainable practices, will further solidify its standing as a leading financial institution.<br><br>\n\n<hr>\n<strong>Way Forward:</strong><br>\n• Driving sustainable growth<br>\n• Expanding services across AJK and beyond<br>\n• Leveraging digital transformation for customer convenience<br>\n• Achieving Schedule Bank status at the earliest<br><br>\n\n<div dir=\"rtl\" style=\"text-align: right;\">\n<strong>اسلام آباد</strong> – بینک آف آزاد جموں و کشمیر (BAJK) کے بورڈ آف ڈائریکٹرز کا 94واں اجلاس بدھ کے روز کشمیر ہاؤس، اسلام آباد میں منعقد ہوا۔ اجلاس کی صدارت جناب خان عبدالمجید خان، معزز وزیرِ خزانہ و کوآپریٹوز، حکومتِ آزاد جموں و کشمیر اور چیئرمین BAJK نے کی۔<br><br>\n\n<strong>اجلاس میں شریک اراکین:</strong><br>\n• صدر و چیف ایگزیکٹو آفیسر، جناب شاہد شہزاد میر<br>\n• سیکریٹری فنانس، اے جے کے، جناب اسلام زیب<br>\n• جناب مبشر نبی<br>\n• سیکریٹری انڈسٹریز اینڈ کامرس، اے جے کے، چوہدری عبدالرحمن<br>\n• سیکریٹری لاء اینڈ جسٹس، جناب محمد سجاد<br>\n• کمپنی سیکریٹری، ڈاکٹر عدنان اللہ خان<br>\n• محترمہ بشریٰ ناز ملک (آن لائن شرکت بذریعہ زوم)<br><br>\n\n<strong>اہم امور اور فیصلے:</strong><br>\n1. نصف سالہ مالیاتی بیانات کا جائزہ اور منظوری:<br>\n• بورڈ نے بینک کے نصف سالہ مالیاتی بیانات کا جائزہ لے کر انہیں منظور کیا اور اس مدت کے دوران حاصل کی گئی مضبوط مالیاتی کارکردگی اور عملی ترقی پر اطمینان کا اظہار کیا۔<br><br>\n\n2. پانچ سالہ اسٹریٹجک پلان برائے بروقت شیڈولنگ اور پیش رفت:<br>\n• صدر و سی ای او نے ایک جامع پانچ سالہ اسٹریٹجک روڈ میپ پیش کیا جس میں بروقت منصوبہ بندی، پائیدار ترقی، تکنیکی جدت، اور سروسز کی توسیع پر توجہ دی گئی۔<br>\n• بورڈ نے اس منصوبے پر تفصیلی بحث کی، مکمل اطمینان کا اظہار کیا اور انتظامیہ کے وژن اور بینک کے مستقبل کو مضبوط کرنے کے عزم کو سراہا۔<br><br>\n\n3. شیڈول بینک کا درجہ حاصل کرنے پر مسلسل توجہ:<br>\n• بورڈ نے اس عزم کو دہرایا کہ اسٹیٹ بینک آف پاکستان (SBP) سے شیڈول بینک کا درجہ حاصل کرنے کے عمل کو تیز کیا جائے، اور اس کی اہمیت پر زور دیا جو BAJK کی علاقائی اور قومی ترقی کے لیے ضروری ہے۔<br><br>\n\n<strong>چیئرمین کے ریمارکس:</strong><br>\nچیئرمین خان عبدالمجید خان نے انتظامیہ کی انتھک کوششوں کو سراہا اور اسٹریٹجک روڈ میپ پر عملدرآمد کے لیے بورڈ کی مکمل حمایت کی یقین دہانی کرائی۔ انہوں نے زور دیا کہ BAJK کا تبدیلی کا سفر، جو جدت اور پائیدار حکمتِ عملیوں پر مبنی ہے، ادارے کو ایک سرکردہ مالیاتی ادارے کے طور پر مزید مستحکم کرے گا۔<br><br>\n\n<strong>آئندہ کا لائحہ عمل:</strong><br>\n• پائیدار ترقی کو فروغ دینا<br>\n• آزاد جموں و کشمیر اور اس سے باہر خدمات کی توسیع<br>\n• صارفین کی سہولت کے لیے ڈیجیٹل ٹرانسفارمیشن سے فائدہ اٹھانا<br>\n• جلد از جلد شیڈول بینک کا درجہ حاصل کرنا<br>\n</div>', 'Islamabad – The 94th meeting of the Board of Directors of Bank of Azad Jammu & Kashmir (BAJK) was convened at Kashmir House, Islamabad on Wednesday. The session was chaired by Mr. Khan Abdul Majid K...', 'news-images/ysj78niUU124Q4xDdZWpqFuwfnfZADTA0r6XBIxc.jpg', '2025-09-10', 0, 'banking', '94th-meeting-of-the-board-of-directors-of-bank-of-azad-jammu-kashmir-bajk', 1, '2025-09-11 04:33:51', '2026-02-02 05:05:07'),
(32, '19 Years Celebration of Bank of Azad Jammu & Kashmir (BAJK)', 'Al- hamdulillah, The Bank of AJK has attained successful completion of 19 years of glory and prosperity. With a view to celebrate this delightful achievement of excellence, cake cutting ceremony was held at its Regional Office Muzaffarabad which was graced by the DH CRBD and DH CMD and was duly attended by all the Managers of Muzaffarabad City Branches and by the Divisional and Regional Office Muzaffarabad staff with a commitment and firm resolve to serve all our valued clients and stake holders with further dedication and enthusiasm to meet their highest expectations and financial needs.<br><br>\r\n\r\nAt this cheerful moment, the patronage and dynamic vision of worthy President, Mr. Shahid Mir was highly appreciated which has enabled this great premier Institution of the State to reach this glory n historic growth. The diversified and effective directional guidance of worthy President has really worked and enabled the Bank to accomplish and surpass the allocated business KPIs competing handsomely with highly equipped big scheduled Banks in the market. The day, truly is not far away when the BAJK will get the scheduled Bank status under the highly skilled and learned supervision of Mr Shahid Shahid Mir, the President and CEO of this great financial Institution. Long live the BAJK<br><br>\r\n<hr> <div dir=\"rtl\" style=\"text-align: right; line-height: 1.8;\"> <strong>19 سالہ جشن – بینک آف آزاد جموں و کشمیر (BAJK)</strong><br><br>\r\n\r\nالحمدللہ، بینک آف اے جے کے نے شان و شوکت اور خوشحالی کے 19 سال کامیابی کے ساتھ مکمل کر لیے ہیں۔ اس پُرمسرت اور قابلِ فخر سنگِ میل کا جشن منانے کے لیے کیک کاٹنے کی تقریب ریجنل آفس مظفرآباد میں منعقد ہوئی، جس میں DH CRBD اور DH CMD نے شرکت کی۔ اس کے علاوہ مظفرآباد سٹی برانچز کے تمام منیجران، ڈویژنل اور ریجنل آفس مظفرآباد کے عملے نے بھی بھرپور شرکت کی۔ شرکاء نے عزم کا اظہار کیا کہ وہ اپنے معزز کلائنٹس اور اسٹیک ہولڈرز کی بہتر سے بہتر خدمت کے لیے مزید لگن، جذبے اور اخلاص کے ساتھ کام جاری رکھیں گے تاکہ ان کی مالی ضروریات اور بلند توقعات کو بہترین طریقے سے پورا کیا جاسکے۔<br><br>\r\n\r\nاس پُرمسرت موقع پر معزز صدر جناب شاہد میر کی سرپرستی، متحرک وژن اور دور اندیشی کو بے حد سراہا گیا، جنہوں نے اس عظیم ریاستی ادارے کو ترقی اور تاریخی کامیابی کے اس مقام تک پہنچانے میں کلیدی کردار ادا کیا۔ معزز صدر کی مؤثر اور متنوع رہنمائی نے بینک کو اپنے مقررہ کاروباری اہداف (KPIs) حاصل کرنے اور ان سے آگے بڑھنے کے قابل بنایا، جس سے BAJK نے مارکیٹ میں بڑے شیڈول بینکوں کے مقابلے میں نمایاں کارکردگی دکھائی۔<br><br>\r\n\r\nوہ دن دور نہیں جب BAJK کو شیڈول بینک کا درجہ حاصل ہو جائے گا، کیونکہ صدر جناب  شاہد میر کی اعلیٰ مہارت اور علمی صلاحیتوں کی بدولت یہ عظیم ادارہ اس اہم سنگِ میل کی طرف بھرپور اعتماد کے ساتھ پیش قدمی کر رہا ہے۔ BAJK ہمیشہ آباد و شاد باد رہے۔<br><br>\r\n\r\n</div>', 'Al- hamdulillah, The Bank of AJK has attained successful completion of 19 years of glory and prosperity. With a view to celebrate this delightful achievement of excellence, cake cutting ceremony was h...', 'news-images/c4oYrWhehky9sobDEwzEd1aS9CfWlyKKYC3zEweq.jpg', '2025-11-04', 0, 'general', '19-years-celebration-of-bank-of-azad-jammu-kashmir-bajk', 1, '2025-12-03 05:17:58', '2026-01-29 12:43:51'),
(33, 'Leadership Training Program for BAJK Middle Management', 'NIBAF Pakistan successfully conducted a two-day Leadership Training Program for the middle management officers of the Bank of Azad Jammu & Kashmir (BAJK)<br><br>\r\n\r\n👨‍🏫 Trainer: Mr. Zaydan Khan<br>\r\n📅 Dates: October 31 – November 1, 2025<br>\r\n🏛️ Mode: Face-to-Face (F2F)<br>\r\n📍 Venue: NIBAF Pakistan – Islamabad Campus<br><br>\r\n\r\n<hr> <strong>Program Highlights:</strong><br> 🔹 Day 1: Focused on the Leadership Journey and Business Communication Skills, helping participants explore leadership styles, effective communication, and confidence-building.<br><br>\r\n\r\n🔹 Day 2: Centered on Stress Management and Outdoor Team Activities, promoting teamwork, resilience, and positive workplace engagement.<br><br>\r\n\r\nThe program empowered BAJK professionals to lead with confidence, foster collaboration, and drive organizational excellence.<br><br>\r\n\r\n<hr> <div dir=\"rtl\" style=\"text-align: right; line-height: 1.8;\"> <strong>BAJK مڈل مینجمنٹ کے لیے لیڈرشپ ٹریننگ پروگرام</strong><br><br>\r\n\r\nنیباف پاکستان نے بینک آف آزاد جموں و کشمیر (BAJK) کے مڈل مینجمنٹ افسران کے لیے دو روزہ لیڈرشپ ٹریننگ پروگرام کامیابی کے ساتھ منعقد کیا۔<br><br>\r\n\r\n👨‍🏫 ٹرینر: جناب زیدان خان<br>\r\n📅 تاریخیں: 31 اکتوبر تا 1 نومبر 2025<br>\r\n🏛️ طریقہ کار: فیس ٹو فیس (F2F)<br>\r\n📍 مقام: نیباف پاکستان – اسلام آباد کیمپس<br><br>\r\n\r\n<strong>پروگرام کی نمایاں خصوصیات:</strong><br>\r\n🔹 پہلا دن: لیڈرشپ جرنی اور بزنس کمیونیکیشن اسکلز پر مشتمل رہا، جس نے شرکاء کو لیڈرشپ اسٹائلز، مؤثر رابطے اور خود اعتمادی کی بہتری میں مدد فراہم کی۔<br><br>\r\n\r\n🔹 دوسرا دن: اسٹریس مینجمنٹ اور آؤٹ ڈور ٹیم ایکٹیویٹیز پر مشتمل تھا، جس کا مقصد ٹیم ورک، مضبوطی (Resilience)، اور مثبت ورک پلیس انگیجمنٹ کو فروغ دینا تھا۔<br><br>\r\n\r\nاس پروگرام نے BAJK کے پروفیشنلز کو اعتماد کے ساتھ قیادت کرنے، تعاون کو فروغ دینے اور ادارے میں اعلیٰ کارکردگی کے تسلسل کو یقینی بنانے میں اہم کردار ادا کیا۔<br><br>\r\n\r\n</div>', 'NIBAF Pakistan successfully conducted a two-day Leadership Training Program for the middle management officers of the Bank of Azad Jammu & Kashmir (BAJK)\r\n\r\n👨‍🏫 Trainer: Mr. Zaydan Khan\r\n📅 ...', 'news-images/FwwSHhES6bnCIl54IWlWdOaMCEvYW1ODqSsyjW5f.jpg', '2025-11-05', 0, 'general', 'leadership-training-program-for-bajk-middle-management', 1, '2025-12-03 05:46:07', '2026-02-02 05:03:42'),
(34, 'Closing Ceremony & Certificate Distribution – Teller Certification Program (Batch 4)', 'NIBAF Pakistan successfully held the Closing Ceremony and Certificate Distribution for the Teller Certification Program – Batch 4, conducted for the Bank of Azad Jammu & Kashmir.<br><br>\r\n\r\n📅 Date: 08–10 November 2025<br>\r\n🤝 Stakeholder: Bank of Azad Jammu & Kashmir (BAJK)<br>\r\n🏫 Mode: Face-to-Face (F2F)<br>\r\n📍 Venue: NIBAF Pakistan, Islamabad Campus<br><br>\r\n\r\n<hr>\r\n\r\n<strong>Chief Guest:</strong><br>\r\nMr. Abdul Majid Khan<br>\r\nFinance Minister, Government of Azad Jammu & Kashmir<br>\r\nChairman, Board of Directors – BAJK<br><br>\r\n\r\n<strong>Guests & Senior Leadership:</strong><br>\r\nMs. Lubna Farooq Malik<br>\r\nChief Executive Officer – NIBAF Pakistan<br><br>\r\n\r\nMr. Syed Sajid Ali<br>\r\nDirector, Learning & Development – NIBAF Pakistan<br><br>\r\n\r\nMs. Rahila Javed<br>\r\nDivisional Head, HRMD – Bank of Azad Jammu & Kashmir<br><br>\r\n\r\n<hr>\r\n\r\n✅ The ceremony celebrated the successful completion of the program and acknowledged the dedication of participating BAJK tellers as they continue their journey toward improved service excellence and professional growth.<br><br>\r\n\r\n<hr> <div dir=\"rtl\" style=\"text-align: right; line-height: 1.8;\">\r\n\r\n<strong>کلوزنگ تقریب اور سرٹیفکیٹ ڈسٹری بیوشن – ٹیلر سرٹیفیکیشن پروگرام (بیچ 4)</strong><br><br>\r\n\r\nنیباف پاکستان نے بینک آف آزاد جموں و کشمیر کے لیے منعقد کیے گئے ٹیلر سرٹیفیکیشن پروگرام – بیچ 4 کی اختتامی تقریب اور سرٹیفکیٹس کی تقسیم کامیابی کے ساتھ منعقد کی۔<br><br>\r\n\r\n📅 تاریخ: 08–10 نومبر 2025<br>\r\n🤝 اسٹیک ہولڈر: بینک آف آزاد جموں و کشمیر (BAJK)<br>\r\n🏫 طریقہ کار: فیس ٹو فیس (F2F)<br>\r\n📍 مقام: نیباف پاکستان، اسلام آباد کیمپس<br><br>\r\n\r\n<strong>چیف گیسٹ:</strong><br>\r\nجناب عبدالمجید خان<br>\r\nوزیر خزانہ، حکومت آزاد جموں و کشمیر<br>\r\nچیئرمین، بورڈ آف ڈائریکٹرز – BAJK<br><br>\r\n\r\n<strong>مہمانانِ خصوصی اور سینئر لیڈرشپ:</strong><br>\r\nمحترمہ لبنیٰ فاروق ملک<br>\r\nچیف ایگزیکٹو آفیسر – نیباف پاکستان<br><br>\r\n\r\nجناب سید ساجد علی<br>\r\nڈائریکٹر لرننگ اینڈ ڈیولپمنٹ – نیباف پاکستان<br><br>\r\n\r\nمحترمہ رائلہ جاوید<br>\r\nڈویژنل ہیڈ، HRMD – بینک آف آزاد جموں و کشمیر<br><br>\r\n\r\n<hr>\r\n\r\n✅ اس تقریب میں پروگرام کی کامیاب تکمیل کا جشن منایا گیا اور BAJK کے ٹیلرز کی محنت اور لگن کو سراہا گیا، جو بہتر سروس ایکسی لینس اور پیشہ ورانہ ترقی کے سفر کو بھرپور طریقے سے جاری رکھے ہوئے ہیں۔<br><br>\r\n\r\n</div>', 'NIBAF Pakistan successfully held the Closing Ceremony and Certificate Distribution for the Teller Certification Program – Batch 4, conducted for the Bank of Azad Jammu & Kashmir.\r\n\r\n📅 Date: 08–...', 'news-images/Jpkn7IpWb6PzTo1uMKN7Axpo8JCS6xoVdfZ7R993.jpg', '2025-11-11', 0, 'general', 'closing-ceremony-certificate-distribution-teller-certification-program-batch-4', 1, '2025-12-03 06:00:07', '2026-09-01 11:57:20');
INSERT INTO `news_announcements` (`id`, `title`, `content`, `excerpt`, `image`, `published_date`, `is_featured`, `category`, `slug`, `is_published`, `created_at`, `updated_at`) VALUES
(35, 'BAJK Launches Advances Campaign 2025 With Special Focus on Advance Salary Scheme and Gold Loan', 'Muzaffarabad: The Bank of Azad Jammu & Kashmir (BAJK) on Monday has officially launched its Advances Campaign 2025, placing special emphasis on the Advance Salary Scheme and Gold Loan products. These facilities are being offered at the lowest mark-up rates in the market, making BAJK one of the most competitive financial institutions in the region.\r\n\r\n<br>\r\n\r\nThe program was hosted by the Commercial and Retail Banking Division, while the campaign was formally launched by Mr. Shahid Shahzad Mir, President/CEO of the Bank of AJK.\r\n\r\n<br>\r\n\r\nSpeaking on the occasion, the President/CEO highlighted that BAJK is fully committed to playing its vital role in the socio-economic development of Azad Jammu & Kashmir. He added that the bank’s customer-centric financial products are designed to support government employees, businesspersons, and the general public by providing affordable and accessible financing solutions.\r\n\r\n<br>\r\n\r\nMr. Mir further emphasized that the Advance Salary Scheme and Gold Loan facility will help thousands of customers meet their personal and business needs with convenience, transparency, and trust — values that BAJK consistently upholds.\r\n\r\n<br>\r\n\r\nWith the launch of Advances Campaign 2025, BAJK continues to strengthen its position as a leading financial institution dedicated to economic empowerment and sustainable financial growth across the state.\r\n\r\n<div dir=\"rtl\" style=\"text-align: right;\"> بینک آف آزاد جموں و کشمیر نے ’’ایڈوانسز کیمپین 2025‘‘ کا آغاز — ایڈوانس سیلری اسکیم اور گولڈ لون پر خصوصی توجہ\r\n\r\nمظفرآباد: بینک آف آزاد جموں و کشمیر (BAJK) نے پیر کے روز باضابطہ طور پر ایڈوانسز کیمپین 2025 کا آغاز کر دیا، جس میں ایڈوانس سیلری اسکیم اور گولڈ لون پر خصوصی توجہ دی گئی۔ یہ سہولیات مارکیٹ کے کم ترین مارک اپ ریٹس پر فراہم کی جا رہی ہیں، جس سے BAJK خطے کے سب سے مسابقتی مالیاتی اداروں میں شامل ہو گیا ہے۔\r\n\r\n<br>\r\n\r\nیہ پروگرام کمرشل اینڈ ریٹیل بینکنگ ڈویژن کی میزبانی میں منعقد ہوا، جبکہ مہم کا باقاعدہ آغاز جناب شاہد شہزاد میر، صدر/CEO بینک آف AJK نے کیا۔\r\n\r\n<br>\r\n\r\nصدر/CEO نے اپنے خطاب میں کہا کہ BAJK آزاد جموں و کشمیر کی سماجی و معاشی ترقی میں اپنا اہم کردار ادا کرنے کے لیے مکمل طور پر پرعزم ہے۔ انہوں نے کہا کہ بینک کی کسٹمر سینٹرک مالیاتی اسکیمیں سرکاری ملازمین، کاروباری طبقے اور عام عوام کے لیے سستی اور آسان مالی سہولیات فراہم کرتی ہیں۔\r\n\r\n<br>\r\n\r\nجناب میر نے مزید کہا کہ ایڈوانس سیلری اسکیم اور گولڈ لون سہولت ہزاروں صارفین کو ان کی ذاتی اور کاروباری ضروریات آسانی، شفافیت اور اعتماد کے ساتھ پورا کرنے میں مدد فراہم کرے گی — جو BAJK کی مستقل اقدار ہیں۔\r\n\r\n<br>\r\n\r\nایڈوانسز کیمپین 2025 کے آغاز کے ساتھ، BAJK ریاست بھر میں اقتصادی بااختیاری اور پائیدار مالی ترقی کے لیے اپنے کردار کو مزید مضبوط بناتا ہے۔\r\n\r\n</div>', 'Muzaffarabad: The Bank of Azad Jammu & Kashmir (BAJK) on Monday has officially launched its Advances Campaign 2025, placing special emphasis on the Advance Salary Scheme and Gold Loan products. These ...', 'news-images/3CFzPfM8B4bKAFvnai7Mjc0rJGnFmFShkxI6jTpz.jpg', '2025-11-17', 0, 'general', 'bajk-launches-advances-campaign-2025-with-special-focus-on-advance-salary-scheme-and-gold-loan', 1, '2025-12-03 06:16:50', '2026-09-01 11:57:32'),
(36, 'BAJK Holds Performance Review Meeting 2025 — Business Plan 2026 Discussed', 'Islamabad: Under the vision of the <strong>Prime Minister of Azad Jammu & Kashmir, Chaudhry Anwar Haq</strong>, for <strong>Youth Empowerment</strong>, the <strong>Bank of Azad Jammu & Kashmir (BAJK)</strong> and the <strong>Azad Kashmir Small Industries Corporation (AKSIC)</strong> have signed a <strong>Memorandum of Understanding (MoU)</strong> for the implementation of the <strong>Prime Minister’s Youth Loan Program</strong>.<br><br>\n\nThe signing ceremony was held on Thursday at the <strong>BAJK Camp Office</strong>. It was attended by <strong>Minister for Finance & Cooperatives and Chairman of the Bank, Mr. Khan Abdul Majid Khan</strong>; <strong>Minister for Small Industries & TATA, Prof. Taqdees Gilani</strong>; <strong>Secretary Finance, Mr. Islam Zeb</strong>; <strong>Secretary Industries, Mr. Chaudhry Abdul Rehman</strong>; <strong>President/CEO BAJK, Mr. Shahid Shahzad Mir</strong>; <strong>Managing Director Small Industries, Mr. Muhammad Zeeshan</strong>; <strong>Director Small Industries, Mr. Abdul Khaliq Abbasi</strong>; <strong>DH CMD, Mr. Muhammad Imtiaz Shaheen</strong>; along with other distinguished personalities.<br><br>\n\n<hr> **Key Highlights:**<br> • Under this scheme, young people will be provided <strong>interest-free loans (zero markup)</strong> ranging from <strong>PKR 100,000 to PKR 2,000,000</strong>. These loans will be given for <strong>new and startup businesses</strong>.<br> • The primary objective of the scheme is to provide interest-free loans to the youth of the region, enabling them to <strong>develop entrepreneurial skills</strong>, <strong>create new employment opportunities</strong>, <strong>reduce poverty</strong>, and <strong>promote economic activities in the private sector</strong>.<br> • As per the agreement, both institutions will assist young people across <strong>all ten districts of Azad Kashmir</strong> in establishing and promoting small businesses.<br> • After the formal signing of the MoU, the scheme will become fully operational.<br> • The <strong>Secretary Industries of AKSIC</strong> stated: “This step is a significant milestone towards turning the dreams of young people into reality.”<br> • The <strong>President of the Bank</strong> said: “The entire team of the Bank is determined to make this scheme a success. We will provide not only financial but also technical support to young entrepreneurs.”<br> • Through this scheme, a new ray of hope is expected to shine for <strong>thousands of young people in Azad Kashmir</strong>, paving the way for a brighter future.<br><br> <hr> <div dir=\"rtl\" style=\"text-align: right;\"> <strong>BAJK نے وزیراعظم یوتھ لون پروگرام کے ذریعے آزاد کشمیر میں اسٹارٹ اپس کی حمایت شروع کی</strong><br><br>\n\nاسلام آباد: <strong>وزیراعظم آزاد جموں و کشمیر، چوہدری انور الحق</strong> کے وژن <strong>یوتھ ایمپاورمنٹ</strong> کے تحت، <strong>بینک آف آزاد جموں و کشمیر (BAJK)</strong> اور <strong>آزاد کشمیر اسمال انڈسٹریز کارپوریشن (AKSIC)</strong> نے <strong>وزیراعظم یوتھ لون پروگرام</strong> کے نفاذ کے لیے <strong>مفاہمتی یادداشت (MoU)</strong> پر دستخط کیے۔<br><br>\n\nدستخطی تقریب جمعرات کو <strong>BAJK کیمپ آفس</strong> میں منعقد ہوئی۔ اس میں <strong>وزیر خزانہ و کواپریٹوز و چئیرمین بینک، جناب خان عبدالماجد خان</strong>؛ <strong>وزیر سمال انڈسٹریز و ٹاٹا، پروفیسر تقدیس گیلانی</strong>؛ <strong>سیکرٹری خزانہ، جناب اسلام زیب</strong>؛ <strong>سیکرٹری انڈسٹریز، جناب چوہدری عبدالرحمن</strong>؛ <strong>صدر/سی ای او BAJK، جناب شاہد شہزاد میر</strong>؛ <strong>منیجنگ ڈائریکٹر اسمال انڈسٹریز، جناب محمد زیشان</strong>؛ <strong>ڈائریکٹر اسمال انڈسٹریز، جناب عبدالخالق عباسی</strong>؛ <strong>ڈی ایچ CMD، جناب محمد امتیاز شاہین</strong> اور دیگر معزز شخصیات نے شرکت کی۔<br><br>\n\n<hr> <strong>اہم نکات:</strong><br> • اس سکیم کے تحت نوجوانوں کو <strong>بلا سود قرضے (زیرو مارک اپ)</strong> فراہم کیے جائیں گے، جو <strong>1 لاکھ سے 20 لاکھ روپے</strong> تک ہوں گے اور <strong>نئے اور اسٹارٹ اپ کاروبار</strong> کے لیے دیے جائیں گے۔<br> • اس سکیم کا مقصد نوجوانوں کو بلاسود قرضے دے کر ان میں <strong>کاروباری مہارتیں پیدا کرنا</strong>، <strong>روزگار کے نئے مواقع فراہم کرنا</strong>، <strong>غربت میں کمی لانا</strong>، اور <strong>نجی شعبے میں معاشی سرگرمیوں کو فروغ دینا</strong> ہے۔<br> • معاہدے کے مطابق، دونوں ادارے آزاد کشمیر کے <strong>تمام دس اضلاع</strong> میں نوجوانوں کو چھوٹے کاروبار قائم کرنے اور ان کی ترقی میں مدد فراہم کریں گے۔<br> • MoU پر دستخط کے بعد یہ سکیم مکمل طور پر نافذ العمل ہو جائے گی۔<br> • <strong>سیکرٹری انڈسٹریز AKSIC</strong> نے کہا: \"یہ قدم نوجوانوں کے خوابوں کو حقیقت میں بدلنے کی جانب ایک اہم پیش رفت ہے۔\"<br> • <strong>صدر بینک</strong> نے کہا: \"بینک کی پوری ٹیم اس سکیم کو کامیاب بنانے کے لیے پرعزم ہے۔ ہم نوجوان کاروباریوں کو مالی اور تکنیکی معاونت فراہم کریں گے۔\"<br> • اس سکیم کے ذریعے آزاد کشمیر کے <strong>ہزاروں نوجوانوں</strong> کے لیے روشن مستقبل کی امید پیدا ہوگی۔<br> </div>', 'Islamabad: Under the vision of the Prime Minister of Azad Jammu & Kashmir, Chaudhry Anwar Haq, for Youth Empowerment, the Bank of Azad Jammu & Kashmir (BAJK) and the Azad Kashmir Small Industries Corp...', 'news-images/JCdwiOOPdmN9rk0cGsC2ZGpkgDvQzvJPF7R6uo1U.jpg', '2025-11-17', 0, 'general', 'bajk-holds-performance-review-meeting-2025-business-plan-2026-discussed', 1, '2025-12-03 06:31:50', '2026-09-01 11:57:45'),
(37, 'BAJK Hosts Farewell and Appreciation Ceremony for Former Chairman', 'Islamabad – December 08, 2025:\r\nThe <strong>Bank of Azad Jammu & Kashmir (BAJK)</strong> organized a graceful <strong>farewell and appreciation ceremony</strong> in honor of the <strong>former Chairman, Mr. Khan Abdul Majid Khan</strong>, acknowledging his significant contributions to the Bank’s progress and stability.<br><br>\r\n\r\nDuring the ceremony, the <strong>newly appointed Chairman of BAJK and Minister for Finance & Inland Revenue, Mr. Ch. Qasim Majeed</strong>, paid glowing tribute to the former Chairman for his visionary leadership and dedicated service. He praised the efforts of <strong>Mr. Khan Abdul Majid Khan</strong> in laying a strong foundation for BAJK’s transformation and growth.<br><br>\r\n\r\nIn recognition of his valuable services, <strong>Chairman Ch. Qasim Majeed</strong> presented a <strong>shield of appreciation</strong> to the former Chairman. <strong>Senior Board members</strong> and the <strong>President & CEO, Mr. Shahid Shahzad Mir</strong>, were also present on the occasion.<br><br>\r\n\r\n<strong>Chairman Ch. Qasim Majeed</strong> reaffirmed that the Bank will continue its journey of progress with the same dedication, adding that the new leadership is committed to taking BAJK to new heights through accelerated strategic initiatives and enhanced service quality.<br><br>\r\n\r\nThe event concluded with heartfelt acknowledgments and warm wishes for the former Chairman’s future endeavors, while the Board expressed confidence in continuing BAJK’s mission of innovation and financial excellence.<br><br>\r\n\r\n<hr> <div dir=\"rtl\" style=\"text-align: right;\"> <strong>بینک آف آزاد جموں و کشمیر (BAJK) نے سابق چیئرمین کے اعزاز میں الوداعی و تعریفی تقریب کا انعقاد کیا</strong><br><br>\r\n\r\nبینک آف آزاد جموں و کشمیر (BAJK) نے سابق چیئرمین <strong>جناب خان عبدالماجد خان</strong> کے اعزاز میں ایک خوبصورت الوداعی اور تعریفی تقریب کا اہتمام کیا، جس میں بینک کی ترقی اور استحکام کے لیے ان کی نمایاں خدمات کو خراجِ تحسین پیش کیا گیا۔<br><br>\r\n\r\nتقریب کے دوران نئے چیئرمین اور <strong>وزیرِ خزانہ و ان لینڈ ریونیو آزاد جموں و کشمیر، چوہدری قاسم مجید</strong> نے سابق چیئرمین کو شاندار الفاظ میں خراجِ عقیدت پیش کیا۔ انہوں نے جناب خان عبدالماجد خان کی وژنری قیادت اور بھرپور خدمات کی تعریف کرتے ہوئے کہا کہ انہوں نے BAJK کی تبدیلی اور ترقی کے لیے ایک مضبوط بنیاد فراہم کی۔<br><br>\r\n\r\nان کی خدمات کے اعتراف میں <strong>چیئرمین چوہدری قاسم مجید</strong> نے سابق چیئرمین کو <strong>تعریفی شیلڈ</strong> پیش کی۔ اس موقع پر <strong>سینئر بورڈ ممبران</strong> اور <strong>صدر و سی ای او جناب شاہد شہزاد میر</strong> بھی موجود تھے۔<br><br>\r\n\r\nچیئرمین چوہدری قاسم مجید نے اس عزم کا اظہار کیا کہ بینک اپنی ترقی کے سفر کو اسی لگن اور جذبے کے ساتھ جاری رکھے گا۔ انہوں نے کہا کہ نئی قیادت تیز رفتار اسٹریٹجک اقدامات اور بہتر سروس کوالٹی کے ذریعے BAJK کو نئی بلندیوں تک پہنچانے کے لیے پرعزم ہے۔<br><br>\r\n\r\nتقریب کا اختتام گرمجوشانہ شکریوں اور سابق چیئرمین کے لیے نیک تمناؤں کے ساتھ ہوا، جبکہ بورڈ نے اعتماد ظاہر کیا کہ بینک جدت اور مالیاتی بہترین خدمات کے مشن کو مزید مؤثر انداز میں جاری رکھے گا۔\r\n\r\n</div>', 'Islamabad – December 08, 2025:\r\nThe Bank of Azad Jammu & Kashmir (BAJK) organized a graceful farewell and appreciation ceremony in honor of the former Chairman, Mr. Khan Abdul Majid Khan, acknowledg...', 'news-images/RAk6hx673sSpKiWKYpBp0mJMrUmazC6T7LhjEAy4.jpg', '2025-12-08', 0, 'general', 'bajk-hosts-farewell-and-appreciation-ceremony-for-former-chairman', 1, '2025-12-16 05:36:01', '2026-09-01 11:58:04'),
(38, '98th Meeting of the Board of Directors of BAJK Held in Islamabad', 'Islamabad – December 08, 2025:\r\nThe <strong>98th meeting of the Board of Directors of Bank of Azad Jammu & Kashmir (BAJK)</strong> was held in <strong>Islamabad</strong> under the chairmanship of <strong>Mr. Ch. Qasim Majeed</strong>, the <strong>newly elected Minister for Finance & Inland Revenue, Government of Azad Jammu & Kashmir</strong>, and <strong>newly appointed Chairman of BAJK</strong>.<br><br>\r\n\r\n<strong>The meeting was attended by:</strong><br>\r\n• <strong>President & CEO</strong>, Mr. Shahid Shahzad Mir<br>\r\n• <strong>Secretary Finance, AJK</strong>, Mr. Islam Zaib<br>\r\n• <strong>Secretary Industries & Commerce, AJK</strong>, Ch. Abdul Rehman<br>\r\n• Mr. Mubashar Nabi<br>\r\n• Ms. Bushra Naz Malik (joined via Zoom)<br>\r\n• <strong>Company Secretary</strong>, Dr. Adnanullah Khan<br><br>\r\n\r\nThe management presented a detailed briefing to the new Chairman on the Bank’s <strong>overall performance</strong>, <strong>financial indicators</strong>, <strong>strategic initiatives</strong>, and progress toward obtaining <strong>Scheduled Bank status</strong>. Updates on <strong>digital transformation</strong>, <strong>service expansion</strong>, and <strong>operational strengthening</strong> were also shared.<br><br>\r\n\r\n<strong>Chairman Ch. Qasim Majeed</strong> expressed confidence in the Bank’s direction and emphasized his commitment to elevating BAJK to new heights. He directed the management to <strong>expedite the Scheduled Bank process</strong>, <strong>enhance operational efficiency</strong>, and <strong>accelerate modernization efforts</strong> across all banking divisions.<br><br>\r\n\r\nThe Board reiterated its commitment to <strong>sustainable growth</strong>, <strong>innovation</strong>, and <strong>service excellence</strong>, reaffirming BAJK’s mission to remain a <strong>trusted, progressive, and customer-centric financial institution</strong>.<br><br>\r\n\r\n<hr> <div dir=\"rtl\" style=\"text-align: right;\"> <strong>بینک آف آزاد جموں و کشمیر (BAJK) کے بورڈ آف ڈائریکٹرز کا 98واں اجلاس اسلام آباد میں منعقد ہوا</strong><br><br>\r\n\r\nبینک آف آزاد جموں و کشمیر (BAJK) کے بورڈ آف ڈائریکٹرز کا <strong>98واں اجلاس</strong> اسلام آباد میں <strong>وزیرِ خزانہ و ان لینڈ ریونیو حکومتِ آزاد جموں و کشمیر</strong> اور <strong>نئے چیئرمین BAJK، جناب چوہدری قاسم مجید</strong> کی زیر صدارت منعقد ہوا۔<br><br>\r\n\r\n<strong>اجلاس میں شرکت کرنے والوں میں شامل تھے:</strong><br>\r\n• <strong>صدر و سی ای او</strong>، جناب شاہد شہزاد میر<br>\r\n• <strong>سیکرٹری خزانہ، آزاد کشمیر</strong>، جناب اسلام زیب<br>\r\n• <strong>سیکرٹری صنعت و تجارت، آزاد کشمیر</strong>، چوہدری عبدالرحمن<br>\r\n• جناب مبشر نبی<br>\r\n• محترمہ بشریٰ ناز ملک (ویڈیو لنک کے ذریعے شریک)<br>\r\n• <strong>کمپنی سیکرٹری</strong>، ڈاکٹر عدنان اللہ خان<br><br>\r\n\r\nاجلاس میں نئے چیئرمین کو بینک کی <strong>مجموعی کارکردگی</strong>، <strong>مالیاتی اشاریوں</strong>، <strong>اسٹریٹجک اقدامات</strong> اور <strong>شیڈولڈ بینک کا درجہ حاصل کرنے</strong> کے عمل پر تفصیلی بریفنگ دی گئی۔ <strong>ڈیجیٹل ٹرانسفارمیشن</strong>، <strong>سروسز کے پھیلاؤ</strong> اور <strong>آپریشنل مضبوطی</strong> کے حوالے سے پیش رفت بھی پیش کی گئی۔<br><br>\r\n\r\n<strong>چیئرمین چوہدری قاسم مجید</strong> نے بینک کی سمت پر مکمل اعتماد ظاہر کرتے ہوئے اس عزم کا اظہار کیا کہ وہ BAJK کو نئی بلندیوں تک لے جانے کے لیے پرعزم ہیں۔ انہوں نے ہدایت کی کہ <strong>شیڈولڈ بینک کا عمل تیز کیا جائے</strong>، <strong>آپریشنل کارکردگی بہتر بنائی جائے</strong>، اور <strong>بینک کے تمام شعبہ جات میں جدیدیت</strong> کے عمل کو مزید تیز کیا جائے۔<br><br>\r\n\r\nبورڈ نے <strong>پائیدار ترقی</strong>، <strong>جدت</strong> اور <strong>اعلیٰ معیار کی سروسز</strong> کے عزم کو دہرایا اور اس بات کی توثیق کی کہ BAJK ایک <strong>قابلِ بھروسہ، ترقی پسند اور کسٹمر دوست مالیاتی ادارہ</strong> بننے کے مشن کو جاری رکھے گا۔\r\n\r\n</div>', 'Islamabad – December 08, 2025:\r\nThe 98th meeting of the Board of Directors of Bank of Azad Jammu & Kashmir (BAJK) was held in Islamabad under the chairmanship of Mr. Ch. Qasim Majeed, the newly elec...', 'news-images/dSSS6rLqCpOClW4fFY3xHt0hGgMj0uHyTXHj984S.jpg', '2025-12-08', 0, 'general', '98th-meeting-of-the-board-of-directors-of-bajk-held-in-islamabad', 1, '2025-12-16 05:42:48', '2026-09-01 11:58:27'),
(39, 'Chairman BAJK Ch. Qasim Majeed Launches Advances Campaign, Chairs High-Level Review Meeting, Opens Personal Account; Reaffirms Commitment to Scheduled Bank Status', 'Muzaffarabad\nThe <strong>Chairman of the Bank of Azad Jammu & Kashmir (BAJK)</strong> and <strong>Minister for Finance & Inland Revenue, Government of Azad Jammu & Kashmir</strong>, <strong>Mr. Ch. Qasim Majeed</strong>, on Tuesday <strong>formally launched the Bank’s Advances Campaign</strong>, chaired a <strong>high-level review meeting</strong> of the Commercial & Retail Banking Division, and <strong>opened his personal bank account</strong> in BAJK, reaffirming his strong confidence in the Bank and reiterating the government’s firm commitment to achieving <strong>Scheduled Bank status</strong>.<br><br>\n\nThe Chairman inaugurated the campaign by <strong>cutting the ribbon at the Bank’s Head Office in Muzaffarabad</strong>. Addressing the ceremony, he stated that the <strong>socio-economic development of Azad Jammu & Kashmir</strong> is a top priority of the government, and strengthening the Bank of Azad Jammu & Kashmir is essential to achieving this goal. He emphasized that the <strong>Advances Campaign</strong> aims to promote business activity and provide <strong>easy and affordable financing</strong> to <strong>youth, women, farmers, traders, and Small & Medium Enterprises (SMEs)</strong>.<br><br>\n\n<strong>Chairman Ch. Qasim Majeed</strong> underscored that granting <strong>Scheduled Bank status</strong> to BAJK remains one of the government’s key priorities. He highlighted that <strong>good governance, merit, discipline, transparency, and public service</strong> will be the core values guiding the Bank, while the establishment of <strong>new branches</strong> will further enhance public access to modern banking services across the region.<br><br>\n\nSubsequently, the Chairman <strong>chaired a high-level meeting</strong> at the Commercial & Retail Banking Division, where <strong>President & CEO Mr. Shahid Shahzad Mir</strong> presented a comprehensive briefing on the Bank’s <strong>financial performance, strategic objectives, and future roadmap</strong>. He informed that BAJK earned a cumulative profit of <strong>Rs. 3.420 billion from 2006 to 2022</strong>, while an additional <strong>Rs. 4.568 billion</strong> was recorded during <strong>2023 to September 2025</strong>.<br><br>\n\nThe President & CEO further shared that the Bank’s <strong>total assets have reached Rs. 58 billion</strong>, <strong>deposits Rs. 47 billion</strong>, and <strong>advances Rs. 5.381 billion</strong>. He highlighted that the <strong>Capital Adequacy Ratio (CAR)</strong> stands at <strong>47.6%</strong>, significantly higher than the <strong>State Bank of Pakistan’s requirement of 13.5%</strong>, while <strong>Non-Performing Loans (NPLs)</strong> have been reduced from <strong>11% to 4.3%</strong> due to improved governance and recovery mechanisms.<br><br>\n\nHe added that <strong>all major regulatory and operational requirements</strong> for achieving Scheduled Bank status have either been completed or are in their final stages. He expressed gratitude to the <strong>Government of Azad Jammu & Kashmir</strong>, the <strong>Prime Minister of Azad Jammu & Kashmir</strong>, and the <strong>Chairman BAJK</strong> for providing <strong>Rs. 2.9 billion as equity</strong>, enabling the Bank to achieve the required <strong>Rs. 10 billion capital base</strong>. He also shared updates on the implementation of a <strong>modern core banking system</strong> and ongoing <strong>staff capacity-building initiatives</strong>.<br><br>\n\nOn the occasion, <strong>President & CEO Mr. Shahid Shahzad Mir</strong> presented a <strong>commemorative shield</strong> to <strong>Chairman Ch. Qasim Majeed</strong> in recognition of his leadership, guidance, and continued support for the Bank’s growth and reforms.<br><br>\n\nLater, the Chairman <strong>opened his personal bank account</strong> in BAJK and urged the public to bank with the institution, stating that BAJK is progressing rapidly, strengthening public trust, and moving steadily toward becoming a <strong>leading scheduled bank</strong> in the country.<br><br>\n\nThe event was attended by <strong>all Divisional and Regional Heads</strong> of the Bank, reflecting strong institutional unity and a shared commitment to <strong>sustainable growth, stability, and service excellence</strong>.\n\n<hr> <div dir=\"rtl\" style=\"text-align: right;\"> <strong>چیئرمین بینک آف آزاد جموں و کشمیر چوہدری قاسم مجید کا بینک ایڈوانسز مہم کا افتتاح، اعلیٰ سطحی اجلاس کی صدارت اور ذاتی اکاؤنٹ کا افتتاح</strong><br><br>\n\n<strong>مظفرآباد:</strong><br>\nآزاد حکومتِ ریاست جموں و کشمیر کے <strong>وزیرِ خزانہ و ان لینڈ ریونیو</strong> اور <strong>بینک آف آزاد جموں و کشمیر (BAJK) کے چیئرمین</strong>، <strong>چوہدری قاسم مجید</strong> نے منگل کے روز <strong>بینک آف آزاد جموں و کشمیر کی ایڈوانسز مہم کا باضابطہ افتتاح</strong> کیا، <strong>کمرشل و ریٹیل بینکنگ ڈویژن</strong> کے اعلیٰ سطحی اجلاس کی صدارت کی اور <strong>بینک میں اپنا ذاتی اکاؤنٹ کھول کر</strong> ادارے پر بھرپور اعتماد کا اظہار کیا، جبکہ <strong>شیڈولڈ بینک اسٹیٹس</strong> کے حصول کے عزم کا اعادہ کیا۔<br><br>\n\nچیئرمین نے <strong>بینک کے ہیڈ آفس مظفرآباد</strong> میں ربن کاٹ کر ایڈوانسز مہم کا آغاز کیا۔ اس موقع پر خطاب کرتے ہوئے انہوں نے کہا کہ <strong>آزاد کشمیر کی سماجی و معاشی ترقی</strong> حکومت کی اولین ترجیح ہے اور اس مقصد کے لیے بینک آف آزاد جموں و کشمیر کو مضبوط بنانا ناگزیر ہے۔ انہوں نے کہا کہ اس مہم کا مقصد <strong>کاروباری سرگرمیوں کا فروغ</strong> اور <strong>نوجوانوں، خواتین، زراعت، تجارت اور ایس ایم ایز</strong> کو <strong>آسان اور سستی فنانسنگ</strong> فراہم کرنا ہے۔<br><br>\n\n<strong>چوہدری قاسم مجید</strong> نے واضح کیا کہ <strong>بینک آف آزاد جموں و کشمیر کو شیڈولڈ بینک کا درجہ دلانا</strong> حکومت کی اہم ترجیحات میں شامل ہے۔ انہوں نے کہا کہ <strong>اچھی حکمرانی، میرٹ، نظم و ضبط، شفافیت اور عوامی خدمت</strong> بینک کی بنیادی اقدار ہوں گی، جبکہ <strong>نئی برانچوں کے قیام</strong> سے عوام تک بینکاری سہولیات کی رسائی مزید بہتر بنائی جا رہی ہے۔<br><br>\n\nبعد ازاں چیئرمین نے <strong>کمرشل و ریٹیل بینکنگ ڈویژن</strong> میں اعلیٰ سطحی اجلاس کی صدارت کی، جہاں <strong>صدر و چیف ایگزیکٹو آفیسر شاہد شہزاد میر</strong> نے بینک کی <strong>مالی کارکردگی، اسٹریٹجک اہداف اور مستقبل کے لائحہ عمل</strong> پر تفصیلی بریفنگ دی۔ انہوں نے بتایا کہ بینک نے <strong>2006ء سے 2022ء تک 3.420 ارب روپے</strong> اور <strong>2023ء سے ستمبر 2025ء تک 4.568 ارب روپے</strong> منافع حاصل کیا۔<br><br>\n\nانہوں نے بتایا کہ بینک کے <strong>کل اثاثے 58 ارب روپے</strong>، <strong>ڈیپازٹس 47 ارب روپے</strong> اور <strong>ایڈوانسز 5.381 ارب روپے</strong> تک پہنچ چکے ہیں۔ <strong>کیپیٹل ایڈی کویسی ریشو 47.6 فیصد</strong> ہے، جو اسٹیٹ بینک آف پاکستان کی مقررہ حد سے کہیں زیادہ ہے، جبکہ <strong>نان پرفارمنگ لونز 11 فیصد سے کم ہو کر 4.3 فیصد</strong> رہ گئے ہیں۔<br><br>\n\nصدر بینک نے بتایا کہ <strong>شیڈولڈ بینک اسٹیٹس</strong> کے لیے تمام اہم تقاضے مکمل یا آخری مراحل میں ہیں۔ انہوں نے <strong>حکومتِ آزاد کشمیر، وزیرِ اعظم آزاد کشمیر</strong> اور <strong>چیئرمین BAJK</strong> کا شکریہ ادا کیا جنہوں نے <strong>2.9 ارب روپے بطور ایکویٹی</strong> فراہم کیے، جس سے بینک کا سرمایہ <strong>10 ارب روپے</strong> مکمل ہوا۔ انہوں نے جدید <strong>کور بینکنگ سسٹم</strong> اور <strong>عملے کی تربیت</strong> سے متعلق پیش رفت سے بھی آگاہ کیا۔<br><br>\n\nاس موقع پر <strong>صدر و چیف ایگزیکٹو آفیسر شاہد شہزاد میر</strong> نے <strong>چیئرمین چوہدری قاسم مجید</strong> کو یادگاری شیلڈ پیش کی۔<br><br>\n\nبعد ازاں چیئرمین نے بینک میں <strong>اپنا ذاتی اکاؤنٹ کھولا</strong> اور عوام سے اپیل کی کہ وہ <strong>بینک آف آزاد جموں و کشمیر</strong> پر اعتماد کریں کیونکہ یہ ادارہ تیزی سے ترقی کر رہا ہے اور عوامی اعتماد کے باعث مزید مضبوط ہو رہا ہے۔<br><br>\n\nتقریب میں بینک کے <strong>تمام ڈویژنل اور ریجنل ہیڈز</strong> نے شرکت کی، جو بینک کی <strong>مستحکم ترقی اور روشن مستقبل</strong> کے عزم کی عکاسی کرتا ہے۔\n\n</div>', 'Muzaffarabad – January 26, 2026:\r\nThe Chairman of the Bank of Azad Jammu & Kashmir (BAJK) and Minister for Finance & Inland Revenue, Government of Azad Jammu & Kashmir, Mr. Ch. Qasim Majeed, on Tues...', 'news-images/N6PVrC0ygfeOruytO3Wj5r8TW6L5SLDQQw5rzyBZ.jpg', '2025-12-17', 0, 'general', 'chairman-bajk-ch-qasim-majeed-launches-advances-campaign-chairs-high-level-review-meeting-opens-personal-account-reaffirms-commitment-to-scheduled-bank-statusstrong', 1, '2026-01-26 05:14:45', '2026-09-01 11:58:42'),
(40, 'Historic Milestone Achieved: BAJK Board Approves Share Issuance After Completion of Rs. 10 Billion Equity Requirement for Scheduled Bank Status', '<div style=\"color:black;\">Muzaffarabad – December 17, 2025:\nThe Bank of Azad Jammu & Kashmir (BAJK) achieved a historic milestone during the 95th meeting of the Board of Directors, held at the BAJK Head Office, Muzaffarabad, under the chairmanship of the Minister for Finance & Inland Revenue, Government of Azad Jammu & Kashmir, and Chairman BAJK, Mr. Ch. Qasim Majeed.\n\nThe meeting was attended by the following Board members:\n\nPresident & CEO, Mr. Shahid Shahzad Mir\n\nSecretary Finance, AJK, Mr. Islam Zaib\n\nSecretary Law, AJK, Mr. Irshad Ahmad Qureshi\n\nSecretary Industries & Commerce, AJK, Ch. Abdul Rehman\n\nMr. Mubashar Nabi, Director\n\nMs. Bushra Naz Malik, Director\n\nCompany Secretary, Dr. Adnanullah Khan\n\nDuring the meeting, the Board was informed that the Government of Azad Jammu & Kashmir has provided the remaining Rs. 2.9 billion, enabling BAJK to fulfill the minimum paid-up capital requirement of Rs. 10 billion, as mandated by the State Bank of Pakistan (SBP) for obtaining Scheduled Bank status.\n\nFollowing this development, the Board approved the issuance of shares to the Government of Azad Jammu & Kashmir, thereby formally completing the equity requirement. The Board observed that the last major hurdle in achieving Scheduled Bank status has now been successfully removed.\n\nThe Board of Directors unanimously expressed gratitude to the Government of Azad Jammu & Kashmir, with special appreciation for the Prime Minister of AJK, who accorded top priority to BAJK’s Scheduled Bank status. The Prime Minister was commended for approving the Rs. 2.9 billion equity injection during the very first cabinet meeting, reflecting strong commitment to institutional development and financial stability.\n\nChairman Ch. Qasim Majeed termed the achievement a defining milestone in the history of BAJK, stating that fulfillment of the equity requirement marks the beginning of a new era for the Bank. He emphasized that BAJK is now fully positioned to expedite the remaining regulatory processes with the State Bank of Pakistan.\n\nThe Chairman directed the management to immediately proceed with the remaining formalities required for Scheduled Bank status and to ensure continued focus on operational excellence, governance, and service expansion.\n\nThe meeting concluded with a renewed commitment to strengthen BAJK as a modern, financially sound, and nationally competitive banking institution, serving the people of Azad Jammu & Kashmir.\n</div>\n\n<hr> \n<div dir=\"rtl\" style=\"text-align: right; color: black;\">\n<strong>بینک آف آزاد جموں و کشمیر کا تاریخی سنگِ میل: شیڈول بینک اسٹیٹس کے لیے 10 ارب روپے کی ایکویٹی مکمل ہونے پر شیئرز کے اجرا کی منظوری</strong><br><br>\n\n<strong>مظفرآباد – 17 دسمبر 2025:</strong><br>\nبینک آف آزاد جموں و کشمیر (بی اے جے کے) کی تاریخ میں ایک اہم سنگِ میل اس وقت عبور ہوا جب بورڈ آف ڈائریکٹرز کے 95ویں اجلاس میں، جو بی اے جے کے ہیڈ آفس مظفرآباد میں وزیر خزانہ و ان لینڈ ریونیو حکومت آزاد جموں و کشمیر اور چیئرمین بی اے جے کے، <strong>چوہدری قاسم مجید</strong> کی صدارت میں منعقد ہوا، ایک تاریخی فیصلہ کیا گیا۔<br><br>\n\nاجلاس میں درج ذیل بورڈ ممبران نے شرکت کی:<br>\n• صدر و چیف ایگزیکٹو آفیسر، مسٹر شاہد شہزاد میر<br>\n• سیکرٹری خزانہ، آزاد کشمیر، مسٹر اسلام زیب<br>\n• سیکرٹری قانون، آزاد کشمیر، مسٹر ارشاد احمد قریشی<br>\n• سیکرٹری صنعت و تجارت، آزاد کشمیر، چوہدری عبد الرحمن<br>\n• مسٹر مبشر نبی، ڈائریکٹر<br>\n• محترمہ بشریٰ ناز ملک، ڈائریکٹر<br>\n• کمپنی سیکرٹری، ڈاکٹر عدنان اللہ خان<br><br>\n\nبورڈ کو آگاہ کیا گیا کہ حکومت آزاد جموں و کشمیر نے باقی ماندہ <strong>2.9 ارب روپے</strong> فراہم کر دیے ہیں، جس کے بعد بی اے جے کے نے اسٹیٹ بینک آف پاکستان کی جانب سے شیڈول بینک کا درجہ حاصل کرنے کے لیے مقرر کردہ کم از کم <strong>10 ارب روپے</strong> کی ادا شدہ سرمایہ (Paid-up Capital) کی شرط پوری کر لی ہے۔<br><br>\n\nاس پیش رفت کے بعد بورڈ آف ڈائریکٹرز نے حکومت آزاد جموں و کشمیر کو <strong>شیئرز کے اجرا</strong> کی منظوری دے دی، جس کے ساتھ ہی ایکویٹی کی شرط باضابطہ طور پر مکمل ہو گئی۔ بورڈ نے اس امر کا مشاہدہ کیا کہ شیڈول بینک بننے کی راہ میں حائل آخری بڑی رکاوٹ بھی کامیابی سے ختم ہو چکی ہے۔<br><br>\n\nبورڈ آف ڈائریکٹرز نے متفقہ طور پر حکومت آزاد جموں و کشمیر کا شکریہ ادا کیا اور بالخصوص <strong>وزیراعظم آزاد کشمیر</strong> کی کاوشوں کو سراہا جنہوں نے بی اے جے کے کے شیڈول بینک بننے کے عمل کو اولین ترجیح دی۔ وزیراعظم آزاد کشمیر کو اس بات پر خصوصی طور پر سراہا گیا کہ انہوں نے اپنے پہلے ہی کابینہ اجلاس میں بی اے جے کے کے لیے <strong>2.9 ارب روپے کی ایکویٹی</strong> کی منظوری دی، جو ادارہ جاتی ترقی اور مالی استحکام کے لیے مضبوط عزم کی عکاسی کرتا ہے۔<br><br>\n\nچیئرمین <strong>چوہدری قاسم مجید</strong> نے اس کامیابی کو بی اے جے کے کی تاریخ کا فیصلہ کن سنگِ میل قرار دیتے ہوئے کہا کہ ایکویٹی کی شرط کی تکمیل بینک کے لیے ایک نئے دور کا آغاز ہے۔ انہوں نے اس بات پر زور دیا کہ اب بی اے جے کے اسٹیٹ بینک آف پاکستان کے ساتھ باقی ماندہ ریگولیٹری مراحل کو تیزی سے مکمل کرنے کے لیے مکمل طور پر تیار ہے۔<br><br>\n\nچیئرمین نے انتظامیہ کو ہدایت کی کہ شیڈول بینک اسٹیٹس کے حصول کے لیے درکار باقی رسمی کارروائیاں فوری طور پر مکمل کی جائیں اور ساتھ ہی آپریشنل بہتری، بہتر گورننس اور خدمات کے دائرہ کار میں توسیع پر بھرپور توجہ برقرار رکھی جائے۔<br><br>\n\nاجلاس کے اختتام پر بی اے جے کے کو ایک جدید، مالی طور پر مستحکم اور قومی سطح پر مسابقتی بینک بنانے کے عزم کا اعادہ کیا گیا جو آزاد جموں و کشمیر کے عوام کی بہترین انداز میں خدمت کرتا رہے گا۔\n\n</div>', 'Muzaffarabad – December 17, 2025:\r\nThe Bank of Azad Jammu & Kashmir (BAJK) achieved a historic milestone during the 95th meeting of the Board of Directors, held at the BAJK Head Office, Muzaffarabad...', 'news-images/knYf2j7FyiUF5E457KDBjocFxPweHyiTfN6IRByQ.jpg', '2025-12-18', 0, 'general', 'historic-milestone-achieved-bajk-board-approves-share-issuance-after-completion-of-rs-10-billion-equity-requirement-for-scheduled-bank-status', 1, '2026-01-26 05:34:11', '2026-09-01 11:59:15'),
(41, 'Message – Kashmir Solidarity Day (5 February)', '<div style=\"color:black;\">\r\n\r\n<strong>Message – Kashmir Solidarity Day (5 February)</strong><br><br>\r\n\r\n<strong>Muzaffarabad – February 5, 2026:</strong><br>\r\nKashmir Solidarity Day reminds us of our unwavering commitment to stand shoulder to shoulder with the people of Indian Illegally Occupied Jammu & Kashmir in their just struggle. This day is not only an expression of solidarity but also an opportunity to awaken the conscience of the world to take notice of the grave human rights violations being committed in the occupied territory.<br><br>\r\n\r\nOn this occasion, I pay tribute to the brave people of Kashmir who, despite decades of oppression, repression, and state violence, continue their struggle for freedom with remarkable courage and resilience. The sacrifices of the Kashmiri people will not go in vain. One day, they will exercise their right to self-determination in accordance with the resolutions of the <strong>United Nations Security Council</strong>.<br><br>\r\n\r\nThe Bank of Azad Jammu & Kashmir (BAJK) remains committed to fulfilling its responsibilities for the socio-economic development of the State. We firmly believe that a strong economy, quality education, employment opportunities, and sustainable development are essential to ensuring a dignified and secure future for the people of Kashmir.<br><br>\r\n\r\nOn Kashmir Solidarity Day, I urge the international community to play its effective role in ensuring the implementation of the relevant United Nations resolutions and in supporting the Kashmiri people in securing their fundamental right to self-determination.<br><br>\r\n\r\nIn conclusion, I pray to Almighty Allah to grant the people of Kashmir freedom, peace, and prosperity, and to keep us united and steadfast in the pursuit of this just cause.<br><br>\r\n\r\n<strong>Shahid Shahzad Mir</strong><br>\r\nPresident & Chief Executive Officer<br>\r\nThe Bank of Azad Jammu & Kashmir\r\n\r\n</div>\r\n\r\n<hr>\r\n\r\n<div dir=\"rtl\" style=\"text-align: right; color: black;\">\r\n\r\n<strong>پیغام</strong><br><br>\r\n\r\n<strong>5 فروری: یومِ یکجہتی کشمیر</strong><br><br>\r\n\r\n<strong>مظفرآباد – 5 فروری 2026:</strong><br>\r\nیومِ یکجہتی کشمیر ہمیں اس عہد کی یاد دہانی کراتا ہے کہ ہم مقبوضہ جموں و کشمیر کے عوام کی جائز جدوجہد میں ان کے شانہ بشانہ کھڑے ہیں۔ یہ دن نہ صرف اظہارِ یکجہتی کا دن ہے بلکہ عالمی ضمیر کو جھنجھوڑنے کا موقع بھی ہے کہ وہ مقبوضہ علاقے میں جاری انسانی حقوق کی سنگین پامالیوں کا نوٹس لے۔<br><br>\r\n\r\nمیں مقبوضہ کشمیر کے بہادر عوام کو خراجِ تحسین پیش کرتا ہوں جو کئی دہائیوں سے ظلم، جبر اور ریاستی تشدد کے باوجود حوصلے اور ثابت قدمی کے ساتھ آزادی کی جدوجہد جاری رکھے ہوئے ہیں۔ کشمیری عوام کی قربانیاں رائیگاں نہیں جائیں گی اور وہ اقوامِ متحدہ کی سلامتی کونسل کی قراردادوں کے مطابق اپنے حقِ خودارادیت کا استعمال ضرور کریں گے۔<br><br>\r\n\r\nبینک آف آزاد جموں و کشمیر ریاست کی سماجی و معاشی ترقی کے لیے اپنی ذمہ داریاں پوری دلجمعی سے ادا کر رہا ہے۔ ہمارا یقین ہے کہ مضبوط معیشت، معیاری تعلیم، روزگار کے مواقع اور پائیدار ترقی ہی کشمیری عوام کو باوقار اور محفوظ مستقبل فراہم کر سکتے ہیں۔<br><br>\r\n\r\nیومِ یکجہتی کشمیر کے موقع پر میں عالمی برادری سے اپیل کرتا ہوں کہ وہ اقوامِ متحدہ کی متعلقہ قراردادوں پر عمل درآمد کو یقینی بنائے اور کشمیری عوام کو ان کا بنیادی حقِ خودارادیت دلانے میں مؤثر کردار ادا کرے۔<br><br>\r\n\r\nآخر میں، میں اللہ تعالیٰ سے دعاگو ہوں کہ وہ کشمیری عوام کو آزادی، امن اور خوشحالی نصیب فرمائے اور ہمیں اس جائز مقصد کے حصول کے لیے متحد اور ثابت قدم رکھے۔<br><br>\r\n\r\n<strong>شاہد شہزاد میر</strong><br>\r\nصدر و چیف ایگزیکٹو آفیسر<br>\r\nبینک آف آزاد جموں و کشمیر\r\n\r\n</div>', 'Message – Kashmir Solidarity Day (5 February)\r\n\r\nMuzaffarabad – February 5, 2026:\r\nKashmir Solidarity Day reminds us of our unwavering commitment to stand shoulder to shoulder with the people ...', 'news-images/IQ70MCTGCZIAQjBrjZKhw7W8kcY2i69xhrlR7uPW.jpg', '2026-02-05', 0, 'general', 'message-kashmir-solidarity-day-5-february', 1, '2026-02-17 05:25:44', '2026-09-01 11:59:34'),
(42, 'Former BAJK Divisional Head Zamurrad Hussain Laid to Rest in Bhimber, AJK', 'Former Divisional Head of the <strong>Bank of Azad Jammu & Kashmir (BAJK)</strong>, Mr. Zamurrad Hussain, has passed away.<br><br>\r\n\r\n<hr>\r\n\r\n<strong>Namaz-e-Janaza & Attendance:</strong><br>\r\nHis Namaz-e-Janaza was offered in Bhimber, where President/CEO Shahid Shahzad Mir, along with senior executives and officers of BAJK, attended to pay their respects.<br><br>\r\n\r\n<hr>\r\n\r\nBAJK paid rich tribute to his dedicated services, professionalism, and contributions to the institution. His legacy of commitment and integrity will be remembered by colleagues and the community alike.<br><br>\r\n\r\nMay his soul rest in peace.<br><br>\r\n\r\n<hr>\r\n\r\n<div dir=\"rtl\" style=\"text-align: right; line-height: 1.8;\">\r\n\r\n<strong>سابق ڈویژنل ہیڈ BAJK، زمرد حسین بھمبر، آزاد جموں و کشمیر میں سپردِ خاک</strong><br><br>\r\n\r\nبینک آف آزاد جموں و کشمیر (BAJK) کے سابق ڈویژنل ہیڈ، جناب زمرد حسین انتقال کر گئے۔<br><br>\r\n\r\n<hr>\r\n\r\n<strong>نمازِ جنازہ اور شرکت:</strong><br>\r\nان کی نمازِ جنازہ بھمبر میں ادا کی گئی، جس میں صدر/سی ای او شاہد شہزاد میر، ساتھ ہی BAJK کے سینئر ایگزیکٹوز اور افسران نے شرکت کر کے مرحوم کو خراجِ عقیدت پیش کیا۔<br><br>\r\n\r\n<hr>\r\n\r\nBAJK کی جانب سے مرحوم کی محنت، پیشہ ورانہ مہارت اور ادارے کے لیے قیمتی خدمات کو خراجِ تحسین پیش کیا گیا۔ ان کی دیانت داری اور لگن کی میراث کو ساتھیوں اور کمیونٹی کی جانب سے ہمیشہ یاد رکھا جائے گا۔<br><br>\r\n\r\nاللہ تعالیٰ مرحوم کی مغفرت فرمائے اور درجات بلند کرے۔ آمین۔<br><br>\r\n\r\n</div>', 'Former Divisional Head of the Bank of Azad Jammu & Kashmir (BAJK), Mr. Zamurrad Hussain, has passed away.\r\n\r\n\r\n\r\nNamaz-e-Janaza & Attendance:\r\nHis Namaz-e-Janaza was offered in Bhimber, where Presiden...', 'news-images/fYHFcnJMml9UikJosvelqw8GnBibQ5Kg1Th53HSG.jpg', '2026-02-18', 0, 'general', 'former-bajk-divisional-head-zamurrad-hussain-laid-to-rest-in-bhimber-ajk', 1, '2026-02-18 07:36:20', '2026-09-01 11:59:50'),
(43, 'BAJK Sharda Branch: A Key Financial Hub in Neelum Valley, AJK', 'A beautiful view of Sharda Branch, Neelam Valley AJK\n\n\n<strong>Overview:</strong><br>\nThe Bank of Azad Jammu and Kashmir – Sharda Branch stands as a vital financial hub in the breathtaking region of Neelum Valley, serving both the local community and the growing number of tourists visiting this scenic destination. Located near the historic town of Sharda, the branch plays a key role in promoting financial inclusion and supporting economic activity in one of the most picturesque yet remote areas of Azad Jammu and Kashmir.<br><br>\n\n\n<strong>Services & Role:</strong><br>\nThe Sharda Branch offers a comprehensive range of modern banking services, including deposit accounts, remittance facilities, utility bill payments, and financing options tailored to individuals, small businesses, and the tourism sector. During peak tourist seasons, the branch experiences increased activity, facilitating smooth financial transactions for visitors exploring landmarks such as the ancient Sharda and surrounding natural attractions.<br><br>\n\n\n<strong>Community Contribution:</strong><br>\nBeyond routine banking, the branch reflects the Bank’s commitment to community development. It actively contributes to local economic growth by enabling small entrepreneurs, supporting traders, and encouraging savings habits among residents. The branch staff is known for its professionalism and customer-friendly approach, ensuring that even in a geographically challenging terrain, customers receive efficient and reliable services.<br><br>\n\n\nIn essence, the BAJK Sharda Branch is more than just a financial institution—it is a pillar of stability and progress in Neelum Valley, bridging banking with the needs of a vibrant and resilient community.<br><br>\n\n\n<div dir=\"rtl\" style=\"text-align: right; line-height: 1.8;\">\n\n<strong>شاردہ برانچ، وادی نیلم، آزاد جموں و کشمیر کا ایک خوبصورت منظر</strong><br><br>\n\n\n\n<strong>تعارف:</strong><br>\nبینک آف آزاد جموں و کشمیر کی شاردہ برانچ دلکش وادی نیلم کے علاقے میں ایک اہم مالیاتی مرکز کے طور پر قائم ہے، جو مقامی آبادی کے ساتھ ساتھ اس خوبصورت سیاحتی مقام پر آنے والے سیاحوں کی بڑھتی ہوئی تعداد کو خدمات فراہم کر رہی ہے۔ تاریخی قصبہ شاردہ کے قریب واقع یہ برانچ مالی شمولیت کے فروغ اور آزاد جموں و کشمیر کے خوبصورت مگر دور دراز علاقوں میں معاشی سرگرمیوں کی حمایت میں اہم کردار ادا کر رہی ہے۔<br><br>\n\n\n<strong>خدمات اور کردار:</strong><br>\nشاردہ برانچ جدید بینکاری خدمات کی مکمل سہولیات فراہم کرتی ہے، جن میں ڈپازٹ اکاؤنٹس، ترسیلاتِ زر، یوٹیلیٹی بلوں کی ادائیگی، اور افراد، چھوٹے کاروباروں اور سیاحت کے شعبے کے لیے موزوں فنانسنگ آپشنز شامل ہیں۔ سیاحتی موسم کے عروج کے دوران برانچ میں سرگرمیوں میں اضافہ ہو جاتا ہے، جہاں یہ قدیم شاردہ اور اردگرد کے قدرتی مقامات کی سیر کرنے والے سیاحوں کے لیے مالی لین دین کو آسان بناتی ہے۔<br><br>\n\n\n\n<strong>کمیونٹی میں کردار:</strong><br>\nروایتی بینکاری سے بڑھ کر، یہ برانچ بینک کے کمیونٹی ڈویلپمنٹ کے عزم کی عکاسی کرتی ہے۔ یہ مقامی معیشت کی ترقی میں فعال کردار ادا کرتی ہے، چھوٹے کاروباری افراد کو سہولت فراہم کرتی ہے، تاجروں کی معاونت کرتی ہے اور مقامی افراد میں بچت کے رجحان کو فروغ دیتی ہے۔ برانچ کا عملہ اپنی پیشہ ورانہ مہارت اور صارف دوست رویے کے لیے مشہور ہے، جو مشکل جغرافیائی حالات کے باوجود صارفین کو مؤثر اور قابلِ اعتماد خدمات فراہم کرتا ہے۔<br><br>\n\n\n\nخلاصہ یہ کہ BAJK کی شاردہ برانچ صرف ایک مالیاتی ادارہ نہیں بلکہ وادی نیلم میں استحکام اور ترقی کی علامت ہے، جو بینکاری کو ایک متحرک اور باہمت کمیونٹی کی ضروریات کے ساتھ ہم آہنگ کرتی ہے۔<br><br>\n\n</div>', 'A beautiful view of Sharda Branch, Neelam Valley AJK\r\n\r\n  \r\n\r\nOverview:\r\nThe Bank of Azad Jammu and Kashmir – Sharda Branch stands as a vital financial hub in the breathtaking region of Neelum Valle...', 'news-images/9oxxhA7d9DNoNxA7hWOexhr19uIFcUQMUssOHlUd.jpg', '2026-04-14', 0, 'banking', 'bajk-sharda-branch-a-key-financial-hub-in-neelum-valley-ajk', 1, '2026-04-24 06:19:57', '2026-09-01 12:00:04'),
(44, 'Bank of Azad Jammu & Kashmir Completes Scrutiny of 34,000 Applications Under Interest-Free Loan Scheme', '<div class=\"press-release\">\r\n    <h2>Muzaffarabad</h2>\r\n\r\n    <h1>Bank of Azad Jammu &amp; Kashmir Completes Scrutiny of 34,000 Applications Under Interest-Free Loan Scheme</h1>\r\n\r\n    <p>\r\n        The <strong>Bank of Azad Jammu &amp; Kashmir (BAJK)</strong> has completed the scrutiny process of \r\n        <strong>34,000 applications</strong> submitted under the Government of Azad Jammu &amp; Kashmir’s \r\n        interest-free loan scheme aimed at providing loans to the public at their doorstep.\r\n    </p>\r\n\r\n    <p>\r\n        The application forms/files have been provided to the Bank of Azad Jammu &amp; Kashmir’s \r\n        <strong>92 branches across the state</strong>. Applicants are advised to contact their concerned \r\n        branch and complete the necessary requirements for obtaining the loan.\r\n    </p>\r\n\r\n    <p>\r\n        A special cell has also been established at the Bank’s Head Office under the supervision of the \r\n        <strong>Credit Management Division (CMD)</strong> to facilitate the process.\r\n    </p>\r\n\r\n    <p>\r\n        According to a Bank spokesperson, the interest-free loan scheme is being implemented through the \r\n        <strong>Azad Kashmir Small Industries Corporation (AKSIC)</strong>. As a facilitating financial \r\n        institution, the Bank has completed the scrutiny process to ensure the opening of accounts and \r\n        disbursement of funds in accordance with government directives.\r\n    </p>\r\n\r\n    <p>\r\n        The Small Industries Corporation provided <strong>34,000 application forms</strong> to the Bank in \r\n        phases by <strong>20th Ramadan</strong>. Immediately upon receipt of the forms, the Bank initiated \r\n        the scrutiny process.\r\n    </p>\r\n\r\n    <p>\r\n        Bank staff carried out the process with utmost dedication, attention to detail, and diligence, \r\n        ensuring the accuracy of the entries. After completion of the scrutiny, the files were promptly \r\n        delivered to the concerned branches so that the public would not face unnecessary delays or difficulties.\r\n    </p>\r\n\r\n    <p>\r\n        For the convenience of applicants, the Bank will ensure the \r\n        <strong>timely disbursement of loans through the concerned branches</strong>, enabling people to \r\n        access the facility at their doorstep.\r\n    </p>\r\n\r\n    <p>\r\n        The Bank of Azad Jammu &amp; Kashmir has reiterated its commitment to \r\n        <strong>transparency, integrity, and strict implementation of government policies</strong>.\r\n    </p>\r\n\r\n    <h3>For Further Guidance</h3>\r\n\r\n    <p>\r\n        For further guidance, officers of the special cell established at the Head Office will be available \r\n        during office hours at the following telephone numbers:\r\n    </p>\r\n\r\n    <ul>\r\n        <li><strong>Muzaffarabad Head Office – CMD:</strong> 05822-923149</li>\r\n        <li><strong>Muzaffarabad Head Office – CRBD:</strong> 05822-923265</li>\r\n        <li><strong>Muzaffarabad Region:</strong> 05822-923226</li>\r\n        <li><strong>Mirpur Region:</strong> 05827-921407</li>\r\n        <li><strong>Rawalakot Region:</strong> 05824-920061</li>\r\n        <li><strong>Kotli Region:</strong> 05826-920822</li>\r\n    </ul>\r\n</div>\r\n<div class=\"press-release\" dir=\"rtl\" lang=\"ur\">\r\n\r\n    <h2>مظفر آباد</h2>\r\n\r\n    <p>\r\n        بینک آف آزاد جموں و کشمیر نے آزاد حکومت ریاست جموں و کشمیر کی بلا سود قرض اسکیم کے تحت \r\n        عوام کو ان کی دہلیز پر قرضہ جات کی فراہمی کے لئے <strong>34 ہزار درخواستوں</strong> کی \r\n        سکروٹنی کا عمل مکمل کر لیا ہے۔ یہ درخواست فارم/فائلیں بینک آف آزاد جموں و کشمیر کی \r\n        ریاست بھر میں <strong>92 برانچوں</strong> کو فراہم کر دی گئی ہیں۔\r\n    </p>\r\n\r\n    <p>\r\n        درخواست دہندگان متعلقہ برانچ سے رابطہ کریں اور قرضہ جات کے حصول کے لئے درکار ضروری \r\n        لوازمات مکمل کریں۔ بینک نے ہیڈ آفس میں کریڈٹ منیجمنٹ ڈویژن کی زیر نگرانی خصوصی سیل \r\n        قائم کر دیا ہے۔\r\n    </p>\r\n\r\n    <p>\r\n        بینک ترجمان کے مطابق بلا سود قرض اسکیم پر آزاد کشمیر سمال انڈسٹریز کارپوریشن \r\n        <strong>(AKSIC)</strong> کے ذریعے عملدرآمد کیا جا رہا ہے۔ بینک نے سہولت کار مالیاتی \r\n        ادارے کے طور پر اکاؤنٹس کے اجراء اور رقوم کی ادائیگی حکومتی ہدایات کے مطابق انجام دینے \r\n        کے لئے سکروٹنی کا عمل مکمل کیا۔\r\n    </p>\r\n\r\n    <p>\r\n        سمال انڈسٹریز کارپوریشن نے <strong>34 ہزار درخواست فارم</strong> 20 رمضان المبارک تک \r\n        بینک کو مرحلہ وار فراہم کئے تھے۔ فارم موصول ہوتے ہی فوری سکروٹنی کا عمل شروع کیا گیا۔\r\n    </p>\r\n\r\n    <p>\r\n        بینک عملے نے انتہائی لگن، باریک بینی اور جانفشانی سے درست اندراج پر توجہ دی اور \r\n        درخواستوں کی سکروٹنی مکمل کر کے متعلقہ برانچوں میں فائلیں پہنچا دی گئیں تاکہ عوام \r\n        کسی تاخیر یا مشکلات سے دوچار نہ ہوں۔\r\n    </p>\r\n\r\n    <p>\r\n        عوام کی سہولت کے لئے متعلقہ برانچوں میں ہی قرضہ جات کی بلاتاخیر فراہمی یقینی بنائی \r\n        جائے گی تاکہ عوام کو ان کی دہلیز پر قرضہ جات دستیاب ہوں۔\r\n    </p>\r\n\r\n    <p>\r\n        بینک آف آزاد جموں و کشمیر نے <strong>شفافیت، دیانت داری اور حکومتی پالیسی پر من و عن \r\n        عملدرآمد</strong> کے عزم کا اعادہ کیا ہے۔\r\n    </p>\r\n\r\n    <h3>مزید رہنمائی کے لئے رابطہ نمبرات</h3>\r\n\r\n    <p>\r\n        مزید رہنمائی کے لئے ہیڈ آفس کے قائم کردہ سیل کے افسران درج ذیل ٹیلی فون نمبرات پر \r\n        دفتری اوقات میں دستیاب ہوں گے:\r\n    </p>\r\n\r\n    <div class=\"contact-details\">\r\n\r\n        <p>\r\n            <strong>مظفر آباد ہیڈ آفس، سی ایم ڈی:</strong>\r\n            05822-923149\r\n        </p>\r\n\r\n        <p>\r\n            <strong>مظفر آباد ہیڈ آفس، سی آر بی ڈی:</strong>\r\n            05822-923265\r\n        </p>\r\n\r\n        <p>\r\n            <strong>مظفر آباد ریجن:</strong>\r\n            05822-923226\r\n        </p>\r\n\r\n        <p>\r\n            <strong>میرپور ریجن:</strong>\r\n            05827-921407\r\n        </p>\r\n\r\n        <p>\r\n            <strong>راولاکوٹ ریجن:</strong>\r\n            05824-920061\r\n        </p>\r\n\r\n        <p>\r\n            <strong>کوٹلی ریجن:</strong>\r\n            05826-920822\r\n        </p>\r\n\r\n    </div>\r\n\r\n</div>', 'Muzaffarabad\r\n\r\n    Bank of Azad Jammu &amp; Kashmir Completes Scrutiny of 34,000 Applications Under Interest-Free Loan Scheme\r\n\r\n    \r\n        The Bank of Azad Jammu &amp; Kashmir (BAJK) has co...', 'news-images/DN8rwnbJMvNROrmbZZfW4kQid0GhCXl4lG8bEm6i.jpg', '2026-04-20', 0, 'announcements', 'bank-of-azad-jammu-kashmir-completes-scrutiny-of-34000-applications-under-interest-free-loan-scheme', 1, '2026-09-01 08:20:23', '2026-09-01 11:54:59');
INSERT INTO `news_announcements` (`id`, `title`, `content`, `excerpt`, `image`, `published_date`, `is_featured`, `category`, `slug`, `is_published`, `created_at`, `updated_at`) VALUES
(45, 'Bank of AJK Expands Banking Network with New Branch at Gujjar Bandi', '<div class=\"press-release\" dir=\"ltr\" lang=\"en\">\r\n\r\n    <h1>Bank of AJK Expands Banking Network with New Branch at Gujjar Bandi</h1>\r\n\r\n    <p>\r\n        The <strong>Bank of AJK</strong> has expanded its banking network by inaugurating a new branch at\r\n        <strong>Gujjar Bandi</strong>, bringing banking facilities closer to thousands of residents of the\r\n        area and surrounding villages. The opening of the branch has been widely welcomed by the local\r\n        population, who termed it a major step towards financial inclusion and economic development in\r\n        the region.\r\n    </p>\r\n\r\n    <p>\r\n        The branch was formally inaugurated by <strong>Dewan Ali Khan Chughtai</strong>, Minister\r\n        Elementary and Secondary Education, Government of AJK. On the occasion, the Minister also opened\r\n        his account at the newly established branch and appreciated the efforts of the Bank management\r\n        for extending banking services to remote areas of Jhelum Valley.\r\n    </p>\r\n\r\n    <p>\r\n        A large number of local residents, traders, community representatives and notables attended the\r\n        inauguration ceremony. People from the area expressed gratitude to the Government of Azad Kashmir\r\n        and the Bank of AJK for opening the branch, stating that the facility would greatly benefit dozens\r\n        of villages by providing easy access to banking, remittance, savings and financial services at\r\n        their doorstep.\r\n    </p>\r\n\r\n    <p>\r\n        <strong>President/CEO of the Bank of AJK, Shahid Shahzad Mir</strong>, along with Divisional Heads\r\n        of CRBD and SAMD, Regional Head Muzaffarabad and other senior officials of the Bank were also\r\n        present on the occasion.\r\n    </p>\r\n\r\n    <p>\r\n        Speaking at the ceremony, the speakers highlighted the Bank’s commitment to promoting financial\r\n        access and socio-economic development across Azad Jammu and Kashmir. They said the opening of\r\n        the Gujjar Bandi branch reflects the Bank’s vision of reaching underserved areas and facilitating\r\n        the local population through quality banking services.\r\n    </p>\r\n\r\n    <p>\r\n        The inauguration ceremony concluded with people opening new accounts at the branch and appreciating\r\n        the customer-friendly initiatives of the Bank of AJK.\r\n    </p>\r\n\r\n</div>\r\n<div class=\"press-release\" dir=\"rtl\" lang=\"ur\">\r\n\r\n    <h1>\r\n        بینک آف آزاد جموں و کشمیر کا گجر بندی میں نئی برانچ کا افتتاح، بینکاری سہولیات عوام کی دہلیز تک پہنچ گئیں\r\n    </h1>\r\n\r\n    <p>\r\n        <strong>بینک آف آزاد جموں و کشمیر</strong> نے گجر بندی میں نئی برانچ کا افتتاح کرکے اپنے بینکاری\r\n        نیٹ ورک کو مزید وسعت دے دی ہے، جس کے نتیجے میں علاقے اور گردونواح کے ہزاروں مکینوں کو بینکاری\r\n        سہولیات ان کی دہلیز کے قریب دستیاب ہو گئی ہیں۔ نئی برانچ کے قیام کا مقامی آبادی نے بھرپور خیرمقدم\r\n        کیا اور اسے خطے میں مالیاتی شمولیت اور معاشی ترقی کی جانب ایک اہم قدم قرار دیا۔\r\n    </p>\r\n\r\n    <p>\r\n        نئی برانچ کا باقاعدہ افتتاح <strong>وزیر ابتدائی و ثانوی تعلیم حکومت آزاد کشمیر،\r\n        دیوان علی خان چغتائی</strong> نے کیا۔ اس موقع پر وزیر موصوف نے نئی قائم ہونے والی برانچ میں\r\n        اپنا اکاؤنٹ بھی کھولا اور وادی جہلم کے دور دراز علاقوں تک بینکاری خدمات کی فراہمی کے لیے\r\n        بینک انتظامیہ کی کاوشوں کو سراہا۔\r\n    </p>\r\n\r\n    <p>\r\n        افتتاحی تقریب میں بڑی تعداد میں مقامی افراد، تاجر برادری، کمیونٹی نمائندگان اور معززین علاقہ\r\n        نے شرکت کی۔ علاقے کے لوگوں نے حکومت آزاد کشمیر اور بینک آف آزاد جموں و کشمیر کا برانچ کے قیام\r\n        پر شکریہ ادا کرتے ہوئے کہا کہ اس سہولت سے درجنوں دیہات کے عوام مستفید ہوں گے اور انہیں بینکاری،\r\n        ترسیلات زر، بچت اور دیگر مالیاتی خدمات تک آسان رسائی اپنی دہلیز پر حاصل ہوگی۔\r\n    </p>\r\n\r\n    <p>\r\n        <strong>بینک آف آزاد جموں و کشمیر کے صدر/چیف ایگزیکٹو آفیسر شاہد شہزاد میر</strong> بھی\r\n        سی آر بی ڈی اور ایس اے ایم ڈی کے ڈویژنل ہیڈز، مظفرآباد کے ریجنل ہیڈ اور بینک کے دیگر\r\n        سینئر افسران کے ہمراہ تقریب میں موجود تھے۔\r\n    </p>\r\n\r\n    <p>\r\n        تقریب سے خطاب کرتے ہوئے مقررین نے آزاد جموں و کشمیر بھر میں مالیاتی رسائی کو فروغ دینے اور\r\n        سماجی و اقتصادی ترقی کے لیے بینک کے عزم کو اجاگر کیا۔ انہوں نے کہا کہ گجر بندی برانچ کا قیام\r\n        بینک کے اس وژن کی عکاسی کرتا ہے جس کے تحت دور دراز اور بینکاری سہولیات سے محروم علاقوں تک\r\n        رسائی حاصل کرکے مقامی آبادی کو معیاری بینکاری خدمات فراہم کی جا رہی ہیں۔\r\n    </p>\r\n\r\n    <p>\r\n        افتتاحی تقریب کا اختتام برانچ میں عوام کی جانب سے نئے اکاؤنٹس کھولنے اور بینک آف آزاد جموں\r\n        و کشمیر کے عوام دوست اقدامات کو سراہنے کے ساتھ ہوا۔\r\n    </p>\r\n\r\n</div>', 'Bank of AJK Expands Banking Network with New Branch at Gujjar Bandi\r\n\r\n    \r\n        The Bank of AJK has expanded its banking network by inaugurating a new branch at\r\n        Gujjar Bandi, bri...', 'news-images/3szo7jBIO4jIW1BQMr78C0noCvshhvTVDdq4xtaL.jpg', '2026-05-14', 0, 'banking', 'bank-of-ajk-expands-banking-network-with-new-branch-at-gujjar-bandi', 1, '2026-09-01 11:36:04', '2026-09-11 06:09:50'),
(46, 'Bank of AJK Reaches Historic Milestone, Formally Applies to State Bank of Pakistan for Scheduled Bank Status', '<div class=\"press-release\" dir=\"ltr\" lang=\"en\">\r\n\r\n    <h1>\r\n        Bank of AJK Reaches Historic Milestone, Formally Applies to State Bank of Pakistan for Scheduled Bank Status\r\n    </h1>\r\n\r\n    <p>\r\n        <strong>Muzaffarabad, June 1, 2026</strong>\r\n    </p>\r\n\r\n    <p>\r\n        The <strong>Bank of Azad Jammu &amp; Kashmir (BAJK)</strong> has reached a historic milestone in\r\n        its journey of growth and expansion by formally submitting an application to the\r\n        <strong>State Bank of Pakistan (SBP)</strong> on Monday, June 1, 2026, for obtaining a\r\n        Scheduled Bank License.\r\n    </p>\r\n\r\n    <p>\r\n        The application was submitted by representatives of the Bank of Azad Jammu &amp; Kashmir to\r\n        officials of the <strong>Banking Policy &amp; Regulations Department (BPRD)</strong> during a\r\n        meeting held at the State Bank of Pakistan\'s Head Office in Karachi.\r\n    </p>\r\n\r\n    <p>\r\n        With this significant development, the Bank of Azad Jammu &amp; Kashmir has become the\r\n        <strong>first government-owned bank of the Government of Azad Jammu &amp; Kashmir</strong>\r\n        to apply for Scheduled Bank status under the regulatory framework of the State Bank of Pakistan.\r\n    </p>\r\n\r\n    <p>\r\n        It is pertinent to mention that the Bank of Azad Jammu &amp; Kashmir was established in\r\n        <strong>2006</strong> under an Act passed by the Azad Jammu &amp; Kashmir Legislative Assembly.\r\n        Over the past two decades, the Bank has expanded its operations across Azad Kashmir and has\r\n        played a significant role in promoting financial inclusion, supporting business activities,\r\n        facilitating government transactions and contributing to the economic development of the region.\r\n    </p>\r\n\r\n    <p>\r\n        In preparation for obtaining Scheduled Bank status, the Bank implemented comprehensive reforms\r\n        and successfully fulfilled all major requirements prescribed by the State Bank of Pakistan.\r\n        These measures included increasing the <strong>Paid-up Capital</strong> to the minimum required\r\n        regulatory level, strengthening the corporate governance framework, implementing modern risk\r\n        management systems, upgrading information technology infrastructure, further strengthening the\r\n        <strong>Anti-Money Laundering and Countering Financing of Terrorism (AML/CFT)</strong> framework,\r\n        and preparing a comprehensive strategic business plan aligned with regulatory requirements.\r\n    </p>\r\n\r\n    <p>\r\n        In accordance with the procedure prescribed by the State Bank of Pakistan, the application will\r\n        undergo a detailed review. The process will include assessment of the\r\n        <strong>fit and proper status of the Bank\'s Board of Directors and senior management</strong>,\r\n        review of the governance structure, operational preparedness and compliance with all relevant\r\n        regulatory requirements. The process is expected to take approximately <strong>eight weeks</strong>.\r\n    </p>\r\n\r\n    <p>\r\n        Subject to successful completion of the regulatory review and approval by the State Bank of\r\n        Pakistan, the Bank expects to obtain Scheduled Bank status by <strong>July 2026</strong>.\r\n    </p>\r\n\r\n    <h2>Statement by Acting President &amp; CEO</h2>\r\n\r\n    <p>\r\n        On the occasion, <strong>Shahid Shahzad Mir, Acting President and Chief Executive Officer of\r\n        the Bank of Azad Jammu &amp; Kashmir</strong>, said:\r\n    </p>\r\n\r\n    <blockquote>\r\n        “The submission of the application for Scheduled Bank status is a landmark in the history of\r\n        the Bank and a major development for the financial sector of Azad Jammu &amp; Kashmir. This\r\n        achievement reflects the vision and strong support of the Government of Azad Jammu &amp; Kashmir,\r\n        the guidance of our Board of Directors, the patronage of the Chief Secretary, Government of\r\n        Azad Jammu &amp; Kashmir, and the Secretary Finance, Government of Azad Jammu &amp; Kashmir, as\r\n        well as the tireless efforts, dedication and professional commitment of our employees and the\r\n        cooperation of our valued customers. We are committed to meeting all regulatory expectations\r\n        and requirements of the State Bank of Pakistan and fulfilling our responsibilities in accordance\r\n        with the highest standards of regulatory compliance and banking services.”\r\n    </blockquote>\r\n\r\n    <p>\r\n        Following the attainment of Scheduled Bank status, the Bank intends to significantly expand\r\n        its operations beyond Azad Jammu &amp; Kashmir into various cities across Pakistan and explore\r\n        opportunities for international expansion.\r\n    </p>\r\n\r\n    <p>\r\n        For this purpose, the Bank plans to establish new branches, introduce modern and innovative\r\n        banking products, launch digital financial services and explore international expansion\r\n        opportunities to meet the financial needs of overseas Pakistanis and Kashmiris. However, all\r\n        such initiatives will remain subject to the relevant regulatory approvals.\r\n    </p>\r\n\r\n    <p>\r\n        This significant achievement is expected to enhance the Bank\'s capacity to mobilize deposits,\r\n        promote trade and business activities, expand investment opportunities, strengthen financial\r\n        inclusion and enable the Bank to play an even more effective role in the socio-economic\r\n        development of <strong>Azad Jammu &amp; Kashmir and Pakistan</strong>.\r\n    </p>\r\n\r\n    <p>\r\n        The Bank of Azad Jammu &amp; Kashmir extends its heartfelt gratitude to the\r\n        <strong>Government of Azad Jammu &amp; Kashmir, State Bank of Pakistan, valued customers,\r\n        partners, stakeholders and all employees</strong> for their continued support, trust and\r\n        encouragement throughout this historic journey.\r\n    </p>\r\n\r\n</div>\r\n<div class=\"press-release\" dir=\"rtl\" lang=\"ur\">\r\n\r\n    <h1>\r\n        بینک آف آزاد جموں و کشمیر نے تاریخی سنگِ میل عبور کرتے ہوئے شیڈولڈ بینک کا درجہ حاصل کرنے کے لیے اسٹیٹ بینک آف پاکستان میں باضابطہ درخواست جمع کرا دی\r\n    </h1>\r\n\r\n    <p>\r\n        <strong>مظفرآباد، یکم جون 2026ء</strong>\r\n    </p>\r\n\r\n    <p>\r\n        بینک آف آزاد جموں و کشمیر (BAJK) نے اپنی ترقی اور وسعت کے سفر میں ایک تاریخی سنگِ میل عبور کرتے\r\n        ہوئے پیر، یکم جون 2026ء کو اسٹیٹ بینک آف پاکستان میں شیڈولڈ بینک لائسنس کے حصول کے لیے باضابطہ\r\n        درخواست جمع کرا دی ہے۔\r\n    </p>\r\n\r\n    <p>\r\n        یہ درخواست بینک آف آزاد جموں و کشمیر کے نمائندگان نے کراچی میں اسٹیٹ بینک آف پاکستان کے\r\n        ہیڈکوارٹرز میں منعقدہ ایک اجلاس کے دوران بینکنگ پالیسی اینڈ ریگولیشنز ڈیپارٹمنٹ (BPRD) کے\r\n        حکام کو پیش کی۔\r\n    </p>\r\n\r\n    <p>\r\n        اس اہم پیش رفت کے ساتھ بینک آف آزاد جموں و کشمیر اسٹیٹ بینک آف پاکستان کے ریگولیٹری فریم ورک\r\n        کے تحت شیڈولڈ بینک کا درجہ حاصل کرنے کے لیے درخواست دینے والا\r\n        <strong>آزاد جموں و کشمیر حکومت کا پہلا ملکیتی بینک</strong> بن گیا ہے۔\r\n    </p>\r\n\r\n    <p>\r\n        یہ بات قابل ذکر ہے کہ بینک آف آزاد جموں و کشمیر کا قیام <strong>2006ء</strong> میں آزاد جموں و\r\n        کشمیر قانون ساز اسمبلی کے منظور کردہ ایک ایکٹ کے تحت عمل میں آیا تھا۔ گزشتہ دو دہائیوں کے\r\n        دوران بینک نے آزاد کشمیر بھر میں اپنے آپریشنز کو وسعت دی ہے اور مالیاتی شمولیت کے فروغ،\r\n        کاروباری سرگرمیوں کی معاونت، حکومتی لین دین کی سہولت اور خطے کی معاشی ترقی میں نمایاں کردار\r\n        ادا کیا ہے۔\r\n    </p>\r\n\r\n    <p>\r\n        شیڈولڈ بینک کا درجہ حاصل کرنے کی تیاری کے سلسلے میں بینک نے جامع اصلاحات نافذ کیں اور\r\n        اسٹیٹ بینک آف پاکستان کی جانب سے مقرر کردہ تمام اہم شرائط کامیابی سے پوری کیں۔ ان اقدامات\r\n        میں کم از کم مطلوبہ ریگولیٹری حد تک <strong>ادا شدہ سرمایہ (Paid-up Capital)</strong> میں\r\n        اضافہ، کارپوریٹ گورننس کے نظام کو مضبوط بنانا، جدید رسک مینجمنٹ سسٹمز کا نفاذ، انفارمیشن\r\n        ٹیکنالوجی انفراسٹرکچر کی جدید خطوط پر اپ گریڈیشن، اینٹی منی لانڈرنگ و دہشت گردی کی مالی\r\n        معاونت کی روک تھام <strong>(AML/CFT)</strong> کے فریم ورک کو مزید مؤثر بنانا اور ریگولیٹری\r\n        تقاضوں سے ہم آہنگ جامع اسٹریٹجک بزنس پلان کی تیاری شامل ہیں۔\r\n    </p>\r\n\r\n    <p>\r\n        اسٹیٹ بینک آف پاکستان کے مقررہ طریقہ کار کے مطابق درخواست کا تفصیلی جائزہ لیا جائے گا،\r\n        جس میں بینک کے بورڈ آف ڈائریکٹرز اور سینئر انتظامیہ کی <strong>فٹ اینڈ پراپر اسسمنٹ</strong>،\r\n        گورننس ڈھانچے، آپریشنل تیاریوں اور تمام متعلقہ ریگولیٹری تقاضوں کی تعمیل کا معائنہ شامل ہوگا۔\r\n        اس عمل کی متوقع مدت تقریباً <strong>آٹھ ہفتے</strong> ہے۔\r\n    </p>\r\n\r\n    <p>\r\n        ریگولیٹری جائزے کی کامیاب تکمیل اور اسٹیٹ بینک آف پاکستان کی منظوری سے مشروط، بینک کو توقع ہے\r\n        کہ وہ <strong>جولائی 2026ء</strong> تک شیڈولڈ بینک کا درجہ حاصل کر لے گا۔\r\n    </p>\r\n\r\n    <h2>قائم مقام صدر و چیف ایگزیکٹو آفیسر کا بیان</h2>\r\n\r\n    <p>\r\n        اس موقع پر بینک آف آزاد جموں و کشمیر کے قائم مقام صدر اور چیف ایگزیکٹو آفیسر\r\n        <strong>شاہد شہزاد میر</strong> نے کہا:\r\n    </p>\r\n\r\n    <blockquote>\r\n        “شیڈولڈ بینک کے درجہ کے حصول کے لیے درخواست جمع کرانا بینک کی تاریخ میں ایک سنگِ میل اور\r\n        آزاد جموں و کشمیر کے مالیاتی شعبے کے لیے ایک بڑی پیش رفت ہے۔ یہ کامیابی حکومتِ آزاد جموں و\r\n        کشمیر کے وژن اور بھرپور تعاون، ہمارے بورڈ آف ڈائریکٹرز کی رہنمائی، چیف سیکرٹری حکومتِ آزاد\r\n        جموں و کشمیر، سیکرٹری مالیات حکومتِ آزاد جموں و کشمیر کی سرپرستی، بینک کے ملازمین کی انتھک\r\n        محنت، لگن اور پیشہ ورانہ وابستگی اور معزز صارفین کے تعاون کی عکاس ہے۔ ہم اسٹیٹ بینک آف\r\n        پاکستان کی تمام ریگولیٹری توقعات اور تقاضوں پر پورا اترنے اور اعلیٰ ترین معیار، قوانین کی\r\n        پاسداری اور بینکاری خدمات کے مطابق اپنی ذمہ داریاں انجام دینے کے لیے پُرعزم ہیں۔”\r\n    </blockquote>\r\n\r\n    <p>\r\n        شیڈولڈ بینک کا درجہ حاصل ہونے کے بعد بینک آزاد جموں و کشمیر سے باہر پاکستان کے مختلف شہروں\r\n        اور بیرونِ ملک اپنی آپریشنز کو نمایاں طور پر وسعت دینے کا ارادہ رکھتا ہے۔ اس مقصد کے لیے نئی\r\n        شاخوں کا قیام، جدید اور اختراعی بینکاری مصنوعات کی فراہمی، ڈیجیٹل مالیاتی خدمات کا اجراء اور\r\n        اوورسیز پاکستانیوں اور کشمیریوں کی مالی ضروریات پوری کرنے کے لیے بین الاقوامی سطح پر توسیع\r\n        کے مواقع تلاش کیے جائیں گے، تاہم یہ تمام اقدامات متعلقہ ریگولیٹری منظوریوں سے مشروط ہوں گے۔\r\n    </p>\r\n\r\n    <p>\r\n        توقع ہے کہ اس اہم کامیابی سے بینک کی ڈپازٹس جمع کرنے کی صلاحیت میں اضافہ ہوگا، تجارت اور\r\n        کاروباری سرگرمیوں کو فروغ ملے گا، سرمایہ کاری کے مواقع وسیع ہوں گے، مالیاتی شمولیت مزید\r\n        مضبوط ہوگی اور بینک آزاد جموں و کشمیر اور پاکستان کی سماجی و معاشی ترقی میں پہلے سے زیادہ\r\n        مؤثر کردار ادا کر سکے گا۔\r\n    </p>\r\n\r\n    <p>\r\n        بینک آف آزاد جموں و کشمیر اس تاریخی سفر میں مسلسل تعاون، اعتماد اور حوصلہ افزائی پر\r\n        <strong>حکومتِ آزاد جموں و کشمیر، اسٹیٹ بینک آف پاکستان، اپنے معزز صارفین، شراکت داروں،\r\n        اسٹیک ہولڈرز اور تمام ملازمین</strong> کا تہہ دل سے شکریہ ادا کرتا ہے۔\r\n    </p>\r\n\r\n</div>', 'Bank of AJK Reaches Historic Milestone, Formally Applies to State Bank of Pakistan for Scheduled Bank Status\r\n    \r\n\r\n    \r\n        Muzaffarabad, June 1, 2026\r\n    \r\n\r\n    \r\n        ...', 'news-images/LkxSUNexAZmhmioL2jkDIHiiFd0nmSp1lsnDdVcs.jpg', '2026-06-01', 0, 'announcements', 'bank-of-ajk-reaches-historic-milestone-formally-applies-to-state-bank-of-pakistan-for-scheduled-bank-status', 1, '2026-09-01 11:43:13', '2026-09-11 06:09:03'),
(47, 'Malik Muhammad Babar Ayyaz Assumes Charge as President CEO of Bank of Azad Jammu & Kashmir', '<div class=\"press-release\" dir=\"ltr\" lang=\"en\">\r\n\r\n    <h1>\r\n        Malik Muhammad Babar Ayyaz Assumes Charge as President &amp; CEO of Bank of Azad Jammu &amp; Kashmir\r\n    </h1>\r\n\r\n    <p>\r\n        <strong>Muzaffarabad, August 4, 2026</strong>\r\n    </p>\r\n\r\n    <p>\r\n        Mr. <strong>Malik Muhammad Babar Ayyaz</strong> has assumed charge as the President &amp; Chief\r\n        Executive Officer (CEO) of the <strong>Bank of Azad Jammu &amp; Kashmir (BAJK)</strong>.\r\n        A seasoned banking professional with over <strong>27 years of diverse experience</strong> in\r\n        Pakistan\'s financial sector, Mr. Ayyaz brings extensive expertise in corporate banking,\r\n        commercial banking, Islamic banking, SME finance, strategic planning, business transformation,\r\n        and institutional leadership.\r\n    </p>\r\n\r\n    <p>\r\n        Prior to joining BAJK, Mr. Ayyaz served for nearly <strong>17 years at The Bank of Punjab (BOP)</strong>,\r\n        where he held several key leadership positions after serving at other private banks. During his\r\n        tenure at BOP, he played a pivotal role in restructuring the Bank\'s Corporate &amp; Investment\r\n        Banking and was instrumental in establishing and strengthening its SME &amp; Commercial Banking\r\n        businesses, contributing significantly to the Bank\'s growth and strategic transformation.\r\n    </p>\r\n\r\n    <p>\r\n        Mr. Ayyaz holds an <strong>Executive MBA from the Lahore University of Management Sciences (LUMS)</strong>,\r\n        graduating with distinction and earning a place on the Dean\'s Honour Roll. His academic background,\r\n        combined with extensive leadership experience, reflects a strong commitment to excellence and\r\n        continuous professional development.\r\n    </p>\r\n\r\n    <h2>Statement by Chairman BAJK</h2>\r\n\r\n    <p>\r\n        Speaking on the occasion of assuming office, <strong>Chief Secretary, Government of the State of\r\n        Jammu &amp; Kashmir and Chairman BAJK, Mr. Khushkal Khan</strong>, said:\r\n    </p>\r\n\r\n    <blockquote>\r\n        “I congratulate the BAJK team on having a professional banker with extensive experience in\r\n        priority sector lending. We look forward to BAJK\'s enhanced role in financial inclusion,\r\n        SME empowerment and taking the Bank to the next level. I also see this as an important first\r\n        step in BAJK\'s journey towards a nationwide commercial banking license.”\r\n    </blockquote>\r\n\r\n    <h2>Statement by President &amp; CEO</h2>\r\n\r\n    <p>\r\n        President &amp; Chief Executive Officer, <strong>Mr. Malik Muhammad Babar Ayyaz</strong>, added:\r\n    </p>\r\n\r\n    <blockquote>\r\n        “I am honoured to join the Bank of Azad Jammu &amp; Kashmir at an important stage in its journey\r\n        of growth and transformation. BAJK has earned a distinguished reputation as the premier\r\n        state-owned financial institution of Azad Jammu &amp; Kashmir, built on the trust of its\r\n        customers and the dedication of its people.\r\n    </blockquote>\r\n\r\n    <blockquote>\r\n        Together with the Board of Directors, management, employees, and all our stakeholders, we will\r\n        work to further strengthen the Bank\'s financial performance, accelerate digital transformation,\r\n        expand Islamic and SME banking, enhance customer experience, reinforce governance and risk\r\n        management practices, and promote greater financial inclusion across the region.\r\n    </blockquote>\r\n\r\n    <blockquote>\r\n        Our focus will remain on innovation, operational excellence, sustainable growth, and creating\r\n        lasting value for our customers, communities, and the economy of Azad Jammu &amp; Kashmir.”\r\n    </blockquote>\r\n\r\n</div>\r\n<div class=\"press-release\" dir=\"rtl\" lang=\"ur\">\r\n\r\n    <h1>\r\n        ملک محمد بابر ایاز نے بینک آف آزاد جموں و کشمیر کے صدر و چیف ایگزیکٹو آفیسر کا عہدہ سنبھال لیا\r\n    </h1>\r\n\r\n    <p>\r\n        <strong>مظفرآباد، 03 اگست 2026</strong>\r\n    </p>\r\n\r\n    <p>\r\n        جناب <strong>ملک محمد بابر ایاز</strong> پاکستان کے مالیاتی شعبے کے ایک ممتاز اور تجربہ کار\r\n        بینکار ہیں، جنہیں بینکاری کے میدان میں <strong>27 سال سے زائد تجربہ</strong> حاصل ہے۔ انہیں\r\n        کارپوریٹ بینکاری، کمرشل بینکاری، اسلامی بینکاری، چھوٹے اور درمیانے درجے کے کاروبار (SMEs) کی\r\n        فنانسنگ، اسٹریٹجک منصوبہ بندی، کاروباری تبدیلی (Business Transformation) اور ادارہ جاتی قیادت\r\n        میں نمایاں مہارت حاصل ہے۔\r\n    </p>\r\n\r\n    <p>\r\n        بینک آف آزاد جموں و کشمیر میں شمولیت سے قبل، آپ تقریباً <strong>17 برس تک دی بینک آف پنجاب\r\n        (BOP)</strong> سے وابستہ رہے، جہاں انہوں نے مختلف نجی بینکوں میں خدمات انجام دینے کے بعد\r\n        متعدد اہم قائدانہ عہدوں پر ذمہ داریاں نبھائیں۔ بینک آف پنجاب میں اپنے دورِ ملازمت کے دوران\r\n        انہوں نے بینک کے کارپوریٹ اینڈ انویسٹمنٹ بینکنگ ڈویژن کی تنظیمِ نو میں کلیدی کردار ادا کیا،\r\n        جبکہ ایس ایم ای اور کمرشل بینکنگ کے شعبوں کے قیام، استحکام اور ترقی میں بھی نمایاں خدمات\r\n        سرانجام دیں، جس سے بینک کی کاروباری وسعت اور اسٹریٹجک ترقی میں اہم پیش رفت ہوئی۔\r\n    </p>\r\n\r\n    <p>\r\n        انہوں نے <strong>لاہور یونیورسٹی آف مینجمنٹ سائنسز (LUMS)</strong> سے ایگزیکٹو ایم بی اے کی\r\n        ڈگری حاصل کی، جہاں انہوں نے نمایاں کارکردگی کا مظاہرہ کرتے ہوئے ڈینز آنر رول میں جگہ بنائی۔\r\n        ان کا مضبوط تعلیمی پس منظر، وسیع قائدانہ تجربہ اور پیشہ ورانہ مہارت ان کے معیارِ کار، مسلسل\r\n        سیکھنے کے جذبے اور بہترین قیادت کے عکاس ہیں۔\r\n    </p>\r\n\r\n    <h2>چیئرمین بینک آف آزاد جموں و کشمیر کا بیان</h2>\r\n\r\n    <p>\r\n        اس موقع پر چیف سیکرٹری حکومتِ آزاد ریاست جموں و کشمیر اور چیئرمین بینک آف آزاد جموں و کشمیر،\r\n        <strong>جناب خوشحال خان</strong> نے کہا:\r\n    </p>\r\n\r\n    <blockquote>\r\n        \"میں بینک آف آزاد جموں و کشمیر کی ٹیم کو مبارکباد پیش کرتا ہوں کہ انہیں وسیع تجربہ رکھنے والے\r\n        ایک پیشہ ور بینکار کی قیادت میسر آئی ہے۔ ہمیں یقین ہے کہ ان کی سربراہی میں بینک مالیاتی\r\n        شمولیت (Financial Inclusion)، چھوٹے اور درمیانے درجے کے کاروبار (SMEs) کو بااختیار بنانے\r\n        اور بینک کو ترقی کی نئی منازل تک پہنچانے میں مزید مؤثر کردار ادا کرے گا۔ میں اسے بینک آف\r\n        آزاد جموں و کشمیر کے ملک گیر کمرشل بینکنگ لائسنس کے حصول کے سفر کی جانب ایک اہم پیش رفت\r\n        بھی سمجھتا ہوں۔\"\r\n    </blockquote>\r\n\r\n    <h2>صدر و چیف ایگزیکٹو آفیسر کا بیان</h2>\r\n\r\n    <p>\r\n        اس موقع پر اپنے خیالات کا اظہار کرتے ہوئے صدر و چیف ایگزیکٹو آفیسر،\r\n        <strong>ملک محمد بابر ایاز</strong> نے کہا:\r\n    </p>\r\n\r\n    <blockquote>\r\n        \"بینک آف آزاد جموں و کشمیر کی ترقی اور ادارہ جاتی تبدیلی کے اس اہم مرحلے پر اس ادارے کا حصہ\r\n        بننا میرے لیے ایک اعزاز ہے۔ بینک نے اپنے صارفین کے اعتماد، ملازمین کی محنت اور پیشہ ورانہ\r\n        خدمات کے باعث آزاد جموں و کشمیر کے ممتاز سرکاری مالیاتی ادارے کی حیثیت سے ایک قابلِ احترام\r\n        مقام حاصل کیا ہے۔\r\n    </blockquote>\r\n\r\n    <blockquote>\r\n        مجھے یقین ہے کہ بورڈ آف ڈائریکٹرز، انتظامیہ، ملازمین اور تمام اسٹیک ہولڈرز کے تعاون سے ہم\r\n        بینک کی مالی کارکردگی کو مزید مضبوط بنائیں گے، ڈیجیٹل بینکاری کے عمل کو تیز کریں گے، اسلامی\r\n        اور ایس ایم ای بینکاری کو وسعت دیں گے، صارفین کو مزید معیاری خدمات فراہم کریں گے، کارپوریٹ\r\n        گورننس اور رسک مینجمنٹ کے نظام کو مزید مستحکم کریں گے اور خطے میں مالیاتی شمولیت کو فروغ\r\n        دیں گے۔\r\n    </blockquote>\r\n\r\n    <blockquote>\r\n        ہماری ترجیح جدت، آپریشنل بہترین کارکردگی، پائیدار ترقی اور اپنے صارفین، مقامی آبادی اور\r\n        آزاد جموں و کشمیر کی معیشت کے لیے دیرپا قدر پیدا کرنا ہوگی۔\"\r\n    </blockquote>\r\n\r\n</div>', '\r\n\r\n    \r\n        Malik Muhammad Babar Ayyaz Assumes Charge as President &amp; CEO of Bank of Azad Jammu &amp; Kashmir\r\n    \r\n\r\n    \r\n        Muzaffarabad, August 4, 2026\r\n    \r\n\r\n    \r\n        Mr. Ma...', 'news-images/6gPwqzgpXaAnqCBl5ocKi9Qp0ehsW4Dp8UcWeo2E.jpg', '2026-08-04', 1, 'announcements', 'malik-muhammad-babar-ayyaz-assumes-charge-as-president-ceo-of-bank-of-azad-jammu-kashmir', 1, '2026-09-01 11:49:16', '2026-09-01 11:49:16'),
(48, 'BAJK Board of Directors Holds 104th Meeting in Muzaffarabad', '<article class=\"news-article english-news\">\r\n\r\n    <h1>BAJK Board of Directors Holds 104th Meeting in Muzaffarabad</h1>\r\n\r\n    <h2>Board Reaffirms Commitment to Good Governance and Enhanced Customer Service</h2>\r\n\r\n    <div class=\"news-meta\">\r\n        <strong>Muzaffarabad</strong><br>\r\n        <strong>September 02, 2026</strong>\r\n    </div>\r\n\r\n    <p>\r\n        The 104th meeting of the Board of Directors of the \r\n        <strong>Bank of Azad Jammu &amp; Kashmir (BAJK)</strong> was held on Wednesday \r\n        in Muzaffarabad under the chairmanship of Mr. Khushal Khan, SI, T. St., \r\n        Chairman, Board of Directors, BAJK, who is also serving as the Chief Secretary, \r\n        Government of Azad Jammu &amp; Kashmir.\r\n    </p>\r\n\r\n    <p>\r\n        The meeting was attended by Mr. Babar Ayyaz, President &amp; Chief Executive \r\n        Officer, BAJK; Mr. Hasan Masud, Secretary Finance, Government of AJK; \r\n        Mr. Muhammad Idrees Abbasi, Secretary Law, Government of AJK; \r\n        Mr. Adnan Khursheed, Secretary Industries, Government of AJK; \r\n        Mr. Mubashar Nabi, Director; Ms. Bushra Naz Malik, Director; \r\n        Mr. Khurram Haris, Director, and Mr. Adnan Ullah Khan, Company Secretary.\r\n    </p>\r\n\r\n    <p>\r\n        At the outset, the Chairman and members of the Board warmly welcomed and \r\n        congratulated Mr. Babar Ayyaz on assuming charge as the President &amp; \r\n        Chief Executive Officer of BAJK. The Board expressed confidence that, \r\n        under his experienced and professional leadership and with the guidance \r\n        of the Board, the Bank would continue to strengthen its institutional \r\n        capacity and banking services.\r\n    </p>\r\n\r\n    <p>\r\n        The Board considered and deliberated upon a number of important agenda \r\n        items relating to the Bank’s business, operations, governance and future \r\n        direction. Important decisions were taken in the best interest of the \r\n        Bank, its customers and other stakeholders.\r\n    </p>\r\n\r\n    <p>\r\n        The meeting emphasized the importance of corporate governance, financial \r\n        discipline, transparency, institutional strengthening and professional \r\n        excellence. Special emphasis was also laid on improving customer service \r\n        and service delivery and responding effectively to the evolving needs of \r\n        customers.\r\n    </p>\r\n\r\n    <p>\r\n        The Chairman appreciated the efforts of the management and employees and \r\n        emphasized the importance of collective commitment, prudent decision-making, \r\n        innovation and professionalism in achieving the Bank’s strategic objectives.\r\n    </p>\r\n\r\n    <p>\r\n        Speaking on the occasion, Mr. Babar Ayyaz, President &amp; CEO, BAJK, thanked \r\n        the Chairman and members of the Board for their warm welcome, confidence \r\n        and guidance. He reaffirmed his commitment to work closely with the Board, \r\n        management and employees, with a focus on customer service, operational \r\n        excellence, technological modernization and sound governance.\r\n    </p>\r\n\r\n    <p>\r\n        The meeting concluded with a shared resolve to safeguard stakeholders’ \r\n        interests, enhance public confidence and further strengthen BAJK as a \r\n        professionally managed and customer focused financial institution.\r\n    </p>\r\n\r\n</article>\r\n\r\n\r\n<article class=\"news-article urdu-news\" dir=\"rtl\" lang=\"ur\">\r\n\r\n    <h1>بینک آف آزاد جموں و کشمیر کے بورڈ آف ڈائریکٹرز کا 104واں اجلاس مظفرآباد میں منعقد</h1>\r\n\r\n    <h2>بورڈ کا گڈ گورننس اور صارفین کو بہتر خدمات کی فراہمی کے عزم کا اعادہ</h2>\r\n\r\n    <div class=\"news-meta\">\r\n        <strong>مظفرآباد</strong><br>\r\n        <strong>02 ستمبر 2026ء</strong>\r\n    </div>\r\n\r\n    <p>\r\n        بینک آف آزاد جموں و کشمیر (BAJK) کے بورڈ آف ڈائریکٹرز کا 104واں اجلاس \r\n        بدھ کے روز مظفرآباد میں منعقد ہوا۔ اجلاس کی صدارت مسٹر خوشحال خان، \r\n        ایس آئی، ٹی۔ ایس ٹی۔، چیئرمین بورڈ آف ڈائریکٹرز، بینک آف آزاد جموں و کشمیر \r\n        نے کی، جو حکومت آزاد جموں و کشمیر کے چیف سیکرٹری کے فرائض بھی انجام دے رہے ہیں۔\r\n    </p>\r\n\r\n    <p>\r\n        اجلاس میں مسٹر بابر ایاز، صدر و چیف ایگزیکٹو آفیسر، بینک آف آزاد جموں و کشمیر؛ \r\n        مسٹر حسن مسعود، سیکرٹری خزانہ، حکومت آزاد جموں و کشمیر؛ \r\n        مسٹر محمد ادریس عباسی، سیکرٹری قانون، حکومت آزاد جموں و کشمیر؛ \r\n        مسٹر عدنان خورشید، سیکرٹری صنعت، حکومت آزاد جموں و کشمیر؛ \r\n        مسٹر مبشر نبی، ڈائریکٹر؛ مس بشریٰ ناز ملک، ڈائریکٹر؛ \r\n        مسٹر خرم حارث، ڈائریکٹر؛ اور مسٹر عدنان اللہ خان، کمپنی سیکرٹری نے شرکت کی۔\r\n    </p>\r\n\r\n    <p>\r\n        اجلاس کے آغاز پر چیئرمین اور بورڈ کے اراکین نے مسٹر بابر ایاز کو \r\n        بینک آف آزاد جموں و کشمیر کے صدر و چیف ایگزیکٹو آفیسر کا منصب سنبھالنے \r\n        پر پرتپاک خیرمقدم اور مبارکباد پیش کی۔ بورڈ نے اس اعتماد کا اظہار کیا کہ \r\n        ان کی تجربہ کار اور پیشہ ورانہ قیادت اور بورڈ کی رہنمائی میں بینک اپنی \r\n        ادارہ جاتی استعداد اور بینکاری خدمات کو مزید مستحکم کرے گا۔\r\n    </p>\r\n\r\n    <p>\r\n        بورڈ نے بینک کے کاروبار، آپریشنز، گورننس اور مستقبل کی سمت سے متعلق متعدد \r\n        اہم ایجنڈا آئٹمز پر غور و خوض کیا۔ بینک، اس کے صارفین اور دیگر اسٹیک ہولڈرز \r\n        کے بہترین مفاد میں اہم فیصلے کیے گئے۔\r\n    </p>\r\n\r\n    <p>\r\n        اجلاس میں کارپوریٹ گورننس، مالیاتی نظم و ضبط، شفافیت، ادارہ جاتی استحکام \r\n        اور پیشہ ورانہ کارکردگی کی اہمیت پر زور دیا گیا۔ صارفین کو بہتر خدمات اور \r\n        سروس ڈیلیوری میں بہتری لانے کے ساتھ ساتھ صارفین کی بدلتی ہوئی ضروریات کا \r\n        مؤثر انداز میں جواب دینے پر بھی خصوصی توجہ دی گئی۔\r\n    </p>\r\n\r\n    <p>\r\n        چیئرمین نے بینک کی انتظامیہ اور ملازمین کی کاوشوں کو سراہا اور بینک کے \r\n        اسٹریٹجک اہداف کے حصول کے لیے اجتماعی عزم، دانشمندانہ فیصلہ سازی، \r\n        جدت اور پیشہ ورانہ طرزِ عمل کی اہمیت پر زور دیا۔\r\n    </p>\r\n\r\n    <p>\r\n        اس موقع پر گفتگو کرتے ہوئے بینک آف آزاد جموں و کشمیر کے صدر و چیف ایگزیکٹو \r\n        آفیسر مسٹر بابر ایاز نے چیئرمین اور بورڈ کے اراکین کا پرتپاک خیرمقدم، \r\n        اعتماد اور رہنمائی پر شکریہ ادا کیا۔ انہوں نے بورڈ، انتظامیہ اور ملازمین \r\n        کے ساتھ مل کر کام کرنے کے عزم کا اعادہ کیا، جس میں صارفین کو بہتر خدمات، \r\n        آپریشنل بہترین کارکردگی، ٹیکنالوجی کو جدید بنانے اور مضبوط گورننس پر خصوصی \r\n        توجہ مرکوز کی جائے گی۔\r\n    </p>\r\n\r\n    <p>\r\n        اجلاس کا اختتام اس مشترکہ عزم کے ساتھ ہوا کہ اسٹیک ہولڈرز کے مفادات کا \r\n        تحفظ کیا جائے گا، عوامی اعتماد میں اضافہ کیا جائے گا اور بینک آف آزاد \r\n        جموں و کشمیر کو ایک پیشہ ورانہ انداز میں منظم اور صارفین پر مرکوز مالیاتی \r\n        ادارے کے طور پر مزید مضبوط بنایا جائے گا۔\r\n    </p>\r\n\r\n</article>', '\r\n\r\n    BAJK Board of Directors Holds 104th Meeting in Muzaffarabad\r\n\r\n    Board Reaffirms Commitment to Good Governance and Enhanced Customer Service\r\n\r\n    \r\n        Muzaffarabad\r\n        September ...', 'news-images/l24VQhlsGwAyATPjdPoycvhPJG0G99tB5nkycBGV.jpg', '2026-09-03', 1, 'updates', 'bajk-board-of-directors-holds-104th-meeting-in-muzaffarabad', 1, '2026-09-03 04:59:12', '2026-09-03 04:59:12'),
(49, 'Prime Minister AJK Reviews BAJK Initiatives for Youth Entrepreneurship and Employment', '<article dir=\"ltr\" style=\"text-align: left;\">\n\n    <h1>Prime Minister Azad Jammu and Kashmir Reviews Bank of Azad Jammu and Kashmir Initiatives for Youth Business and Employment</h1>\n\n    <div class=\"news-meta\">\n        <strong>Islamabad</strong>\n    </div>\n\n    <p>\n        Prime Minister Azad Jammu and Kashmir Barrister Iftikhar Gilani chaired a\n        meeting of the <strong>Bank of Azad Jammu and Kashmir (BAJK)</strong> and\n        reviewed initiatives aimed at promoting youth entrepreneurship and employment.\n    </p>\n\n    <p>\n        President &amp; CEO Babar Ayyaz briefed the Prime Minister on the Bank’s\n        performance, operations and key initiatives. The meeting discussed introducing\n        easy term financing schemes for youth, skilled individuals and aspiring\n        entrepreneurs to promote self-employment, small businesses and industrial\n        development in Azad Jammu and Kashmir.\n    </p>\n\n    <p>\n        The Prime Minister emphasized expanding access to financing opportunities\n        for young, skilled and unemployed people to support sustainable employment\n        and economic activity in the region.\n    </p>\n\n</article>\n\n<article dir=\"rtl\" style=\"text-align: right;\">\n\n    <h1>وزیر اعظم آزاد جموں و کشمیر کا بینک آف آزاد جموں و کشمیر کے نوجوانوں کے لیے کاروبار اور روزگار کے اقدامات کا جائزہ</h1>\n\n    <div class=\"news-meta\">\n        <strong>اسلام آباد</strong>\n    </div>\n\n    <p>\n        وزیر اعظم آزاد جموں و کشمیر بیرسٹر افتخار گیلانی نے بینک آف آزاد جموں و کشمیر\n        (BAJK) کے ایک اجلاس کی صدارت کی اور نوجوانوں میں کاروباری سرگرمیوں اور\n        روزگار کے فروغ کے لیے بینک کی جانب سے کیے جانے والے اقدامات کا جائزہ لیا۔\n    </p>\n\n    <p>\n        صدر و چیف ایگزیکٹو آفیسر بینک آف آزاد جموں و کشمیر، بابر ایاز نے وزیر اعظم\n        کو بینک کی کارکردگی، آپریشنز اور اہم اقدامات کے بارے میں بریفنگ دی۔ اجلاس\n        میں نوجوانوں، ہنرمند افراد اور کاروبار شروع کرنے کے خواہشمند افراد کے لیے\n        آسان شرائط پر ٹرم فنانسنگ اسکیمیں متعارف کرانے پر غور کیا گیا تاکہ آزاد\n        جموں و کشمیر میں خود روزگاری، چھوٹے کاروبار اور صنعتی ترقی کو فروغ دیا جا سکے۔\n    </p>\n\n    <p>\n        وزیر اعظم نے نوجوان، ہنرمند اور بے روزگار افراد کے لیے مالی معاونت اور\n        فنانسنگ کے مواقع تک رسائی کو مزید وسعت دینے کی ضرورت پر زور دیا تاکہ خطے\n        میں پائیدار روزگار اور معاشی سرگرمیوں کو فروغ دیا جا سکے۔\n    </p>\n\n</article>', 'Islamabad\r\n    \r\n\r\n    \r\n        Prime Minister Azad Jammu and Kashmir Barrister Iftikhar Gilani chaired a \r\n        meeting of the Bank of Azad Jammu and Kashmir (BAJK) and \r\n        review...', 'news-images/QXI1hVpPLWhhUkj2etbWG4JtS0I3OqvjJhskFMpk.jpg', '2026-09-10', 1, 'updates', 'prime-minister-ajk-reviews-bajk-initiatives-for-youth-entrepreneurship-and-employment', 1, '2026-09-11 06:06:33', '2026-09-24 10:03:03');
