(1, 1, 'Purpose', 'Don\'t worry about your urgent Domestic/personal/family needs like education of kids, marriage of children and medical requirements. BAJK provides you a hassle free finance against your salary.', 'text', 1, 1, '2025-07-17 08:08:31', '2025-07-17 08:08:31'),
(2, 1, 'Eligibility', 'Permanent employees of Government/semi Government Departments Autonomous Corporation with at least 01 year service.', 'text', 2, 1, '2025-07-17 08:08:31', '2025-07-17 08:08:31'),
