(12, 2, 'Eligibility', 'Must be AJK/Pakistani National.\n                             Permanent Employee of Government/Semi Government Departments and Autonomous Corporations with at least 03 years of service.\n                             Professional/Self Employed/Businessmen having established business for last three years.', 'text', 2, 1, '2025-07-17 08:08:31', '2025-07-17 08:08:31'),
