INSERT INTO `services` (`id`, `name`, `slug`, `description`, `icon`, `image`, `is_active`, `sort_order`, `meta_data`, `created_at`, `updated_at`) VALUES
(1, 'Lockers Facility', 'lockers-facility', 'Lockers\' facility is available in Main Branch Muzaffarabad, Main Branch Mirpur, Ladies Branch Mirpur, and CMH Road Branch Rawalakot in three different sizes Small, Medium and Large on annually fee with one time Security Deposit respectively to the size of locker. Locker holders need to have an account in the Bank.', '🔒', 'https://demo.bankajk.com/storage/services/lockers.png', 1, 1, NULL, '2025-07-17 08:08:31', '2025-07-17 08:08:31'),
(2, 'Utility Bills Collection', 'utility-bills-collection', 'Our bank\'s extensive network of branches is fully authorized to provide the convenient service of collecting electricity bills for our customers. You can easily pay your electricity bills at any of our bank branches, making it a hassle-free experience for your bill payment needs.', '💡', 'https://demo.bankajk.com/storage/services/utility-bill.png', 1, 2, NULL, '2025-07-17 08:08:31', '2025-07-17 08:08:31'),
(3, 'Services for AJK PSC', 'services-for-ajk-psc', 'At all our branches, we proudly offer the service of collecting the application fees for the AJK Public Service Commission from candidates. In addition to this, we also provide application forms, ensuring a seamless and efficient process for individuals applying for various positions. Trust us to assist you in your application process.', '🏛️', 'https://demo.bankajk.com/storage/services/psc.jpg', 1, 3, NULL, '2025-07-17 08:08:31', '2025-07-17 08:08:31'),
(4, 'Home Remittance', 'home-remittance', 'The bank has made adequate arrangements with major scheduled banks for the purpose of inter bank settlements and outward remittances. Under an arrangement with HBL all Banker Cheques issued by BAJK branches are payable on all branches of HBL.', '💸', 'https://demo.bankajk.com/storage/services/home-remittances.png', 1, 4, NULL, '2025-07-17 08:08:31', '2025-07-17 08:08:31');
