(2, 'Services', 'urgent', '💰', 'Enhanced Loan Limits: Gold loans up to 2 Million & Advance salary loans up to 3 Million from designated BAJK branches', 'from-blue-500 to-cyan-600', 'from-blue-50 to-cyan-50', 1, 2, '2025-07-17 08:08:31', '2025-07-17 08:08:31'),
